# 0104. 二叉树的最大深度

**题目描述**

给定一个二叉树的根节点 `root`，返回其最大深度。二叉树的最大深度是指从根节点到最远叶子节点的最长路径上的节点数。

```
示例：
输入: root = [3,9,20,null,null,15,7]
      3
     / \
    9  20
      /  \
     15   7
输出: 3
```

## 思路

- DFS：空节点深度为 0，当前深度为 `1+max(左深度,右深度)`。时间 O(n)，空间 O(h)。
- BFS：每处理一层，深度加一。时间 O(n)，空间 O(w)。

h 为树高，w 为最大层宽。

## 代码

### Python

```python
class Solution:
    # 方法：maxDepth；按题目要求处理输入并返回结果，核心算法见方法体。
    def maxDepth(self, root):
        # 思路一：后序遍历递归
        if root is None:
            return 0                          # 终止条件
        left_depth = self.maxDepth(root.left)   # 左子树深度
        right_depth = self.maxDepth(root.right) # 右子树深度
        return max(left_depth, right_depth) + 1  # 取较大值加上当前层

    # 方法：maxDepthBFS；按题目要求处理输入并返回结果，核心算法见方法体。
    def maxDepthBFS(self, root):
        # 思路二：层序遍历统计层数
        from collections import deque
        if root is None:
            return 0
        queue = deque([root])
        depth = 0
        while queue:
            size = len(queue)             # 当前层节点数
            for _ in range(size):
                node = queue.popleft()
                if node.left:
                    queue.append(node.left)
                if node.right:
                    queue.append(node.right)
            depth += 1                     # 处理完一层，深度加一
        return depth
```

二叉树节点定义：

```cpp
struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(NULL), right(NULL) {}
};
```

```python
class TreeNode:
    # 方法：__init__；按题目要求处理输入并返回结果，核心算法见方法体。
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right
```

### C++

```cpp
class Solution {
public:
    // 思路一：后序遍历递归，自底向上求高度
    // 方法：maxDepth；按题目要求处理输入并返回结果，核心算法见方法体。
    int maxDepth(TreeNode* root) {
        if (root == nullptr) return 0;             // 终止条件：空节点深度为0
        int leftDepth = maxDepth(root->left);      // 先求左子树深度
        int rightDepth = maxDepth(root->right);    // 再求右子树深度
        return max(leftDepth, rightDepth) + 1;     // 当前节点深度 = 较大子树深度 + 1（加上自己这一层）
    }

    // 思路二：层序遍历统计层数
    // 方法：maxDepthBFS；按题目要求处理输入并返回结果，核心算法见方法体。
    int maxDepthBFS(TreeNode* root) {
        if (root == nullptr) return 0;
        queue<TreeNode*> que;
        que.push(root);
        int depth = 0;
        while (!que.empty()) {
            int size = que.size();       // 记录当前层节点数
            for (int i = 0; i < size; i++) {
                TreeNode* node = que.front();
                que.pop();
                if (node->left) que.push(node->left);
                if (node->right) que.push(node->right);
            }
            depth++;                     // 处理完一层，深度加一
        }
        return depth;
    }
};
```


### Go

```go
// 思路一：后序遍历递归
// 方法：maxDepth；按题目要求处理输入并返回结果，核心算法见方法体。
func maxDepth(root *TreeNode) int {
    if root == nil {
        return 0 // 终止条件
    }
    leftDepth := maxDepth(root.Left)   // 左子树深度
    rightDepth := maxDepth(root.Right) // 右子树深度
    if leftDepth > rightDepth {
        return leftDepth + 1 // 取较大值加上当前层
    }
    return rightDepth + 1
}

// 思路二：层序遍历统计层数
// 方法：maxDepthBFS；按题目要求处理输入并返回结果，核心算法见方法体。
func maxDepthBFS(root *TreeNode) int {
    if root == nil {
        return 0
    }
    queue := []*TreeNode{root}
    depth := 0
    for len(queue) > 0 {
        size := len(queue) // 当前层节点数
        for i := 0; i < size; i++ {
            node := queue[0]
            queue = queue[1:]
            if node.Left != nil {
                queue = append(queue, node.Left)
            }
            if node.Right != nil {
                queue = append(queue, node.Right)
            }
        }
        depth++ // 处理完一层，深度加一
    }
    return depth
}
```

## 总结

- 求最大深度，说白了本质就是求"根节点的高度"，用后序遍历（自底向上）来做是天然合适的：先算出左右子树的高度，再用 max+1 合并成当前节点的高度。
- 用层序遍历数层数的思路更直观地对应了"深度等于层数"这个定义，拿 BFS 模板一层一层数就行。
- 两种解法复杂度都是 O(n)，实际面试中递归写法代码量更小，一般是更常用的首选。
- 这道题其实是"自底向上"递归模式的一个典型代表：不需要额外带参数从根往下传信息，而是让子树先算好结果，回溯的时候在父节点这里合并起来。

