### C++

```cpp
class Solution {
public:
    // remain 表示还需要凑够多少值才能达到目标，用值传递天然实现隐式回溯
    // 方法：traverse；按题目要求处理输入并返回结果，核心算法见方法体。
    bool traverse(TreeNode* node, int remain) {
        if (node == nullptr) return false;         // 空节点不构成有效路径
        remain -= node->val;                       // 用当前节点值抵消剩余目标值
        if (node->left == nullptr && node->right == nullptr) {
            // 到达叶子节点，判断是否恰好凑够目标值
            return remain == 0;
        }
        // 只要左子树或右子树中有一条路径满足条件即可
        return traverse(node->left, remain) || traverse(node->right, remain);
    }

    // 方法：hasPathSum；按题目要求处理输入并返回结果，核心算法见方法体。
    bool hasPathSum(TreeNode* root, int targetSum) {
        if (root == nullptr) return false;  // 空树不存在任何路径
        return traverse(root, targetSum);
    }
};
```


### Go

```go
// 方法：hasPathSum；按题目要求处理输入并返回结果，核心算法见方法体。
func hasPathSum(root *TreeNode, targetSum int) bool {
    if root == nil {
        return false // 空树不存在任何路径
    }
    return traverse(root, targetSum)
}

// remain 用值传递（Go中int是值类型），实现隐式回溯
// 方法：traverse；按题目要求处理输入并返回结果，核心算法见方法体。
func traverse(node *TreeNode, remain int) bool {
    if node == nil {
        return false // 空节点不构成有效路径
    }
    remain -= node.Val // 抵消剩余目标值
    if node.Left == nil && node.Right == nil {
        return remain == 0 // 叶子节点，判断是否恰好凑够
    }
    // 任一子树满足即可
    return traverse(node.Left, remain) || traverse(node.Right, remain)
}
```

## 总结

- 用"剩余目标值不断减去当前节点值，到叶子节点判断是不是恰好为0"这种写法，比维护"当前路径和再跟目标比较"更简洁，这两种逻辑是等价的。
- `remain` 这个参数以值传递的方式在递归中往下传，天然就实现了回溯，不需要手动去撤销状态，这是"隐式回溯"在实际题目里的一个具体应用，正好呼应了本系列里专门讲回溯思想的那篇方法论文档。
- 判断是不是存在满足条件的路径，只需要左子树或者右子树里**任意一条**满足就行，用逻辑或连接两次递归结果，不需要把两侧都探索完再去决策。
- 这道题跟 0257 题（收集所有路径）的区别在于：0257 要收集所有的路径，这道题只需要判断"是否存在"一条路径就够了，所以不需要显式维护一个路径列表，只需要维护一个数值即可，是同一类问题在不同要求下的简化版本。

07.二叉树/0116.填充每个节点的下一个右侧节点指针/0116.填充每个节点:
# 116. 填充每个节点的下一个右侧节点指针

**题目描述**

给定一棵**完美二叉树**（每一层的节点都被完全填充，且所有叶子节点都在同一层），树的每个节点除了 `left`、`right` 指针外，还多了一个 `next` 指针。请填充每个节点的 `next` 指针，让它指向其同一层的右侧下一个节点。如果找不到下一个右侧节点，则将 `next` 设为 `null`。初始状态下所有 `next` 指针都为 `null`。

```
示例：
输入: root = [1,2,3,4,5,6,7]
输出: [1,#,2,3,#,4,5,6,7,#]
解释: 给定的二叉树是完美二叉树，
      填充后：第 1 层的 1 的 next 指向 null（因为它是本层唯一节点）
      第 2 层：2 -> 3 -> null
      第 3 层：4 -> 5 -> 6 -> 7 -> null
      （# 表示每层的结尾，即该层最后一个节点的 next 是 null）
```

## 思路

- 利用 `next`：沿当前层连接下一层。`left.next=right`；若当前节点有后邻，令 `right.next=node.next.left`。逐层下降。时间 O(n)，空间 O(1)。
- BFS：逐层连接相邻节点，层尾指向空。时间 O(n)，空间 O(w)，w 为最大层宽。

## 代码

### Python

标准库没有针对这种"树内指针原地连接"问题的一行解法，本题只写手写实现：

```python
class Node:
    # 方法：__init__；按题目要求处理输入并返回结果，核心算法见方法体。
    def __init__(self, val=0, left=None, right=None, next=None):
        self.val = val
        self.left = left
        self.right = right
        self.next = next


class Solution:
    # 方法：connect；按题目要求处理输入并返回结果，核心算法见方法体。
    def connect(self, root: 'Node') -> 'Node':
        if root is None:
            return root

        level_start = root  # 当前层的最左节点，作为每层的起点
        while level_start.left is not None:  # 只要还有下一层（有左孩子）就继续
            cur = level_start  # cur 沿当前层的 next 链条向右移动
            while cur is not None:
                cur.left.next = cur.right  # 同一父节点下，左孩子 next 指向右孩子
                if cur.next is not None:
                    # 跨父节点连接：cur 的右孩子 next 指向 cur.next 的左孩子
                    cur.right.next = cur.next.left
                cur = cur.next  # 沿当前层链条前进，处理下一个父节点

            level_start = level_start.left  # 下移到下一层的最左节点

        return root
```

面试考察点：能不能想清楚"用上一层已经建好的 next 链条去推出下一层"这个归纳思路，尤其是"跨父节点连接"（也就是 `cur.right.next = cur.next.left`）这一步，这是这道题能从 O(n) 空间优化到 O(1) 空间的关键难点所在。

以下四种语言均采用**思路二（O(1) 空间，利用已连接的 next 层间递进）**实现。

### C++

```cpp
class Node {
public:
    int val;
    Node* left;
    Node* right;
    Node* next;

    Node() : val(0), left(nullptr), right(nullptr), next(nullptr) {}
    Node(int _val) : val(_val), left(nullptr), right(nullptr), next(nullptr) {}
};

class Solution {
public:
    Node* connect(Node* root) {
        if (root == nullptr) return root;

        Node* levelStart = root;  // 当前层的最左节点，作为每层的起点
        while (levelStart->left != nullptr) {  // 只要还有下一层（有左孩子）就继续
            Node* cur = levelStart;  // cur 沿当前层的 next 链条向右移动
            while (cur != nullptr) {
                cur->left->next = cur->right;  // 同一父节点下，左孩子的 next 指向右孩子
                if (cur->next != nullptr) {
                    // 跨父节点连接：cur 的右孩子 next 指向 cur.next 的左孩子
                    cur->right->next = cur->next->left;
                }
                cur = cur->next;  // 沿当前层链条前进，处理下一个父节点
            }
            levelStart = levelStart->left;  // 下移到下一层的最左节点
        }
        return root;
    }
};
```


### Go

```go
type Node struct {
    Val   int
    Left  *Node
    Right *Node
    Next  *Node
}

// 方法：connect；按题目要求处理输入并返回结果，核心算法见方法体。
func connect(root *Node) *Node {
    if root == nil {
        return root
    }

    levelStart := root // 当前层的最左节点，作为每层的起点
    for levelStart.Left != nil {  // 只要还有下一层就继续
        cur := levelStart // cur 沿当前层的 next 链条向右移动
        for cur != nil {
            cur.Left.Next = cur.Right // 同一父节点下，左孩子 next 指向右孩子
            if cur.Next != nil {
                // 跨父节点连接
                cur.Right.Next = cur.Next.Left
            }
            cur = cur.Next // 沿当前层链条前进
        }
        levelStart = levelStart.Left // 下移到下一层最左节点
    }
    return root
}
```

## 总结

- BFS 层序遍历是比较通用的解法，思路简单，但代价是要用 O(n) 的队列空间；而利用已经连好的 next 链条逐层往下推的方法呢，能做到 O(1) 额外空间，不过它的代价是只能用在完美二叉树这种同层节点数量固定、左右孩子必定成对出现的特殊结构上。
- O(1) 解法说白了本质就是一个归纳的过程：上一层的 next 链条连好了，才有条件去连下一层，根节点自己就构成了归纳的起点，因为它就一个节点，next 天然是 null。
- 这里最容易出错的地方就是"跨父节点连接"这一步（也就是 `cur.right.next = cur.next.left`），很多人容易只记得去连同一个父节点下的左右孩子，却忘了不同父节点之间在下一层其实也是相邻的，这一步必须单独处理才行。
- 整个循环可以这么理解：外层循环控制的是"还有没有下一层"（通过 `levelStart.left != nil` 来判断，完美二叉树能保证不会出现只有一侧孩子的怪情况），内层循环控制的是"在当前层内从左往右移动，顺便把下一层连好"。这两层循环分别对应着"层间往下推进"和"层内从左到右遍历"，把这两层循环各自的职责想清楚，是写对这道题代码的关键。

07.二叉树/0129.求根到叶子节点数字之和/0129.求根到叶子节点数字之和:
# 129. 求根到叶子节点数字之和

**题目描述**

给定一棵二叉树，树中每个节点都存放一个 0-9 的数字，每一条从根节点到叶子节点的路径都代表一个数字。求所有从根到叶子路径代表的数字之和。

```
示例：
输入: root = [1,2,3]
输出: 25
解释: 从根到叶子节点路径 1->2 代表数字 12，路径 1->3 代表数字 13，12 + 13 = 25
```

```
示例：
输入: root = [4,9,0,5,1]
输出: 1026
解释: 从根到叶子节点路径 4->9->5 代表数字 495
      从根到叶子节点路径 4->9->1 代表数字 491
      从根到叶子节点路径 4->0 代表数字 40
      495 + 491 + 40 = 1026
```

## 思路

DFS 传递路径数字：`num=num*10+node.val`；叶子返回 `num`，非叶子返回左右子树结果之和，空节点返回 0。

时间 O(n)，空间 O(h)，h 为树高。

## 代码

### Python

标准库层面没有直接对应"路径数字求和"的一行解法，本题以手写递归为主：

```python
class TreeNode:
    # 方法：__init__；按题目要求处理输入并返回结果，核心算法见方法体。
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


class Solution:
    # 方法：sumNumbers；按题目要求处理输入并返回结果，核心算法见方法体。
    def sumNumbers(self, root: TreeNode) -> int:
        # 方法：dfs；按题目要求处理输入并返回结果，核心算法见方法体。
        def dfs(node: TreeNode, cur_num: int) -> int:
            if node is None:
                return 0  # 空节点不产生数字
            cur_num = cur_num * 10 + node.val  # 拼接当前节点值到已有数字末位
            if node.left is None and node.right is None:
                return cur_num  # 叶子节点，数字已完整，直接返回
            # 非叶子节点，分别递归左右子树，两条路径的 cur_num 互不影响
            return dfs(node.left, cur_num) + dfs(node.right, cur_num)

        return dfs(root, 0)
```

面试考察点：面试官这里主要看你能不能想到"数字 = 父数字 * 10 + 当前值"这个递推式，还有能不能正确处理叶子节点的判定和空节点这些边界条件，而不是单纯看你会不会搭个递归框架。

### C++

```cpp
struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode() : val(0), left(nullptr), right(nullptr) {}
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
    TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
};

class Solution {
public:
    // 方法：sumNumbers；按题目要求处理输入并返回结果，核心算法见方法体。
    int sumNumbers(TreeNode* root) {
        return dfs(root, 0);  // 从根节点开始，初始已组成数字为 0
    }

private:
    // 方法：dfs；按题目要求处理输入并返回结果，核心算法见方法体。
    int dfs(TreeNode* node, int curNum) {
        if (node == nullptr) {
            return 0;  // 空节点不产生数字，直接返回 0
        }
        curNum = curNum * 10 + node->val;  // 把当前节点值拼接到已有数字末位
        if (node->left == nullptr && node->right == nullptr) {
            return curNum;  // 叶子节点，这条路径的数字已经完整，直接返回
        }
        // 非叶子节点，把 curNum 分别传给左右子树继续拼接，两条路径互不影响
        return dfs(node->left, curNum) + dfs(node->right, curNum);
    }
};
```


### Go

```go
