// 通用解法：O(n)
// 方法：countNodesGeneral；按题目要求处理输入并返回结果，核心算法见方法体。
func countNodesGeneral(root *TreeNode) int {
    if root == nil {
        return 0
    }
    leftCount := countNodesGeneral(root.Left)
    rightCount := countNodesGeneral(root.Right)
    return leftCount + rightCount + 1
}

// 优化解法：O(log n * log n)
// 方法：countNodes；按题目要求处理输入并返回结果，核心算法见方法体。
func countNodes(root *TreeNode) int {
    if root == nil {
        return 0
    }
    left, right := root.Left, root.Right
    leftDepth, rightDepth := 0, 0
    for left != nil { // 一直往左走到底，统计深度
        leftDepth++
        left = left.Left
    }
    for right != nil { // 一直往右走到底，统计深度
        rightDepth++
        right = right.Right
    }
    if leftDepth == rightDepth {
        return (1 << (leftDepth + 1)) - 1 // 满二叉树，公式计算
    }
    return countNodes(root.Left) + countNodes(root.Right) + 1 // 递归处理不满的一侧
}
```

## 总结

- 通用解法就是用后序遍历，累加左右子树的节点数就行，能适用于任意二叉树，复杂度是 O(n)。
- 优化解法呢，利用的是完全二叉树"最左路径深度等于最右路径深度时，一定是满二叉树"这个性质，把满二叉树那部分直接用公式 `2^depth - 1` 算出来，不用再一个个节点去访问了。
- 优化解法的递归深度是 O(log n)，每一层还需要花 O(log n) 的时间去统计左右深度，所以总的复杂度是 O(log n × log n)，比通用解法快得多。
- 这道题的价值就在于，它展示了"通用算法 + 特殊结构性质 = 更优解法"这样一种思路，算是数据结构性质应用类题目里比较有代表性的一道。

07.二叉树/0226.翻转二叉树/0226.翻转二叉树.md:
# 0226. 翻转二叉树

**题目描述**

给你一棵二叉树的根节点 `root`，翻转这棵二叉树，并返回其根节点（即每个节点的左右子树互换）。

```
示例：
输入: root = [4,2,7,1,3,6,9]
输出: [4,7,2,9,6,3,1]

     4                4
    / \              / \
   2   7    -->     7   2
  / \  / \          / \ / \
 1  3 6   9        9  6 3  1
```

## 思路

遍历每个节点并交换左右孩子。可用递归 DFS、显式栈或队列，确保每个节点只交换一次。

时间 O(n)；递归或 DFS 栈空间 O(h)，BFS 队列空间 O(w)。h 为树高，w 为最大层宽。

## 代码

### Python

```python
class Solution:
    # 方法：invertTree；按题目要求处理输入并返回结果，核心算法见方法体。
    def invertTree(self, root):
        # 递归法
        if root is None:
            return root                     # 终止条件
        root.left, root.right = root.right, root.left  # 交换左右孩子
        self.invertTree(root.left)          # 递归处理新的左子树
        self.invertTree(root.right)         # 递归处理新的右子树
        return root

    # 方法：invertTreeIterative；按题目要求处理输入并返回结果，核心算法见方法体。
    def invertTreeIterative(self, root):
        # 迭代法（栈模拟前序遍历）
        if root is None:
            return root
        stack = [root]
        while stack:
            node = stack.pop()
            node.left, node.right = node.right, node.left  # 访问即交换
            if node.left:
                stack.append(node.left)
            if node.right:
                stack.append(node.right)
        return root
```

二叉树节点定义：

```cpp
struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(NULL), right(NULL) {}
};
```

```python
class TreeNode:
    # 方法：__init__；按题目要求处理输入并返回结果，核心算法见方法体。
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right
```

### C++

```cpp
class Solution {
public:
    // 递归法（前序遍历：先交换，再递归左右子树）
    TreeNode* invertTree(TreeNode* root) {
        if (root == nullptr) return root;  // 终止条件：空节点无需处理
        swap(root->left, root->right);     // 交换当前节点的左右孩子
        invertTree(root->left);            // 递归处理新的左子树（原右子树）
        invertTree(root->right);           // 递归处理新的右子树（原左子树）
        return root;
    }

    // 迭代法（用栈模拟前序遍历，遇到节点就交换左右孩子）
    TreeNode* invertTreeIterative(TreeNode* root) {
        if (root == nullptr) return root;
        stack<TreeNode*> st;
        st.push(root);
        while (!st.empty()) {
            TreeNode* node = st.top();
            st.pop();
            swap(node->left, node->right);       // 访问即交换
            if (node->left) st.push(node->left);   // 交换后的左孩子（原右孩子）入栈
            if (node->right) st.push(node->right); // 交换后的右孩子（原左孩子）入栈
        }
        return root;
    }
};
```


### Go

```go
// 递归法
// 方法：invertTree；按题目要求处理输入并返回结果，核心算法见方法体。
func invertTree(root *TreeNode) *TreeNode {
    if root == nil {
        return root // 终止条件
    }
    root.Left, root.Right = root.Right, root.Left // 交换左右孩子
    invertTree(root.Left)                          // 递归处理新的左子树
    invertTree(root.Right)                         // 递归处理新的右子树
    return root
}

// 迭代法（栈模拟前序遍历）
// 方法：invertTreeIterative；按题目要求处理输入并返回结果，核心算法见方法体。
func invertTreeIterative(root *TreeNode) *TreeNode {
    if root == nil {
        return root
    }
    stack := []*TreeNode{root}
    for len(stack) > 0 {
        node := stack[len(stack)-1]
        stack = stack[:len(stack)-1]
        node.Left, node.Right = node.Right, node.Left // 访问即交换
        if node.Left != nil {
            stack = append(stack, node.Left)
        }
        if node.Right != nil {
            stack = append(stack, node.Right)
        }
    }
    return root
}
```

## 总结

- 翻转二叉树的本质就是对每个节点执行一次"交换左右孩子"的操作，任何能遍历到每个节点的方式都能完成这个任务。
- 前序、后序遍历都能正确翻转，唯独中序遍历不行——因为中序遍历在处理完根节点之后，会把已经处理过的子树当成新的子树再递归一次，这样一来就会导致重复翻转和漏翻转。
- 递归和迭代（用栈模拟）在本质上是等价的，选哪种写法主要看个人习惯，或者面试官有没有特别要求。
- 这道题是理解"遍历顺序会怎么影响算法正确性"的一个很好的例子，以后遇到需要修改树结构的题目，都要先想清楚该用哪种遍历顺序才不会产生副作用上的冲突。

07.二叉树/0235.二叉搜索树的最近公共祖先/0235.二叉搜索树的最近公共:
# 0235. 二叉搜索树的最近公共祖先

**题目描述**

给定一个二叉搜索树（BST），找到该树中两个指定节点 `p` 和 `q` 的最近公共祖先（LCA）。

```
示例：
输入: root = [6,2,8,0,4,7,9,null,null,3,5], p = 2, q = 8
输出: 6
解释: 节点 2 和节点 8 的最近公共祖先是根节点 6。
```

## 思路

利用 BST 有序性：两目标均小于当前值则向左，均大于则向右；否则当前节点即最近公共祖先，包括当前节点等于某个目标的情况。

时间 O(h)；递归空间 O(h)，迭代空间 O(1)，h 为树高。

## 代码

### Python

```python
class TreeNode:
    # 方法：__init__；按题目要求处理输入并返回结果，核心算法见方法体。
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


class Solution:
    # 方法：lowestCommonAncestor；按题目要求处理输入并返回结果，核心算法见方法体。
    def lowestCommonAncestor(self, root: TreeNode, p: TreeNode, q: TreeNode) -> TreeNode:
        # 递归写法
        if p.val < root.val and q.val < root.val:
            return self.lowestCommonAncestor(root.left, p, q)  # 都比当前节点小，往左走
        if p.val > root.val and q.val > root.val:
            return self.lowestCommonAncestor(root.right, p, q)  # 都比当前节点大，往右走
        return root  # 分岔点，即为答案

    # 方法：lowestCommonAncestorIterative；按题目要求处理输入并返回结果，核心算法见方法体。
    def lowestCommonAncestorIterative(self, root: TreeNode, p: TreeNode, q: TreeNode) -> TreeNode:
        # 迭代写法
        node = root
        while node is not None:
            if p.val < node.val and q.val < node.val:
                node = node.left
            elif p.val > node.val and q.val > node.val:
                node = node.right
            else:
                return node  # 分岔点
        return None
```

二叉树节点定义：

```cpp
struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(NULL), right(NULL) {}
};
```

### C++

```cpp
class Solution {
public:
    // 递归写法
    TreeNode* lowestCommonAncestor(TreeNode* root, TreeNode* p, TreeNode* q) {
        if (p->val < root->val && q->val < root->val) {
            return lowestCommonAncestor(root->left, p, q);  // 都比当前节点小，往左走
        }
        if (p->val > root->val && q->val > root->val) {
            return lowestCommonAncestor(root->right, p, q); // 都比当前节点大，往右走
        }
        return root; // 分岔点（或其中一个等于当前节点），当前节点即为答案
    }

    // 迭代写法：不需要递归栈
    TreeNode* lowestCommonAncestorIterative(TreeNode* root, TreeNode* p, TreeNode* q) {
        TreeNode* node = root;
        while (node != nullptr) {
            if (p->val < node->val && q->val < node->val) {
                node = node->left; // 都比当前节点小，往左走
            } else if (p->val > node->val && q->val > node->val) {
                node = node->right; // 都比当前节点大，往右走
            } else {
                return node; // 分岔点，即为答案
            }
        }
        return nullptr;
    }
};
```


### Go

```go
type TreeNode struct {
    Val   int
    Left  *TreeNode
    Right *TreeNode
}

// 递归写法
// 方法：lowestCommonAncestor；按题目要求处理输入并返回结果，核心算法见方法体。
func lowestCommonAncestor(root, p, q *TreeNode) *TreeNode {
    if p.Val < root.Val && q.Val < root.Val {
        return lowestCommonAncestor(root.Left, p, q) // 往左走
    }
    if p.Val > root.Val && q.Val > root.Val {
        return lowestCommonAncestor(root.Right, p, q) // 往右走
    }
    return root // 分岔点，即为答案
}

// 迭代写法
// 方法：lowestCommonAncestorIterative；按题目要求处理输入并返回结果，核心算法见方法体。
func lowestCommonAncestorIterative(root, p, q *TreeNode) *TreeNode {
    node := root
    for node != nil {
        if p.Val < node.Val && q.Val < node.Val {
            node = node.Left
        } else if p.Val > node.Val && q.Val > node.Val {
            node = node.Right
        } else {
            return node // 分岔点
        }
    }
    return nil
}
```

## 总结

- 跟 0236 那种普通二叉树的解法比起来，BST 解法不需要用后序遍历去回溯，只要根据 `p`、`q` 的值和当前节点值的大小关系，就能直接判断该往哪走，这也是利用有序性做剪枝的又一次体现。
- 当 `p`、`q` 分别落在当前节点两侧的时候（或者其中一个正好等于当前节点），说明路径在这里分岔了，当前节点就是最近公共祖先，这个判断逻辑比 0236 要简单直接得多。
- 因为只需要沿着一条路径走到分岔点就行，所以时间复杂度是 O(h) 而不是 O(n)，比普通二叉树的解法效率更高，因为不用去访问那些不相关的子树。
- 这道题特别适合用迭代来实现，因为不需要回溯，空间复杂度可以做到 O(1)，这一点又进一步体现出了 BST 解法相对于普通二叉树解法的优势。

07.二叉树/0236.二叉树的最近公共祖先/0236.二叉树的最近公共祖先.m:
# 0236. 二叉树的最近公共祖先

**题目描述**

给定一个二叉树，找到该树中两个指定节点 `p` 和 `q` 的最近公共祖先（LCA）。这是一棵**普通二叉树**，不是二叉搜索树，节点值没有大小顺序可以利用。

最近公共祖先的定义：对于有根树 `T` 的两个节点 `p`、`q`，最近公共祖先表示为一个节点 `x`，满足 `x` 是 `p`、`q` 的祖先且 `x` 的深度尽可能大（一个节点也可以是它自己的祖先）。

```
示例：
输入: root = [3,5,1,6,2,0,8,null,null,7,4], p = 5, q = 1
输出: 3
解释: 节点 5 和节点 1 的最近公共祖先是节点 3。
```

## 思路

后序递归：遇到空节点、`p` 或 `q` 直接返回。左右结果均非空，当前节点即祖先；仅一侧非空则返回该侧；均空返回空。

时间 O(n)，空间 O(h)，h 为树高；题目保证两目标存在。

## 代码

### Python

```python
class TreeNode:
    # 方法：__init__；按题目要求处理输入并返回结果，核心算法见方法体。
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


class Solution:
    # 方法：lowestCommonAncestor；按题目要求处理输入并返回结果，核心算法见方法体。
    def lowestCommonAncestor(self, root: TreeNode, p: TreeNode, q: TreeNode) -> TreeNode:
        if root is None or root == p or root == q:
            return root  # 终止条件：空节点，或当前节点恰好是 p/q

        left = self.lowestCommonAncestor(root.left, p, q)   # 左子树查找
        right = self.lowestCommonAncestor(root.right, p, q)  # 右子树查找

        if left is not None and right is not None:
            return root  # 左右都找到，当前节点是最近公共祖先
        return left if left is not None else right  # 向上传递唯一找到的结果
```

二叉树节点定义：

```cpp
struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(NULL), right(NULL) {}
};
```

### C++

```cpp
class Solution {
public:
    TreeNode* lowestCommonAncestor(TreeNode* root, TreeNode* p, TreeNode* q) {
        if (root == nullptr || root == p || root == q) {
            return root; // 终止条件：空节点，或当前节点恰好是 p/q
        }
        TreeNode* left = lowestCommonAncestor(root->left, p, q);   // 在左子树中查找
        TreeNode* right = lowestCommonAncestor(root->right, p, q); // 在右子树中查找

        if (left != nullptr && right != nullptr) {
            return root; // 左右子树都找到了目标，当前节点就是最近公共祖先
        }
        return left != nullptr ? left : right; // 只有一侧找到，把结果向上传递
    }
};
```


### Go

```go
type TreeNode struct {
    Val   int
    Left  *TreeNode
    Right *TreeNode
}

// 方法：lowestCommonAncestor；按题目要求处理输入并返回结果，核心算法见方法体。
func lowestCommonAncestor(root, p, q *TreeNode) *TreeNode {
    if root == nil || root == p || root == q {
        return root // 终止条件
    }
    left := lowestCommonAncestor(root.Left, p, q)   // 左子树查找
    right := lowestCommonAncestor(root.Right, p, q) // 右子树查找

    if left != nil && right != nil {
        return root // 左右都找到，当前节点是最近公共祖先
    }
    if left != nil {
        return left // 向上传递左子树的结果
    }
    return right // 向上传递右子树的结果（可能是 nil）
}
```

## 总结

- 这道题的核心是后序遍历回溯：必须先知道左右子树各自的查找结果，才能判断当前节点是不是最近公共祖先，这就决定了处理当前节点这一步必须放在两次递归调用之后。
- 递归函数返回值的含义要想清楚——它代表的是"在这棵子树里找到的、需要往上汇报的节点"，可能是 `p`、`q`、最终答案，也可能是 `null`，这三种非空情况语义各不相同，但代码上用同一个返回值类型统一处理，这正是这道题最巧妙的地方。
- `left` 和 `right` 都不为空的时候，当前节点就是答案，这是这道题最关键的判断逻辑，它的正确性靠的是"两个目标节点分别出现在不相交的两侧子树里"这个事实。
- `p` 是 `q` 祖先这种特殊情况能被正确处理，靠的是终止条件里"当前节点等于 p 或 q 时立即返回"这一步，它其实暗含了"一个节点是它自己的祖先"这个定义，根本不需要额外做特判。

07.二叉树/0257.二叉树的所有路径/0257.二叉树的所有路径.md:
# 0257. 二叉树的所有路径

**题目描述**

给你一个二叉树的根节点 `root`，按**任意顺序**，返回所有从根节点到叶子节点的路径。路径用字符串表示，节点值之间用 `"->"` 分隔。

```
示例：
输入: root = [1,2,3,null,5]
     1
   /   \
  2     3
   \
    5
输出: ["1->2->5","1->3"]
```

## 思路

DFS＋回溯维护路径：进入节点加入值，到叶子保存路径，返回时撤销。也可将路径作为独立参数传递，避免显式撤销。

时间 O(n+L)，辅助空间 O(h)，结果空间 O(L)；L 为输出路径总长度，h 为树高。逐层复制路径最坏时间、峰值空间可达 O(n²)。

## 代码

### Python

```python
class Solution:
    # 方法：binaryTreePaths；按题目要求处理输入并返回结果，核心算法见方法体。
    def binaryTreePaths(self, root):
        result = []
        if root is None:
            return result
        self.traverse(root, [], result)
        return result

    # 方法：traverse；按题目要求处理输入并返回结果，核心算法见方法体。
    def traverse(self, node, path, result):
        path = path + [node.val]  # 用新列表而不是原地修改，天然实现了"隐式回溯"
        if node.left is None and node.right is None:
            result.append("->".join(map(str, path)))  # 叶子节点，拼接路径加入结果
            return
        if node.left:
            self.traverse(node.left, path, result)   # 递归左子树，传入的是新列表，不影响后续右子树
        if node.right:
            self.traverse(node.right, path, result)  # 递归右子树
```

二叉树节点定义：

```cpp
struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(NULL), right(NULL) {}
};
```

```python
class TreeNode:
    # 方法：__init__；按题目要求处理输入并返回结果，核心算法见方法体。
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right
```

### C++

```cpp
class Solution {
public:
    // 方法：traverse；按题目要求处理输入并返回结果，核心算法见方法体。
    void traverse(TreeNode* node, vector<int>& path, vector<string>& result) {
        path.push_back(node->val);              // 做出选择：把当前节点加入路径
        if (node->left == nullptr && node->right == nullptr) {
            // 叶子节点，拼接路径字符串加入结果
            string pathStr;
            for (int i = 0; i < path.size(); i++) {
                pathStr += to_string(path[i]);
                if (i != path.size() - 1) pathStr += "->";
            }
            result.push_back(pathStr);
            return; // 叶子节点没有子节点可以继续递归，直接返回
        }
        if (node->left) {
            traverse(node->left, path, result);  // 递归探索左子树
            path.pop_back();                     // 撤销选择：回溯，移除刚加入的左孩子
        }
        if (node->right) {
            traverse(node->right, path, result); // 递归探索右子树
            path.pop_back();                     // 撤销选择：回溯，移除刚加入的右孩子
        }
    }

    // 方法：binaryTreePaths；按题目要求处理输入并返回结果，核心算法见方法体。
    vector<string> binaryTreePaths(TreeNode* root) {
        vector<string> result;
        if (root == nullptr) return result;
        vector<int> path;
        traverse(root, path, result);
        return result;
    }
};
```


### Go

```go
// 方法：binaryTreePaths；按题目要求处理输入并返回结果，核心算法见方法体。
func binaryTreePaths(root *TreeNode) []string {
    result := []string{}
    if root == nil {
        return result
    }
    var traverse func(node *TreeNode, path []int)
    traverse = func(node *TreeNode, path []int) {
        path = append(path, node.Val) // 追加到新的切片（Go中append不保证不影响原切片，这里按值语义处理更安全）
        if node.Left == nil && node.Right == nil {
            // 叶子节点，拼接路径字符串
            strs := make([]string, len(path))
            for i, v := range path {
                strs[i] = strconv.Itoa(v)
            }
            result = append(result, strings.Join(strs, "->"))
            return
        }
        if node.Left != nil {
            traverse(node.Left, path) // 递归左子树
        }
        if node.Right != nil {
            traverse(node.Right, path) // 递归右子树
        }
    }
    traverse(root, []int{})
    return result
}
```

## 总结

- 收集"根到叶子"的所有路径，是回溯法在二叉树上的一个很典型的应用：递归探索一条路径的过程中不断在"做选择"（把当前节点加入路径），走到叶子节点的时候就收集结果，返回上一层之前需要"撤销选择"（把当前节点移除），这样才能避免污染到其他分支的路径。
- 如果路径参数用的是可变容器（比如 C++、Java 里的可变列表）并且是通过引用传递的，那就必须手动在递归调用之后写 `pop_back`、`remove` 之类的操作来完成回溯；但如果每次递归传进去的是"值拷贝"（比如 Python 里的字符串拼接或者新建一个列表），那就不需要写显式的回溯代码了，因为每个分支天然拿到的就是一份独立的路径副本。
- 判断叶子节点的条件是左右孩子都为空，只有真正走到叶子节点才算是完成了一条完整路径，中间节点是不应该被当成终点的。
- 这道题算是理解"二叉树递归里其实藏着回溯思想"的一道入门题，后面会有专门一篇去讲这个思想的普适性。

07.二叉树/0404.左叶子之和/0404.左叶子之和.md:
# 0404. 左叶子之和

**题目描述**

给定二叉树的根节点 `root`，返回所有**左叶子之和**。

```
示例：
输入: root = [3,9,20,null,null,15,7]
      3
     / \
    9  20
      /  \
     15   7
输出: 24
解释: 左叶子节点是9和15，9+15=24
```

## 思路

遍历时检查左孩子：若非空且没有孩子，累加其值；继续处理左右子树。左叶子须同时满足“左孩子”和“叶子”。

可用递归 DFS 或队列 BFS。时间 O(n)；DFS 空间 O(h)，BFS 空间 O(w)，h 为树高，w 为最大层宽。

## 代码

### Python

```python
class Solution:
    # 方法：sumOfLeftLeaves；按题目要求处理输入并返回结果，核心算法见方法体。
    def sumOfLeftLeaves(self, root):
        if root is None:
            return 0                             # 终止条件
        left_value = 0
        if root.left and root.left.left is None and root.left.right is None:
            left_value = root.left.val           # 左孩子是叶子，记录值
        else:
            left_value = self.sumOfLeftLeaves(root.left)  # 继续往下找
        right_value = self.sumOfLeftLeaves(root.right)    # 右子树内部同样递归
        return left_value + right_value
```

二叉树节点定义：

```cpp
struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(NULL), right(NULL) {}
};
```

```python
class TreeNode:
    # 方法：__init__；按题目要求处理输入并返回结果，核心算法见方法体。
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right
```

### C++

```cpp
class Solution {
public:
    // 方法：sumOfLeftLeaves；按题目要求处理输入并返回结果，核心算法见方法体。
    int sumOfLeftLeaves(TreeNode* root) {
        if (root == nullptr) return 0;               // 终止条件：空节点贡献为0
        int leftValue = 0;
        // 判断当前节点的左孩子是否存在且是叶子节点
        if (root->left != nullptr && root->left->left == nullptr && root->left->right == nullptr) {
            leftValue = root->left->val;             // 找到一个左叶子，记录它的值
        } else {
            leftValue = sumOfLeftLeaves(root->left);  // 左孩子不是叶子（或不存在），继续往下找
        }
        int rightValue = sumOfLeftLeaves(root->right); // 右子树内部同样可能藏着左叶子，需要递归
        return leftValue + rightValue;                // 合并左右子树的结果
    }
};
```


### Go

```go
// 方法：sumOfLeftLeaves；按题目要求处理输入并返回结果，核心算法见方法体。
func sumOfLeftLeaves(root *TreeNode) int {
    if root == nil {
        return 0 // 终止条件
    }
    leftValue := 0
    if root.Left != nil && root.Left.Left == nil && root.Left.Right == nil {
        leftValue = root.Left.Val // 左孩子是叶子，记录值
    } else {
        leftValue = sumOfLeftLeaves(root.Left) // 继续往下找
    }
    rightValue := sumOfLeftLeaves(root.Right) // 右子树内部同样递归
    return leftValue + rightValue
}
```

## 总结

- 说白了，"左叶子"的判断关键就是要结合父子关系：节点自己是不是叶子（左右孩子都空）这个好判断，但"是不是左孩子"这个信息只有在父节点这一层才拿得到，所以判断逻辑得放在父节点那里做，不能等递归进到子节点内部再去判断。
- 递归的时候，"左孩子是叶子"和"左孩子不是叶子或不存在"这两种情况要分开处理：前一种直接把值累加进去，后一种就继续往下递归接着找。
- 右子树这边也不能漏，得照样递归遍历，因为右子树内部同样可能藏着"某个节点的左孩子是叶子"的情况，只是这些左叶子相对于最开始的根节点来说，是处在右子树这个范围里的。
- 那 BFS 的写法呢，逻辑上是等价的，只是用队列迭代代替了递归调用栈，如果不想用递归，或者担心递归深度太深爆栈，用这种写法会更稳一些。

07.二叉树/0450.删除二叉搜索树中的节点/0450.删除二叉搜索树中的节点:
# 0450. 删除二叉搜索树中的节点

**题目描述**

给定二叉搜索树（BST）的根节点 `root` 和一个值 `key`，删除 BST 中值为 `key` 的节点，并保证删除后的树仍然是有效的 BST。返回删除后 BST 的根节点。

```
示例：
输入: root = [5,3,6,2,4,null,7], key = 3
输出: [5,4,6,2,null,null,7]
解释: 节点 3 有左右两个孩子（2 和 4），删除后可以用右子树的最小值节点 4 顶替它的位置。
```

## 思路

按 BST 有序性查找目标，删除后返回新子树根：

- 无孩子：返回空。
- 仅一个孩子：返回该孩子。
- 两个孩子：用右子树最小值替换当前值，再删除该后继节点；也可对称地用左子树最大值替换并删除。

时间 O(h)，递归空间 O(h)，h 为树高。

## 代码

### Python

```python
class TreeNode:
    # 方法：__init__；按题目要求处理输入并返回结果，核心算法见方法体。
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


class Solution:
    # 方法：deleteNode；按题目要求处理输入并返回结果，核心算法见方法体。
    def deleteNode(self, root: TreeNode, key: int) -> TreeNode:
        if root is None:
            return None  # 没找到目标值

        if key < root.val:
            root.left = self.deleteNode(root.left, key)  # 去左子树删除并接回
            return root
        if key > root.val:
            root.right = self.deleteNode(root.right, key)  # 去右子树删除并接回
            return root

        # root.val == key，root 就是要删除的节点
        if root.left is None and root.right is None:
            return None  # 情况1：叶子节点
        if root.left is None:
            return root.right  # 情况2：只有右子树
        if root.right is None:
            return root.left  # 情况3：只有左子树

        # 情况4：左右子树都存在，找右子树最小值节点
        successor = root.right
        while successor.left is not None:
            successor = successor.left  # 一路向左找到最小值节点
        root.val = successor.val  # 用最小值顶替当前节点的值
        root.right = self.deleteNode(root.right, successor.val)  # 递归删除该节点
        return root
```

二叉树节点定义：

```cpp
struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(NULL), right(NULL) {}
};
```

### C++

```cpp
class Solution {
public:
    TreeNode* deleteNode(TreeNode* root, int key) {
        if (root == nullptr) {
            return nullptr; // 没找到要删除的值，空树/空子树直接返回
        }
        if (key < root->val) {
            root->left = deleteNode(root->left, key);   // 目标更小，去左子树删除并接回
            return root;
        }
        if (key > root->val) {
            root->right = deleteNode(root->right, key);  // 目标更大，去右子树删除并接回
            return root;
        }

        // 走到这里说明 root->val == key，root 就是要删除的节点
        if (root->left == nullptr && root->right == nullptr) {
            delete root;
            return nullptr; // 情况1：叶子节点，直接删除
        }
        if (root->left == nullptr) {
            TreeNode* rightChild = root->right;
            delete root;
            return rightChild; // 情况2：只有右子树，用右子树顶替
        }
        if (root->right == nullptr) {
            TreeNode* leftChild = root->left;
            delete root;
            return leftChild; // 情况3：只有左子树，用左子树顶替
        }

        // 情况4：左右子树都存在，找右子树最小值节点顶替
        TreeNode* successor = root->right;
        while (successor->left != nullptr) {
            successor = successor->left; // 一路向左找到右子树的最小值节点
        }
        root->val = successor->val;                          // 用最小值顶替当前节点的值
        root->right = deleteNode(root->right, successor->val); // 递归删除右子树中的这个最小值节点
        return root;
    }
};
```


### Go

```go
type TreeNode struct {
    Val   int
    Left  *TreeNode
    Right *TreeNode
}

// 方法：deleteNode；按题目要求处理输入并返回结果，核心算法见方法体。
func deleteNode(root *TreeNode, key int) *TreeNode {
    if root == nil {
        return nil // 没找到目标值
    }
    if key < root.Val {
        root.Left = deleteNode(root.Left, key) // 去左子树删除并接回
        return root
    }
    if key > root.Val {
        root.Right = deleteNode(root.Right, key) // 去右子树删除并接回
        return root
    }

    // root.Val == key，root 就是要删除的节点
    if root.Left == nil && root.Right == nil {
        return nil // 情况1：叶子节点
    }
    if root.Left == nil {
        return root.Right // 情况2：只有右子树
    }
    if root.Right == nil {
        return root.Left // 情况3：只有左子树
    }

    // 情况4：左右子树都存在，找右子树最小值节点
    successor := root.Right
    for successor.Left != nil {
        successor = successor.Left // 一路向左找到最小值节点
    }
    root.Val = successor.Val                          // 用最小值顶替当前节点的值
    root.Right = deleteNode(root.Right, successor.Val) // 递归删除该节点
    return root
}
```

## 总结

- 删除 BST 节点这里的关键是得分类讨论四种情况：叶子节点直接删掉；只有一侧子树的话就用那个子树顶替；左右子树都有的话，就得找一个"后继节点"，也就是右子树的最小值，或者对称地用左子树的最大值，拿它顶替当前节点的值，再递归把这个后继节点原来的位置删掉。
- 找右子树最小值节点这个路径，说白了就是"一路向左走到底"，这个节点本身最多只有右孩子，所以递归删除它的时候不会再掉进"左右子树都存在"这种复杂情况里，递归深度是可控的。
- 这里沿用了 0701（BST 插入）那道题的套路，也就是"递归返回值重新赋值给子节点指针"这个模式，这样才能保证子树内部改完之后能正确接回父节点，这也是二叉树结构性修改类题目通用的写法。
- 用右子树最小值还是左子树最大值去顶替，两种写法都是对的，只是会让删除后树的具体形状不太一样，但不管选哪种，都得保证递归删除后继节点的时候不会引入重复值，也不会破坏 BST 的性质。

07.二叉树/0501.二叉搜索树中的众数/0501.二叉搜索树中的众数.md:
# 0501. 二叉搜索树中的众数

**题目描述**

给定一个含重复值的二叉搜索树（BST）的根节点 `root`，找出并返回 BST 中的所有众数（出现频率最高的元素）。如果树中有多个众数，则返回它们的数组（顺序任意）。

```
示例：
输入: root = [1,null,2,2]
输出: [2]
解释: 节点值 2 出现了 2 次，1 出现了 1 次，2 是众数。
```

## 思路

- 中序计数：BST 中序非递减，相同值连续出现。记录前值、连续次数和最大次数；超过最大值清空答案，相等则加入。时间 O(n)，辅助空间 O(h)，不计结果。
- 哈希计数：遍历统计频次，输出最大频次对应值。平均时间 O(n)，空间 O(n)。

h 为树高。

## 代码

### Python

```python
class TreeNode:
    # 方法：__init__；按题目要求处理输入并返回结果，核心算法见方法体。
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


class Solution:
    # 方法：findMode；按题目要求处理输入并返回结果，核心算法见方法体。
    def findMode(self, root: TreeNode) -> list[int]:
        self.pre = None       # 上一个访问的节点
        self.count = 0          # 当前值连续出现次数
        self.max_count = 0      # 最大出现次数
        self.result = []        # 众数列表

        # 方法：inorder；按题目要求处理输入并返回结果，核心算法见方法体。
        def inorder(node: TreeNode) -> None:
            if node is None:
                return  # 终止条件
            inorder(node.left)  # 先递归左子树

            if self.pre is not None and self.pre.val == node.val:
                self.count += 1  # 与上一个值相同，计数加 1
            else:
                self.count = 1     # 新的值区间，重置计数

            if self.count > self.max_count:
                self.max_count = self.count  # 发现更高频率的众数
                self.result = [node.val]        # 清空之前的记录
            elif self.count == self.max_count:
                self.result.append(node.val)     # 频率相同，加入众数列表

            self.pre = node       # 更新 pre
            inorder(node.right)  # 最后递归右子树

        inorder(root)
        return self.result
```

二叉树节点定义：

```cpp
struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(NULL), right(NULL) {}
};
```

### C++

```cpp
class Solution {
public:
    // 方法：findMode；按题目要求处理输入并返回结果，核心算法见方法体。
    vector<int> findMode(TreeNode* root) {
        inorder(root);
        return result;
    }

private:
    TreeNode* pre = nullptr;   // 中序遍历中上一个访问的节点
    int count = 0;              // 当前值的连续出现次数
    int maxCount = 0;           // 目前为止的最大出现次数
    vector<int> result;         // 众数列表

    // 方法：inorder；按题目要求处理输入并返回结果，核心算法见方法体。
    void inorder(TreeNode* root) {
        if (root == nullptr) return; // 终止条件
        inorder(root->left);           // 先递归左子树

        // 处理当前节点：更新连续计数
        if (pre != nullptr && pre->val == root->val) {
            count++;         // 与上一个值相同，连续计数加 1
        } else {
            count = 1;         // 进入新的值区间，重置计数
        }

        // 根据 count 与 maxCount 的关系更新众数列表
        if (count > maxCount) {
            maxCount = count;    // 发现频率更高的众数
            result.clear();       // 之前记录的都不再是众数
            result.push_back(root->val);
        } else if (count == maxCount) {
            result.push_back(root->val); // 频率相同，也是众数之一
        }

        pre = root;             // 更新 pre
        inorder(root->right);   // 最后递归右子树
    }
};
```


### Go

```go
type TreeNode struct {
    Val   int
    Left  *TreeNode
    Right *TreeNode
}

// 方法：findMode；按题目要求处理输入并返回结果，核心算法见方法体。
func findMode(root *TreeNode) []int {
    var pre *TreeNode  // 上一个访问的节点
    count := 0           // 当前值连续出现次数
    maxCount := 0         // 最大出现次数
    result := []int{}      // 众数列表

    var inorder func(node *TreeNode)
    inorder = func(node *TreeNode) {
        if node == nil {
            return // 终止条件
        }
        inorder(node.Left) // 先递归左子树

        if pre != nil && pre.Val == node.Val {
            count++ // 与上一个值相同，计数加 1
        } else {
            count = 1 // 新的值区间，重置计数
        }

        if count > maxCount {
            maxCount = count           // 发现更高频率的众数
            result = []int{node.Val}     // 清空之前的记录
        } else if count == maxCount {
            result = append(result, node.Val) // 频率相同，加入众数列表
        }

        pre = node          // 更新 pre
        inorder(node.Right) // 最后递归右子树
    }

    inorder(root)
    return result
}
```

## 总结

- 这道题的核心就是利用 BST 中序遍历的有序性：相同的值在中序遍历结果里必然是连续排列的，所以可以用一个 `pre` 指针比较相邻节点是否相同，来统计连续出现的次数，完全不需要额外的哈希表。
- 需要维护三个状态变量：`count`（当前值的连续计数）、`maxCount`（目前的最大计数）、`result`（众数列表），然后根据 `count` 跟 `maxCount` 之间大于、等于、小于这三种关系，来决定要不要更新众数列表。
- 有一点要特别注意：`count > maxCount` 的时候一定要记得清空之前的 `result`，为什么呢？因为之前记录的众数已经被更频繁出现的新值给取代了。
- 说白了，这道题就是 0530 那个技巧的自然延伸，都是"中序遍历 + pre 指针"这个模式在不同统计需求下的应用，把这个模式吃透了，就能应对更多"BST 相邻关系"这一类的题目。

07.二叉树/0513.找树左下角的值/0513.找树左下角的值.md:
# 0513. 找树左下角的值

**题目描述**

给定一个二叉树的根节点 `root`，找出该二叉树的**最底层最左边**节点的值。

```
示例：
输入: root = [2,1,3]
输出: 1

输入: root = [1,2,3,4,null,5,6,null,null,7]
       1
      / \
     2   3
    /   / \
   4   5   6
  /
 7
输出: 7
```

## 思路

- BFS：记录每层第一个节点，最后一次记录即答案。时间 O(n)，空间 O(w)。
- DFS：先左后右，仅首次到达更深层时更新答案。时间 O(n)，空间 O(h)。

h 为树高，w 为最大层宽。

## 代码

### Python

```python
class Solution:
    # 方法：findBottomLeftValueBFS；按题目要求处理输入并返回结果，核心算法见方法体。
    def findBottomLeftValueBFS(self, root):
        # 思路一：层序遍历
        from collections import deque
        queue = deque([root])
        result = root.val
        while queue:
            size = len(queue)
            for i in range(size):
                node = queue.popleft()
                if i == 0:
                    result = node.val         # 本层第一个节点即最左
                if node.left:
                    queue.append(node.left)
                if node.right:
                    queue.append(node.right)
        return result

    # 方法：findBottomLeftValue；按题目要求处理输入并返回结果，核心算法见方法体。
    def findBottomLeftValue(self, root):
        # 思路二：DFS
        self.max_depth = -1
        self.result = 0

        # 方法：traverse；按题目要求处理输入并返回结果，核心算法见方法体。
        def traverse(node, depth):
            if node is None:
                return
            if node.left is None and node.right is None:
                if depth > self.max_depth:
                    self.max_depth = depth   # 更新最大深度
                    self.result = node.val   # 更新最左值
            traverse(node.left, depth + 1)   # 先左
            traverse(node.right, depth + 1)  # 后右

        traverse(root, 0)
        return self.result
```

