### C++

```cpp
class Solution {
public:
    // 思路一：层序遍历，取每层第一个节点，最终保留最后一层的记录
    // 方法：findBottomLeftValueBFS；按题目要求处理输入并返回结果，核心算法见方法体。
    int findBottomLeftValueBFS(TreeNode* root) {
        queue<TreeNode*> que;
        que.push(root);
        int result = root->val;
        while (!que.empty()) {
            int size = que.size();
            for (int i = 0; i < size; i++) {
                TreeNode* node = que.front();
                que.pop();
                if (i == 0) result = node->val;   // 记录本层第一个访问到的节点（最左）
                if (node->left) que.push(node->left);
                if (node->right) que.push(node->right);
            }
        }
        return result;  // 遍历结束，result 保留的是最后一层（最底层）的最左值
    }

    // 思路二：DFS，记录最大深度，深度增加时更新结果
    int maxDepth = -1;
    int result = 0;
    // 方法：traverse；按题目要求处理输入并返回结果，核心算法见方法体。
    void traverse(TreeNode* node, int depth) {
        if (node == nullptr) return;
        if (node->left == nullptr && node->right == nullptr) {
            // 到达叶子节点，检查是否比当前记录的最大深度更深
            if (depth > maxDepth) {
                maxDepth = depth;      // 更新最大深度
                result = node->val;    // 更新最左值（因为前序遍历先左后右，第一次到达更深层就是最左）
            }
        }
        traverse(node->left, depth + 1);  // 先递归左子树（保证左边先被访问到）
        traverse(node->right, depth + 1); // 再递归右子树
    }
    // 方法：findBottomLeftValue；按题目要求处理输入并返回结果，核心算法见方法体。
    int findBottomLeftValue(TreeNode* root) {
        traverse(root, 0);
        return result;
    }
};
```


### Go

```go
// 思路一：层序遍历
// 方法：findBottomLeftValueBFS；按题目要求处理输入并返回结果，核心算法见方法体。
func findBottomLeftValueBFS(root *TreeNode) int {
    queue := []*TreeNode{root}
    result := root.Val
    for len(queue) > 0 {
        size := len(queue)
        for i := 0; i < size; i++ {
            node := queue[0]
            queue = queue[1:]
            if i == 0 {
                result = node.Val // 本层第一个节点即最左
            }
            if node.Left != nil {
                queue = append(queue, node.Left)
            }
            if node.Right != nil {
                queue = append(queue, node.Right)
            }
        }
    }
    return result
}

// 思路二：DFS
// 方法：findBottomLeftValue；按题目要求处理输入并返回结果，核心算法见方法体。
func findBottomLeftValue(root *TreeNode) int {
    maxDepth := -1
    result := 0
    var traverse func(node *TreeNode, depth int)
    traverse = func(node *TreeNode, depth int) {
        if node == nil {
            return
        }
        if node.Left == nil && node.Right == nil {
            if depth > maxDepth {
                maxDepth = depth  // 更新最大深度
                result = node.Val // 更新最左值
            }
        }
        traverse(node.Left, depth+1)  // 先左
        traverse(node.Right, depth+1) // 后右
    }
    traverse(root, 0)
    return result
}
```

## 总结

- 层序遍历这个解法是最直观的：每层只记录第一个被访问到的节点值，遍历结束之后留下来的就是最后一层，也就是最底层的记录，天然就满足了"最底层最左"这个要求。
- DFS 解法需要维护"当前最大深度"和"对应结果值"这两个状态，而且必须保证先递归左子树再递归右子树，这样同一深度里最左边的节点才会先被访问到，"深度增加了才更新结果"这个判断逻辑才能立得住。
- 两种解法的复杂度都是 O(n)，选哪种主要看个人偏好：BFS 写法更符合"层"的那种直觉，DFS 写法代码量稍微少一点，但要注意递归顺序不能写错。
- 这道题其实又体现了一个套路：跟"层"相关的问题优先考虑用 BFS，如果需要在遍历过程中携带额外状态（比如这里的深度），用 DFS 也能等价地解决。

07.二叉树/0530.二叉搜索树的最小绝对差/0530.二叉搜索树的最小绝对差:
# 0530. 二叉搜索树的最小绝对差

**题目描述**

给定一个二叉搜索树（BST）的根节点 `root`，返回树中任意两个不同节点值之间的最小绝对差。

```
示例：
输入: root = [4,2,6,1,3]
输出: 1
解释: 所有节点值排序后是 [1,2,3,4,6]，相邻差值分别是 1,1,1,2，最小值是 1。
```

## 思路

- 中序遍历：BST 有序，最小差必在相邻值间；用前驱值更新最小差。时间 O(n)，空间 O(h)。
- 收集后排序：排序全部节点值，再比较相邻差。时间 O(n log n)，空间 O(n)。

h 为树高。

## 代码

### Python

```python
class TreeNode:
    # 方法：__init__；按题目要求处理输入并返回结果，核心算法见方法体。
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


class Solution:
    # 方法：getMinimumDifference；按题目要求处理输入并返回结果，核心算法见方法体。
    def getMinimumDifference(self, root: TreeNode) -> int:
        self.pre = None            # 记录上一个访问的节点
        self.result = float("inf")  # 最小差值

        # 方法：inorder；按题目要求处理输入并返回结果，核心算法见方法体。
        def inorder(node: TreeNode) -> None:
            if node is None:
                return  # 终止条件
            inorder(node.left)  # 先递归左子树
            if self.pre is not None:
                self.result = min(self.result, node.val - self.pre.val)  # 更新最小差
            self.pre = node  # 更新 pre
            inorder(node.right)  # 最后递归右子树

        inorder(root)
        return self.result
```

二叉树节点定义：

```cpp
struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(NULL), right(NULL) {}
};
```

### C++

```cpp
class Solution {
public:
    // 方法：getMinimumDifference；按题目要求处理输入并返回结果，核心算法见方法体。
    int getMinimumDifference(TreeNode* root) {
        inorder(root);
        return result;
    }

private:
    TreeNode* pre = nullptr;      // 记录中序遍历中上一个访问的节点
    int result = INT_MAX;          // 维护当前最小差值

    // 方法：inorder；按题目要求处理输入并返回结果，核心算法见方法体。
    void inorder(TreeNode* root) {
        if (root == nullptr) return; // 终止条件：空节点
        inorder(root->left);          // 先递归左子树
        if (pre != nullptr) {
            result = min(result, root->val - pre->val); // 与上一个节点比较，更新最小差
        }
        pre = root;                    // 更新 pre 为当前节点
        inorder(root->right);          // 最后递归右子树
    }
};
```


### Go

```go
type TreeNode struct {
    Val   int
    Left  *TreeNode
    Right *TreeNode
}

// 方法：getMinimumDifference；按题目要求处理输入并返回结果，核心算法见方法体。
func getMinimumDifference(root *TreeNode) int {
    var pre *TreeNode      // 记录上一个访问的节点
    result := math.MaxInt64 // 最小差值

    var inorder func(node *TreeNode)
    inorder = func(node *TreeNode) {
        if node == nil {
            return // 终止条件
        }
        inorder(node.Left) // 先递归左子树
        if pre != nil {
            diff := node.Val - pre.Val
            if diff < result {
                result = diff // 更新最小差
            }
        }
        pre = node          // 更新 pre
        inorder(node.Right) // 最后递归右子树
    }

    inorder(root)
    return result
}
```

## 总结

- 核心结论就是：BST 中序遍历结果是严格递增的，最小差值必然出现在相邻元素之间，所以说不需要把所有节点两两组合都比较一遍，只要比较中序遍历里相邻的元素对就行。
- 用 `pre` 指针记录中序遍历的上一个节点，边遍历边比较，这样就能把"先存整个序列再遍历比较"那种 O(n) 的额外空间，优化到 O(1)（不含递归栈），这是处理 BST 相邻关系类问题的通用技巧。
- 递归结构其实还是标准的中序遍历模板，唯一的变化就是在"处理当前节点"这一步，插入了跟 `pre` 比较的逻辑。
- 这道题跟后面要讲的 0501（BST 中的众数）共享的是同一个"pre 指针加中序遍历"的模式，把这道题的写法理解透了，后面可以直接照搬过去用。

07.二叉树/0538.把二叉搜索树转换为累加树/0538.把二叉搜索树转换为累:
# 0538. 把二叉搜索树转换为累加树

**题目描述**

给定一个二叉搜索树（BST），将其转换为累加树（Greater Sum Tree），使得每个节点的值等于原来的值加上所有大于它的节点值之和。

```
示例：
输入: root = [5,2,13]
输出: [18,20,13]
解释: 节点 2 的新值 = 2 + 13 + 5 = 20；节点 5 的新值 = 5 + 13 = 18；节点 13 没有比它大的节点，新值不变。
```

## 思路

反向中序遍历“右→根→左”，按值从大到小累加；每到一个节点，累加原值并用累计和替换节点值。

时间 O(n)，空间 O(h)，h 为树高。

## 代码

### Python

```python
class TreeNode:
    # 方法：__init__；按题目要求处理输入并返回结果，核心算法见方法体。
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


class Solution:
    # 方法：convertBST；按题目要求处理输入并返回结果，核心算法见方法体。
    def convertBST(self, root: TreeNode) -> TreeNode:
        self.pre = 0  # 累加和：目前已处理过的所有节点值之和

        # 方法：reverse_inorder；按题目要求处理输入并返回结果，核心算法见方法体。
        def reverse_inorder(node: TreeNode) -> None:
            if node is None:
                return  # 终止条件
            reverse_inorder(node.right)  # 先处理右子树（值更大的部分）
            self.pre += node.val  # 累加当前节点原值
            node.val = self.pre  # 把累加和赋给当前节点
            reverse_inorder(node.left)  # 最后处理左子树

        reverse_inorder(root)
        return root
```

二叉树节点定义：

```cpp
struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(NULL), right(NULL) {}
};
```

### C++

```cpp
class Solution {
public:
    TreeNode* convertBST(TreeNode* root) {
        reverseInorder(root);
        return root;
    }

private:
    int pre = 0; // 累加和：目前已处理过的所有节点值之和

    // 方法：reverseInorder；按题目要求处理输入并返回结果，核心算法见方法体。
    void reverseInorder(TreeNode* root) {
        if (root == nullptr) return; // 终止条件
        reverseInorder(root->right);  // 先处理右子树（值更大的部分）
        pre += root->val;               // 累加当前节点原值
        root->val = pre;                 // 把累加和赋给当前节点，完成转换
        reverseInorder(root->left);    // 最后处理左子树（值更小的部分）
    }
};
```


### Go

```go
type TreeNode struct {
    Val   int
    Left  *TreeNode
    Right *TreeNode
}

// 方法：convertBST；按题目要求处理输入并返回结果，核心算法见方法体。
func convertBST(root *TreeNode) *TreeNode {
    pre := 0 // 累加和

    var reverseInorder func(node *TreeNode)
    reverseInorder = func(node *TreeNode) {
        if node == nil {
            return // 终止条件
        }
        reverseInorder(node.Right) // 先处理右子树
        pre += node.Val              // 累加当前节点原值
        node.Val = pre                // 赋值给当前节点
        reverseInorder(node.Left)    // 最后处理左子树
    }

    reverseInorder(root)
    return root
}
```

## 总结

- 核心技巧就是"反中序遍历"，也就是先右子树、再当前节点、最后左子树，这样得到的访问顺序是从大到小，天然适合"累加所有比当前节点大的值"这类需求。
- `pre` 这个变量在这里扮演的角色是"到目前为止已处理节点值之和"，处理当前节点的时候要先累加原值，再把结果赋值给节点本身，这个顺序不能颠倒，不然会把累加和本身重复算进去。
- 这道题说白了就是 0530 和 0501 那种"pre 指针加中序遍历"模式的一个变体：遍历方向从"从小到大"改成了"从大到小"，`pre` 的含义也从"上一个节点"变成了"累加和"，这体现的是同一个模式在不同问题上的灵活迁移。
- 这个转换是原地修改节点的 `val`，不需要新建一棵树的结构，空间开销就只有递归调用栈，这也是这类"基于中序遍历顺序做原地统计或转换"问题典型的效率特征。

07.二叉树/0617.合并二叉树/0617.合并二叉树.md:
# 0617. 合并二叉树

**题目描述**

给定两棵二叉树 `root1` 和 `root2`，想象当你将其中一棵覆盖到另一棵上时，两棵树的一些节点会重叠，而另一些节点则不会。你需要将这两棵树合并成一棵新树。合并的规则是：如果两个节点重叠，那么将两个节点的值相加作为合并后节点的新值；否则，不为 `null` 的节点将直接作为新树的节点。

```
示例：
输入: root1 = [1,3,2,5], root2 = [2,1,3,null,4,null,7]
输出: [3,4,5,5,4,null,7]
解释: 对应位置节点值相加，root1 有的位置 root2 没有（或反过来），直接用存在的那个节点。
```

## 思路

同步递归：一棵子树为空则直接返回另一棵；均非空则节点值相加，递归合并左右孩子并接回。

时间 O(min(m,n)+1)，辅助空间 O(min(h₁,h₂)+1)，m、n 为节点数，h₁、h₂ 为树高。

## 代码

### Python

同时遍历两棵树做合并是结构性递归，没有对应的标准库一行解，只给手写实现：

```python
class TreeNode:
    # 方法：__init__；按题目要求处理输入并返回结果，核心算法见方法体。
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


class Solution:
    # 方法：mergeTrees；按题目要求处理输入并返回结果，核心算法见方法体。
    def mergeTrees(self, root1: TreeNode, root2: TreeNode) -> TreeNode:
        # 复用 root1 的结构，直接在其上修改
        if root1 is None:
            return root2  # root1 为空，结果取决于 root2
        if root2 is None:
            return root1  # root2 为空，直接用 root1
        root1.val += root2.val  # 两者都非空，值相加
        root1.left = self.mergeTrees(root1.left, root2.left)    # 递归合并左子树
        root1.right = self.mergeTrees(root1.right, root2.right)  # 递归合并右子树
        return root1

    # 方法：mergeTreesNew；按题目要求处理输入并返回结果，核心算法见方法体。
    def mergeTreesNew(self, root1: TreeNode, root2: TreeNode) -> TreeNode:
        # 新建节点版本，不修改任意一棵原树
        if root1 is None:
            return root2
        if root2 is None:
            return root1
        node = TreeNode(root1.val + root2.val)  # 新建节点承载合并结果
        node.left = self.mergeTreesNew(root1.left, root2.left)
        node.right = self.mergeTreesNew(root1.right, root2.right)
        return node
```

