# 二叉树的统一迭代法

**内容概述**

上一篇讲的迭代遍历里，前序和后序的写法很接近，但中序遍历需要额外引入一个 `cur` 指针，逻辑上和另外两种不统一，代码没法直接复用。这篇讲一种"标记法"，用同一套代码模板就能写出前中后序三种迭代遍历，只需要调整节点重新入栈的相对顺序就行。

节点定义（后续代码统一使用）：

```cpp
struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(NULL), right(NULL) {}
};
```

```python
class TreeNode:
    # 方法：__init__；按题目要求处理输入并返回结果，核心算法见方法体。
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right
```

## 思路

栈＋空标记区分“展开节点”和“访问节点”。未标记时按遍历顺序的逆序压入孩子及当前节点，并在当前节点后压入空标记；遇到标记，弹出下一个节点并访问。

时间 O(n)，辅助空间 O(h)，结果 O(n)，h 为树高。

## 代码

### Python

```python
class Solution:
    # 方法：inorderTraversal；按题目要求处理输入并返回结果，核心算法见方法体。
    def inorderTraversal(self, root):
        # 中序遍历统一迭代法：左 -> 根 -> 右
        result = []
        stack = []
        if root:
            stack.append(root)
        while stack:
            node = stack[-1]
            if node is not None:
                stack.pop()
                if node.right:
                    stack.append(node.right)  # 右孩子先压
                stack.append(node)            # 根节点重新压回
                stack.append(None)            # 紧跟标记
                if node.left:
                    stack.append(node.left)   # 左孩子最后压
            else:
                stack.pop()                   # 弹出标记
                result.append(stack.pop().val)  # 弹出并访问真正的节点
        return result

    # 方法：preorderTraversal；按题目要求处理输入并返回结果，核心算法见方法体。
    def preorderTraversal(self, root):
        # 前序遍历统一迭代法：根 -> 左 -> 右
        result = []
        stack = []
        if root:
            stack.append(root)
        while stack:
            node = stack[-1]
            if node is not None:
                stack.pop()
                if node.right:
                    stack.append(node.right)
                if node.left:
                    stack.append(node.left)
                stack.append(node)
                stack.append(None)
            else:
                stack.pop()
                result.append(stack.pop().val)
        return result

    # 方法：postorderTraversal；按题目要求处理输入并返回结果，核心算法见方法体。
    def postorderTraversal(self, root):
        # 后序遍历统一迭代法：左 -> 右 -> 根
        result = []
        stack = []
        if root:
            stack.append(root)
        while stack:
            node = stack[-1]
            if node is not None:
                stack.pop()
                stack.append(node)
                stack.append(None)
                if node.right:
                    stack.append(node.right)
                if node.left:
                    stack.append(node.left)
            else:
                stack.pop()
                result.append(stack.pop().val)
        return result
```

### C++

```cpp
class Solution {
public:
    // 中序遍历统一迭代法：左 -> 根 -> 右
    // 方法：inorderTraversal；按题目要求处理输入并返回结果，核心算法见方法体。
    vector<int> inorderTraversal(TreeNode* root) {
        vector<int> result;
        stack<TreeNode*> st;
        if (root != nullptr) st.push(root);
        while (!st.empty()) {
            TreeNode* node = st.top();
            if (node != nullptr) {
                st.pop();
                if (node->right) st.push(node->right); // 右孩子先压，最后出栈
                st.push(node);                          // 根节点重新压回
                st.push(nullptr);                       // 紧跟一个标记，表示下次弹出即访问
                if (node->left) st.push(node->left);    // 左孩子最后压，最先出栈
            } else {
                st.pop();                    // 弹出标记
                result.push_back(st.top()->val); // 标记后面就是真正要访问的节点
                st.pop();
            }
        }
        return result;
    }

    // 前序遍历统一迭代法：根 -> 左 -> 右
    // 方法：preorderTraversal；按题目要求处理输入并返回结果，核心算法见方法体。
    vector<int> preorderTraversal(TreeNode* root) {
        vector<int> result;
        stack<TreeNode*> st;
        if (root != nullptr) st.push(root);
        while (!st.empty()) {
            TreeNode* node = st.top();
            if (node != nullptr) {
                st.pop();
                if (node->right) st.push(node->right); // 右孩子先压
                if (node->left) st.push(node->left);   // 左孩子次之
                st.push(node);                          // 根节点最后压，最先出栈访问
                st.push(nullptr);                       // 紧跟标记
            } else {
                st.pop();
                result.push_back(st.top()->val);
                st.pop();
            }
        }
        return result;
    }

    // 后序遍历统一迭代法：左 -> 右 -> 根
    // 方法：postorderTraversal；按题目要求处理输入并返回结果，核心算法见方法体。
    vector<int> postorderTraversal(TreeNode* root) {
        vector<int> result;
        stack<TreeNode*> st;
        if (root != nullptr) st.push(root);
        while (!st.empty()) {
            TreeNode* node = st.top();
            if (node != nullptr) {
                st.pop();
                st.push(node);                          // 根节点先压（最后访问）
                st.push(nullptr);                       // 紧跟标记
                if (node->right) st.push(node->right);  // 右孩子次之
                if (node->left) st.push(node->left);    // 左孩子最后压，最先出栈
            } else {
                st.pop();
                result.push_back(st.top()->val);
                st.pop();
            }
        }
        return result;
    }
};
```


### Go

```go
// 中序遍历统一迭代法：左 -> 根 -> 右
// 方法：inorderTraversal；按题目要求处理输入并返回结果，核心算法见方法体。
func inorderTraversal(root *TreeNode) []int {
    result := []int{}
    var stack []*TreeNode
    if root != nil {
        stack = append(stack, root)
    }
    for len(stack) > 0 {
        node := stack[len(stack)-1]
        if node != nil {
            stack = stack[:len(stack)-1]
            if node.Right != nil {
                stack = append(stack, node.Right) // 右先压
            }
            stack = append(stack, node) // 根重新压回
            stack = append(stack, nil)  // 标记
            if node.Left != nil {
                stack = append(stack, node.Left) // 左最后压
            }
        } else {
            stack = stack[:len(stack)-1] // 弹出标记
            node = stack[len(stack)-1]
            stack = stack[:len(stack)-1]
            result = append(result, node.Val) // 访问真正的节点
        }
    }
    return result
}

// 前序遍历统一迭代法：根 -> 左 -> 右
// 方法：preorderTraversal；按题目要求处理输入并返回结果，核心算法见方法体。
func preorderTraversal(root *TreeNode) []int {
    result := []int{}
    var stack []*TreeNode
    if root != nil {
        stack = append(stack, root)
    }
    for len(stack) > 0 {
        node := stack[len(stack)-1]
        if node != nil {
            stack = stack[:len(stack)-1]
            if node.Right != nil {
                stack = append(stack, node.Right)
            }
            if node.Left != nil {
                stack = append(stack, node.Left)
            }
            stack = append(stack, node)
            stack = append(stack, nil)
        } else {
            stack = stack[:len(stack)-1]
            node = stack[len(stack)-1]
            stack = stack[:len(stack)-1]
            result = append(result, node.Val)
        }
    }
    return result
}

// 后序遍历统一迭代法：左 -> 右 -> 根
// 方法：postorderTraversal；按题目要求处理输入并返回结果，核心算法见方法体。
func postorderTraversal(root *TreeNode) []int {
    result := []int{}
    var stack []*TreeNode
    if root != nil {
        stack = append(stack, root)
    }
    for len(stack) > 0 {
        node := stack[len(stack)-1]
        if node != nil {
            stack = stack[:len(stack)-1]
            stack = append(stack, node)
            stack = append(stack, nil)
            if node.Right != nil {
                stack = append(stack, node.Right)
            }
            if node.Left != nil {
                stack = append(stack, node.Left)
            }
        } else {
            stack = stack[:len(stack)-1]
            node = stack[len(stack)-1]
            stack = stack[:len(stack)-1]
            result = append(result, node.Val)
        }
    }
    return result
}
```

## 总结

- 统一迭代法的核心是给节点加一个"访问标记"：第一次遇到只入栈不访问，标记后紧跟着重新压回，第二次遇到（也就是弹出标记）的时候才真正去访问。
- 三种遍历顺序只需要调整"根、左、右"三者压栈的相对顺序，代码框架完全一致，不用再像中序那样单独引入额外指针，也不用像后序那样依赖"反转结果"的技巧。
- 压栈顺序跟出栈顺序是相反的：想要出栈顺序是"左、根、右"，压栈顺序就得反过来写成"右、根+标记、左"，这个地方要转个弯想一下。
- 这种写法虽然更统一，但引入了 `nullptr`/`None` 当标记，代码可读性上不如前一篇那种"专用写法"直观，实际面试中两种写法都可以选，理解思想比死记代码更重要。

07.二叉树/二叉树的迭代遍历/二叉树的迭代遍历.md:
# 二叉树的迭代遍历

**内容概述**

你想啊，递归遍历靠的是系统调用栈自动帮你维护"待处理节点"的顺序，那迭代遍历呢，说白了就得自己用一个显式的栈来模拟这个过程。三种遍历里，前序最容易写，中序需要一个额外的指针配合，后序则可以用一个小技巧转化成前序的变体，挺巧妙的。

节点定义（后续代码统一使用）：

```cpp
struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(NULL), right(NULL) {}
};
```

```python
class TreeNode:
    # 方法：__init__；按题目要求处理输入并返回结果，核心算法见方法体。
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right
```

## 思路

- 前序：弹栈即访问，先压右孩子，再压左孩子。
- 中序：沿左链入栈；弹栈访问后转向右孩子。
- 后序：按“根→右→左”收集，再反转为“左→右→根”。

时间 O(n)，辅助栈空间 O(h)，结果空间 O(n)，h 为树高。

## 代码

### Python

```python
class Solution:
    # 方法：preorderTraversal；按题目要求处理输入并返回结果，核心算法见方法体。
    def preorderTraversal(self, root):
        # 前序遍历迭代法：根 -> 左 -> 右
        result = []
        if root is None:
            return result
        stack = [root]           # 初始把根节点压栈
        while stack:
            node = stack.pop()
            result.append(node.val)   # 弹出即访问
            if node.right:
                stack.append(node.right)  # 先压右孩子
            if node.left:
                stack.append(node.left)   # 再压左孩子，保证左先弹出
        return result

    # 方法：inorderTraversal；按题目要求处理输入并返回结果，核心算法见方法体。
    def inorderTraversal(self, root):
        # 中序遍历迭代法：左 -> 根 -> 右
        result = []
        stack = []
        cur = root                # cur 跟踪当前探索节点
        while cur is not None or stack:
            if cur is not None:   # 一直向左压栈，不访问
                stack.append(cur)
                cur = cur.left
            else:                  # 左边走到头，弹出并访问
                cur = stack.pop()
                result.append(cur.val)
                cur = cur.right   # 转向右子树
        return result

    # 方法：postorderTraversal；按题目要求处理输入并返回结果，核心算法见方法体。
    def postorderTraversal(self, root):
        # 后序遍历迭代法：左 -> 右 -> 根
        result = []
        if root is None:
            return result
        stack = [root]
        while stack:
            node = stack.pop()
            result.append(node.val)
            if node.left:
                stack.append(node.left)   # 先压左孩子
            if node.right:
                stack.append(node.right)  # 再压右孩子，保证右先弹出
        return result[::-1]       # 反转"根右左"得到"左右根"
```

### C++

```cpp
class Solution {
public:
    // 前序遍历迭代法：根 -> 左 -> 右
    // 方法：preorderTraversal；按题目要求处理输入并返回结果，核心算法见方法体。
    vector<int> preorderTraversal(TreeNode* root) {
        vector<int> result;
        if (root == nullptr) return result;
        stack<TreeNode*> st;
        st.push(root);                    // 初始把根节点压栈
        while (!st.empty()) {
            TreeNode* node = st.top();
            st.pop();
            result.push_back(node->val);  // 弹出即访问，符合"先访问根"的要求
            if (node->right) st.push(node->right); // 先压右孩子
            if (node->left) st.push(node->left);   // 再压左孩子，保证左孩子先被弹出
        }
        return result;
    }

    // 中序遍历迭代法：左 -> 根 -> 右
    // 方法：inorderTraversal；按题目要求处理输入并返回结果，核心算法见方法体。
    vector<int> inorderTraversal(TreeNode* root) {
        vector<int> result;
        stack<TreeNode*> st;
        TreeNode* cur = root;             // cur 指针跟踪当前探索的节点
        while (cur != nullptr || !st.empty()) {
            if (cur != nullptr) {         // 只要还能往左走，就一直压栈不访问
                st.push(cur);
                cur = cur->left;
            } else {                       // 左边走到头，弹出栈顶并访问
                cur = st.top();
                st.pop();
                result.push_back(cur->val); // 此时左子树已完全处理，访问当前节点
                cur = cur->right;          // 转向右子树，重复上述过程
            }
        }
        return result;
    }

    // 后序遍历迭代法：左 -> 右 -> 根（用"根右左"逆序实现）
    // 方法：postorderTraversal；按题目要求处理输入并返回结果，核心算法见方法体。
    vector<int> postorderTraversal(TreeNode* root) {
        vector<int> result;
        if (root == nullptr) return result;
        stack<TreeNode*> st;
        st.push(root);
        while (!st.empty()) {
            TreeNode* node = st.top();
            st.pop();
            result.push_back(node->val);
            if (node->left) st.push(node->left);   // 先压左孩子
            if (node->right) st.push(node->right); // 再压右孩子，保证右孩子先被弹出（得到"根右左"）
        }
        reverse(result.begin(), result.end());     // 反转"根右左"得到"左右根"
        return result;
    }
};
```


### Go

```go
// 前序遍历迭代法：根 -> 左 -> 右
// 方法：preorderTraversal；按题目要求处理输入并返回结果，核心算法见方法体。
func preorderTraversal(root *TreeNode) []int {
    result := []int{}
    if root == nil {
        return result
    }
    stack := []*TreeNode{root} // 初始把根节点压栈
    for len(stack) > 0 {
        node := stack[len(stack)-1]
        stack = stack[:len(stack)-1]
        result = append(result, node.Val) // 弹出即访问
        if node.Right != nil {
            stack = append(stack, node.Right) // 先压右孩子
        }
        if node.Left != nil {
            stack = append(stack, node.Left) // 再压左孩子，保证左先弹出
        }
    }
    return result
}

// 中序遍历迭代法：左 -> 根 -> 右
// 方法：inorderTraversal；按题目要求处理输入并返回结果，核心算法见方法体。
func inorderTraversal(root *TreeNode) []int {
    result := []int{}
    var stack []*TreeNode
    cur := root // cur 跟踪当前探索节点
    for cur != nil || len(stack) > 0 {
        if cur != nil { // 一直向左压栈，不访问
            stack = append(stack, cur)
            cur = cur.Left
        } else { // 左边走到头，弹出并访问
            cur = stack[len(stack)-1]
            stack = stack[:len(stack)-1]
            result = append(result, cur.Val)
            cur = cur.Right // 转向右子树
        }
    }
    return result
}

// 后序遍历迭代法：左 -> 右 -> 根
// 方法：postorderTraversal；按题目要求处理输入并返回结果，核心算法见方法体。
func postorderTraversal(root *TreeNode) []int {
    result := []int{}
    if root == nil {
        return result
    }
    stack := []*TreeNode{root}
    for len(stack) > 0 {
        node := stack[len(stack)-1]
        stack = stack[:len(stack)-1]
        result = append(result, node.Val)
        if node.Left != nil {
            stack = append(stack, node.Left) // 先压左孩子
        }
        if node.Right != nil {
            stack = append(stack, node.Right) // 再压右孩子，保证右先弹出
        }
    }
    // 反转"根右左"得到"左右根"
    for i, j := 0, len(result)-1; i < j; i, j = i+1, j-1 {
        result[i], result[j] = result[j], result[i]
    }
    return result
}
```

## 总结

- 前序迭代最直观：栈的"后进先出"特性正好对应"先访问根再访问左"，压栈时要先压右孩子再压左孩子，这样才能保证左孩子先出栈。
- 中序迭代需要额外的 `cur` 指针配合栈来用：不断向左压栈直到走到头，再弹出访问，然后转向右子树，说白了本质就是在模拟"沿着左链一直往下，再折返"的过程。
- 后序迭代最省心的写法就是复用前序迭代的代码，把入栈顺序改为先左后右（这样能得到"根右左"），最后整体反转结果就得到"左右根"了，不需要单独设计新逻辑，挺讨巧的。
- 三种迭代写法的时间空间复杂度和递归版本是一致的，区别只是显式管理栈还是依赖系统调用栈，这也是为什么迭代法能避免递归深度过大导致栈溢出这个问题的原因。

07.二叉树/二叉树的递归遍历/二叉树的递归遍历.md:
# 二叉树的递归遍历

**内容概述**

这篇讲二叉树前序、中序、后序遍历的递归实现。你会发现三种遍历的递归代码结构几乎一模一样，唯一的区别就是"访问当前节点"这一行代码放在递归调用左子树、右子树的前面、中间还是后面。理解了这一点，三种遍历就不需要死记硬背了，而是能自己推导出来。

节点定义（后续代码统一使用）：

```cpp
struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(NULL), right(NULL) {}
};
```

```python
class TreeNode:
    # 方法：__init__；按题目要求处理输入并返回结果，核心算法见方法体。
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right
```

## 思路

递归遍历：空节点返回；访问当前值与递归左右子树的顺序决定结果。

- 前序：根→左→右。
- 中序：左→根→右。
- 后序：左→右→根。

时间 O(n)，辅助空间 O(h)，结果空间 O(n)，h 为树高。

## 代码

### Python

```python
class Solution:
    # 方法：preorder；按题目要求处理输入并返回结果，核心算法见方法体。
    def preorder(self, root, result):
        # 前序遍历：根 -> 左 -> 右
        if root is None:
            return  # 终止条件：空节点直接返回
        result.append(root.val)     # 先处理当前节点
        self.preorder(root.left, result)   # 再递归左子树
        self.preorder(root.right, result)  # 最后递归右子树

    # 方法：inorder；按题目要求处理输入并返回结果，核心算法见方法体。
    def inorder(self, root, result):
        # 中序遍历：左 -> 根 -> 右
        if root is None:
            return
        self.inorder(root.left, result)    # 先递归左子树
        result.append(root.val)     # 左子树处理完后处理当前节点
        self.inorder(root.right, result)   # 最后递归右子树

    # 方法：postorder；按题目要求处理输入并返回结果，核心算法见方法体。
    def postorder(self, root, result):
        # 后序遍历：左 -> 右 -> 根
        if root is None:
            return
        self.postorder(root.left, result)  # 先递归左子树
        self.postorder(root.right, result) # 再递归右子树
        result.append(root.val)     # 左右都处理完才处理当前节点
```

### C++

```cpp
class Solution {
public:
    // 前序遍历：根 -> 左 -> 右
    // 方法：preorder；按题目要求处理输入并返回结果，核心算法见方法体。
    void preorder(TreeNode* root, vector<int>& result) {
        if (root == nullptr) return;   // 终止条件：空节点直接返回
        result.push_back(root->val);   // 先处理当前节点（根）
        preorder(root->left, result);  // 再递归处理左子树
        preorder(root->right, result); // 最后递归处理右子树
    }

    // 中序遍历：左 -> 根 -> 右
    // 方法：inorder；按题目要求处理输入并返回结果，核心算法见方法体。
    void inorder(TreeNode* root, vector<int>& result) {
        if (root == nullptr) return;
        inorder(root->left, result);   // 先递归处理左子树
        result.push_back(root->val);   // 左子树处理完后处理当前节点
        inorder(root->right, result);  // 最后递归处理右子树
    }

    // 后序遍历：左 -> 右 -> 根
    // 方法：postorder；按题目要求处理输入并返回结果，核心算法见方法体。
    void postorder(TreeNode* root, vector<int>& result) {
        if (root == nullptr) return;
        postorder(root->left, result);  // 先递归处理左子树
        postorder(root->right, result); // 再递归处理右子树
        result.push_back(root->val);    // 左右子树都处理完后才处理当前节点
    }
};
```


### Go

```go
// 前序遍历：根 -> 左 -> 右
// 方法：preorder；按题目要求处理输入并返回结果，核心算法见方法体。
func preorder(root *TreeNode, result *[]int) {
    if root == nil {
        return // 终止条件：空节点直接返回
    }
    *result = append(*result, root.Val) // 先处理当前节点
    preorder(root.Left, result)         // 再递归左子树
    preorder(root.Right, result)        // 最后递归右子树
}

// 中序遍历：左 -> 根 -> 右
// 方法：inorder；按题目要求处理输入并返回结果，核心算法见方法体。
func inorder(root *TreeNode, result *[]int) {
    if root == nil {
        return
    }
    inorder(root.Left, result)          // 先递归左子树
    *result = append(*result, root.Val) // 左子树处理完后处理当前节点
    inorder(root.Right, result)         // 最后递归右子树
}

// 后序遍历：左 -> 右 -> 根
// 方法：postorder；按题目要求处理输入并返回结果，核心算法见方法体。
func postorder(root *TreeNode, result *[]int) {
    if root == nil {
        return
    }
    postorder(root.Left, result)        // 先递归左子树
    postorder(root.Right, result)       // 再递归右子树
    *result = append(*result, root.Val) // 左右都处理完才处理当前节点
}
```

## 总结

- 二叉树递归遍历的三要素：参数与返回值、终止条件（节点为空）、单层递归逻辑（也就是处理当前节点插入的位置）。
- 前中后序遍历的代码结构完全相同，唯一的区别就是"处理当前节点"这一行代码相对于两次递归调用的位置。
- 递归的时间复杂度是 O(n)，空间复杂度取决于递归调用栈的深度，也就是树的高度 O(h)，最坏情况会退化成 O(n)。
- 理解递归遍历是后面理解迭代遍历（用栈显式模拟）和统一迭代法的基础，说白了迭代版本本质上就是把递归调用栈的行为手动搬到一个显式的栈里去。

08.回溯算法/0017.电话号码的字母组合/0017.电话号码的字母组合.md:
# 0017. 电话号码的字母组合

**题目描述**

给定一个仅包含数字 `2-9` 的字符串，返回所有它能表示的字母组合，按九宫格键盘的映射关系（`2:abc`, `3:def`, `4:ghi`, `5:jkl`, `6:mno`, `7:pqrs`, `8:tuv`, `9:wxyz`）。答案可以按任意顺序返回。

```
示例：
输入：digits = "23"
输出：["ad","ae","af","bd","be","bf","cd","ce","cf"]

输入：digits = ""
输出：[]
```

## 思路

回溯：每层处理一位数字，依次选择其对应字母；处理完全部数字时保存字符串，返回时撤销选择。空输入返回空列表。也可用 `itertools.product` 枚举各位字母的笛卡尔积。

最坏时间 O(n·4ⁿ)，辅助空间 O(n)，不计结果，n 为数字位数。

## 代码

### Python

标准库无直接对应函数可以一行解出九宫格映射结果（`itertools.product` 可以在拿到每位对应的字母表后做笛卡尔积，勉强算"库解"，但本质仍需手动构建字母表，这里只做简要提及）：

```python
from itertools import product

class Solution:
    # 方法：letterCombinations；按题目要求处理输入并返回结果，核心算法见方法体。
    def letterCombinations(self, digits: str) -> list[str]:
        if not digits:
            return []
        letter_map = {'2':'abc','3':'def','4':'ghi','5':'jkl','6':'mno','7':'pqrs','8':'tuv','9':'wxyz'}
        pools = [letter_map[d] for d in digits]      # 每一位对应的候选字母表
        return [''.join(p) for p in product(*pools)]  # 笛卡尔积，仅作对比，非回溯写法
```

手写回溯实现（还原递归树的逐层选择过程）：

```python
class Solution:
    # 方法：letterCombinations；按题目要求处理输入并返回结果，核心算法见方法体。
    def letterCombinations(self, digits: str) -> list[str]:
        if not digits:
            return []  # 边界：空字符串直接返回空结果

        letter_map = {
            '2': 'abc', '3': 'def', '4': 'ghi', '5': 'jkl',
            '6': 'mno', '7': 'pqrs', '8': 'tuv', '9': 'wxyz'
        }
        result = []
        path = []

        # 方法：backtrack；按题目要求处理输入并返回结果，核心算法见方法体。
        def backtrack(index: int):
            if index == len(digits):            # 终止条件：每一位数字都已处理完
                result.append(''.join(path))     # 收集拼出的字母组合
                return
            letters = letter_map[digits[index]]  # 当前数字对应的候选字母表
            for c in letters:                    # 横向遍历本层候选字母
                path.append(c)        # 【选择】
                backtrack(index + 1)  # 【递归】处理下一位数字
                path.pop()             # 【撤销选择】

        backtrack(0)
        return result
```

### C++

```cpp
class Solution {
private:
    // 数字到字母的映射表，下标 0-1 不使用（题目保证不出现 0、1）
    vector<string> letterMap = {
        "", "", "abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"
    };
    vector<string> result;
    string path;

    // 方法：backtrack；按题目要求处理输入并返回结果，核心算法见方法体。
    void backtrack(const string& digits, int index) {
        if (index == digits.size()) {          // 终止条件：每一位数字都已处理完
            result.push_back(path);            // 收集当前拼出的字母组合
            return;
        }
        int digit = digits[index] - '0';        // 取出当前处理的数字
        const string& letters = letterMap[digit]; // 该数字对应的字母表（本层候选集合）
        for (char c : letters) {                 // 横向遍历：本层的每个候选字母
            path.push_back(c);                   // 【选择】把字母加入路径
            backtrack(digits, index + 1);        // 【递归】处理下一位数字
            path.pop_back();                      // 【撤销选择】回退，尝试下一个字母
        }
    }

public:
    // 方法：letterCombinations；按题目要求处理输入并返回结果，核心算法见方法体。
    vector<string> letterCombinations(string digits) {
        if (digits.empty()) return result;   // 边界：空字符串直接返回空结果
        backtrack(digits, 0);
        return result;
    }
};
```


### Go

```go
// 方法：letterCombinations；按题目要求处理输入并返回结果，核心算法见方法体。
func letterCombinations(digits string) []string {
    if len(digits) == 0 {
        return []string{}  // 边界：空字符串直接返回空结果
    }
    letterMap := map[byte]string{
        '2': "abc", '3': "def", '4': "ghi", '5': "jkl",
        '6': "mno", '7': "pqrs", '8': "tuv", '9': "wxyz",
    }
    var result []string
    path := make([]byte, 0, len(digits))

    var backtrack func(index int)
    backtrack = func(index int) {
        if index == len(digits) {              // 终止条件：每一位都已处理完
            result = append(result, string(path))
            return
        }
        letters := letterMap[digits[index]]     // 当前数字对应的候选字母表
        for i := 0; i < len(letters); i++ {     // 横向遍历本层候选字母
            path = append(path, letters[i])     // 【选择】
            backtrack(index + 1)                 // 【递归】
            path = path[:len(path)-1]            // 【撤销选择】
        }
    }
    backtrack(0)
    return result
}
```

## 总结

- 这题的关键区别在于"树的宽度不固定"：每一层的候选集合是由当前数字对应的字母表决定的，而不是像组合问题一样有一个固定的候选区间。
- 不需要 `startIndex` 去重，为什么呢？因为每一位处理的是不同位置的数字，候选字母表天然就不重叠，参数 `index` 只起到"往下推进一层"的作用。
- 递归深度等于 `digits` 的长度，每层的分支数等于该位数字对应的字母个数，这种"多叉树"结构在字符串拼接类回溯题目里很常见。
- 空字符串是一个明确的边界条件，必须在进入递归前单独处理，不然会返回一个包含空字符串的错误结果。

08.回溯算法/0037.解数独/0037.解数独.md:
# 0037. 解数独

**题目描述**

编写一个程序，通过填充空格来解决数独问题。数独的解法需遵循如下规则：数字 1-9 在每一行只能出现一次；数字 1-9 在每一列只能出现一次；数字 1-9 在每一个以粗实线分隔的 3x3 宫内只能出现一次。数独部分空格内已填入了数字，空白格用 `'.'` 表示，需要填入合适的数字使整个数独有唯一解。

```
示例：
输入：一个 9x9 的二维字符数组 board，部分单元格是数字，其余是 '.'
输出：直接在 board 上完成填数（原地修改），使其成为一个解好的数独
```

## 思路

回溯：找到空格，尝试 1～9，同行、同列、同九宫格无冲突才填入并递归。失败则清空；某空格全部尝试失败立即返回，棋盘无空格即成功。

搜索时间上界 O(9ᵐ)，栈空间 O(m)，m 为空格数；固定 9×9 棋盘下空间 O(1)。

## 代码

### Python

```python
class Solution:
    # 方法：solveSudoku；按题目要求处理输入并返回结果，核心算法见方法体。
    def solveSudoku(self, board: list[list[str]]) -> None:
        # 方法：is_valid；按题目要求处理输入并返回结果，核心算法见方法体。
        def is_valid(row: int, col: int, val: str) -> bool:
            for i in range(9):
                if board[row][i] == val:        # 同行冲突
                    return False
                if board[i][col] == val:        # 同列冲突
                    return False
            box_row, box_col = (row // 3) * 3, (col // 3) * 3   # 所在宫格起始坐标
            for r in range(box_row, box_row + 3):
                for c in range(box_col, box_col + 3):
                    if board[r][c] == val:        # 同宫格冲突
                        return False
            return True

        # 方法：backtrack；按题目要求处理输入并返回结果，核心算法见方法体。
        def backtrack() -> bool:
            for row in range(9):
                for col in range(9):
                    if board[row][col] != '.':      # 已有数字，跳过
                        continue
                    for val in '123456789':            # 尝试填入 1-9
                        if not is_valid(row, col, val):
                            continue
                        board[row][col] = val    # 【选择】
                        if backtrack():             # 【递归】
                            return True                   # 已找到完整解，一路向上返回 True
                        board[row][col] = '.'      # 【撤销选择】
                    return False    # 1-9 都不行，当前分支无解
            return True    # 没有空格了，棋盘已填满

        backtrack()
```

### C++

```cpp
class Solution {
private:
    // 方法：isValid；按题目要求处理输入并返回结果，核心算法见方法体。
    bool isValid(vector<vector<char>>& board, int row, int col, char val) {
        for (int i = 0; i < 9; i++) {
            if (board[row][i] == val) return false;       // 同行冲突
            if (board[i][col] == val) return false;       // 同列冲突
        }
        int boxRow = (row / 3) * 3, boxCol = (col / 3) * 3;  // 所在 3x3 宫格起始坐标
        for (int r = boxRow; r < boxRow + 3; r++) {
            for (int c = boxCol; c < boxCol + 3; c++) {
                if (board[r][c] == val) return false;      // 同宫格冲突
            }
        }
        return true;
    }

    // 方法：backtrack；按题目要求处理输入并返回结果，核心算法见方法体。
    bool backtrack(vector<vector<char>>& board) {
        for (int row = 0; row < 9; row++) {
            for (int col = 0; col < 9; col++) {
                if (board[row][col] != '.') continue;   // 已有数字，跳过，处理下一个格子
                for (char val = '1'; val <= '9'; val++) {  // 横向遍历：尝试填入 1-9
                    if (!isValid(board, row, col, val)) continue;  // 冲突则跳过
                    board[row][col] = val;              // 【选择】填入数字
                    if (backtrack(board)) {             // 【递归】处理后续格子
                        return true;                        // 已找到完整解，一路向上返回 true，不再撤销
                    }
                    board[row][col] = '.';                // 【撤销选择】此数字走不通，恢复空格
                }
                return false;   // 1-9 都试过仍不行，说明当前分支无解，返回 false 让上一层换数字
            }
        }
        return true;   // 遍历完所有格子都没有再遇到空格，说明整个棋盘已经填满，成功
    }

public:
    // 方法：solveSudoku；按题目要求处理输入并返回结果，核心算法见方法体。
    void solveSudoku(vector<vector<char>>& board) {
        backtrack(board);   // 原地修改 board，题目不要求返回值
    }
};
```


