// 方法：solveSudoku；按题目要求处理输入并返回结果，核心算法见方法体。
func solveSudoku(board [][]byte) {
    var isValid func(row, col int, val byte) bool
    isValid = func(row, col int, val byte) bool {
        for i := 0; i < 9; i++ {
            if board[row][i] == val {     // 同行冲突
                return false
            }
            if board[i][col] == val {     // 同列冲突
                return false
            }
        }
        boxRow, boxCol := (row/3)*3, (col/3)*3   // 所在宫格起始坐标
        for r := boxRow; r < boxRow+3; r++ {
            for c := boxCol; c < boxCol+3; c++ {
                if board[r][c] == val {     // 同宫格冲突
                    return false
                }
            }
        }
        return true
    }

    var backtrack func() bool
    backtrack = func() bool {
        for row := 0; row < 9; row++ {
            for col := 0; col < 9; col++ {
                if board[row][col] != '.' {    // 已有数字，跳过
                    continue
                }
                for val := byte('1'); val <= '9'; val++ {   // 尝试填入 1-9
                    if !isValid(row, col, val) {
                        continue
                    }
                    board[row][col] = val    // 【选择】
                    if backtrack() {           // 【递归】
                        return true                 // 已找到完整解，一路向上返回 true
                    }
                    board[row][col] = '.'      // 【撤销选择】
                }
                return false   // 1-9 都不行，当前分支无解
            }
        }
        return true   // 没有空格了，棋盘已填满
    }
    backtrack()
}
```

## 总结

- 数独是二维回溯（需要同时定位行 `row` 和列 `col` 两个维度），跟 N 皇后的一维行递归不一样，本质是因为每行可能有多个空格需要处理，不存在"每行只决策一次"的天然结构。
- 判断合法性需要同时检查行、列、3x3 宫格三个约束，宫格起始坐标用 `(row/3)*3` 和 `(col/3)*3` 计算，这是数独问题特有的第三重约束。
- 终止条件的设计是这题的核心难点：`backtrack` 函数必须返回布尔值表示"是否已经找到完整解"，找到解后要让 `true` 一路沿递归调用链向上传递直到最外层，中途不能撤销已经填好的数字，不然会破坏已经找到的正确解。
- 跟 0332 重新安排行程很相似，这题也是"只需要找到一个解就终止整个搜索"的回溯场景，这类题目的通用处理方式是让回溯函数带返回值，通过返回值的传递控制是否继续尝试其他分支。

08.回溯算法/0039.组合总和/0039.组合总和.md:
# 0039. 组合总和

**题目描述**

给定一个无重复元素的整数数组 `candidates` 和一个目标整数 `target`，找出 `candidates` 中可以使数字和为目标数 `target` 的所有不同组合，`candidates` 中的**同一个数字可以无限制重复被选取**。返回的组合中不能有重复的组合。

```
示例：
输入: candidates = [2,3,6,7], target = 7
输出: [[2,2,3],[7]]

输入: candidates = [2,3,5], target = 8
输出: [[2,2,2,2],[2,3,3],[3,5]]
```

## 思路

排序＋回溯：从 `startIndex` 选数，递归仍从 `i` 开始，允许重复使用；下标不回退，避免排列重复。和等于目标收集，超过目标则停止当前及后续分支，返回时撤销。

令 d=⌊target/min(candidates)⌋、n 为候选数。粗略时间上界 O(n log n+(n+1)ᵈ·(d+1))，辅助空间 O(n+d)，不计结果。

## 代码

### Python

```python
class Solution:
    # 方法：combinationSum；按题目要求处理输入并返回结果，核心算法见方法体。
    def combinationSum(self, candidates: list[int], target: int) -> list[list[int]]:
        candidates.sort()  # 排序是剪枝的前提
        result = []
        path = []
        path_sum = 0

        # 方法：backtrack；按题目要求处理输入并返回结果，核心算法见方法体。
        def backtrack(start_index: int):
            nonlocal path_sum
            if path_sum == target:              # 终止条件：和恰好等于 target
                result.append(path[:])
                return
            for i in range(start_index, len(candidates)):
                if path_sum + candidates[i] > target:  # 剪枝：已排序，超过 target 直接结束
                    break
                path.append(candidates[i])       # 【选择】
                path_sum += candidates[i]
                backtrack(i)                      # 【递归】传 i，允许重复选取当前数字（不是 i+1）
                path_sum -= candidates[i]          # 【撤销选择】
                path.pop()                          # 【撤销选择】

        backtrack(0)
        return result
```

### C++

```cpp
class Solution {
private:
    vector<vector<int>> result;
    vector<int> path;
    int pathSum = 0;

    // 方法：backtrack；按题目要求处理输入并返回结果，核心算法见方法体。
    void backtrack(vector<int>& candidates, int target, int startIndex) {
        if (pathSum == target) {           // 终止条件：和恰好等于 target
            result.push_back(path);
            return;
        }
        for (int i = startIndex; i < candidates.size(); i++) {
            if (pathSum + candidates[i] > target) {  // 剪枝：candidates 已排序，超过 target 直接结束
                break;
            }
            path.push_back(candidates[i]);   // 【选择】
            pathSum += candidates[i];
            backtrack(candidates, target, i);  // 【递归】传 i 而不是 i+1，允许重复选取当前数字
            pathSum -= candidates[i];          // 【撤销选择】
            path.pop_back();                    // 【撤销选择】
        }
    }

public:
    vector<vector<int>> combinationSum(vector<int>& candidates, int target) {
        sort(candidates.begin(), candidates.end());  // 排序是剪枝的前提
        backtrack(candidates, target, 0);
        return result;
    }
};
```


### Go

```go
// 方法：combinationSum；按题目要求处理输入并返回结果，核心算法见方法体。
func combinationSum(candidates []int, target int) [][]int {
    sort.Ints(candidates)  // 排序是剪枝的前提
    var result [][]int
    var path []int
    pathSum := 0

    var backtrack func(startIndex int)
    backtrack = func(startIndex int) {
        if pathSum == target {                    // 终止条件：和恰好等于 target
            tmp := make([]int, len(path))
            copy(tmp, path)
            result = append(result, tmp)
            return
        }
        for i := startIndex; i < len(candidates); i++ {
            if pathSum+candidates[i] > target {   // 剪枝：已排序，超过 target 直接结束
                break
            }
            path = append(path, candidates[i])    // 【选择】
            pathSum += candidates[i]
            backtrack(i)                           // 【递归】传 i，允许重复选取当前数字
            pathSum -= candidates[i]                // 【撤销选择】
            path = path[:len(path)-1]               // 【撤销选择】
        }
    }
    backtrack(0)
    return result
}
```

## 总结

- 跟 0077/0216 的核心区别其实就是递归调用传参从 `i+1` 变成了 `i`，一字之差，却决定了"当前元素能不能被重复选取"，这是理解这道题最关键的一点。
- `startIndex` 依然保留，但它的作用变了：从"避免同一数字重复选取"变成了"避免不同数字的选择顺序导致重复组合"，这两个作用一定要分清楚，不能混为一谈。
- 剪枝依赖排序：先排好序之后，一旦当前候选数字加上路径和超过了 target，后面的候选数字（更大）必然也会超过，这时候可以直接 `break`，而不是 `continue`。
- 递归深度不再受固定的 `k` 限制了，而是取决于 `target` 和候选数组里最小值的比值，这就是允许重复选取带来的直接影响。

08.回溯算法/0040.组合总和II/0040.组合总和II.md:
# 0040. 组合总和 II

**题目描述**

给定一个候选数组 `candidates` 和一个目标数 `target`，找出 `candidates` 中所有可以使数字和为 `target` 的组合。`candidates` 中的**每个数字在每个组合中只能使用一次**，但数组本身**可能包含重复数字**，解集不能包含重复的组合。

```
示例：
输入: candidates = [10,1,2,7,6,1,5], target = 8
输出:
[
[1,1,6],
[1,2,5],
[1,7],
[2,6]
]
```

## 思路

排序＋回溯：递归从 `i+1` 开始，每个元素仅用一次。同层遇到 `i>startIndex` 且与前值相等则跳过；和超目标直接结束循环，和等于目标保存结果，返回时撤销。

最坏时间 O(n·2ⁿ)，辅助空间 O(n)，不计结果。

## 代码

### Python

```python
class Solution:
    # 方法：combinationSum2；按题目要求处理输入并返回结果，核心算法见方法体。
    def combinationSum2(self, candidates: list[int], target: int) -> list[list[int]]:
        candidates.sort()  # 排序，为去重和剪枝做准备
        result = []
        path = []
        path_sum = 0

        # 方法：backtrack；按题目要求处理输入并返回结果，核心算法见方法体。
        def backtrack(start_index: int):
            nonlocal path_sum
            if path_sum == target:                  # 终止条件：和恰好等于 target
                result.append(path[:])
                return
            for i in range(start_index, len(candidates)):
                if path_sum + candidates[i] > target:   # 剪枝：已排序，超过 target 直接结束
                    break
                # 树层去重：i > start_index 表示不是本层第一个位置，
                # 值相同则说明会产生与前一个分支相同的组合，跳过
                if i > start_index and candidates[i] == candidates[i - 1]:
                    continue
                path.append(candidates[i])           # 【选择】
                path_sum += candidates[i]
                backtrack(i + 1)                       # 【递归】i+1，同一数字不重复使用
                path_sum -= candidates[i]               # 【撤销选择】
                path.pop()                               # 【撤销选择】

        backtrack(0)
        return result
```

### C++

```cpp
class Solution {
private:
    vector<vector<int>> result;
    vector<int> path;
    int pathSum = 0;

    // 方法：backtrack；按题目要求处理输入并返回结果，核心算法见方法体。
    void backtrack(vector<int>& candidates, int target, int startIndex) {
        if (pathSum == target) {              // 终止条件：和恰好等于 target
            result.push_back(path);
            return;
        }
        for (int i = startIndex; i < candidates.size(); i++) {
            if (pathSum + candidates[i] > target) {  // 剪枝：已排序，超过 target 直接结束
                break;
            }
            // 树层去重：i > startIndex 表示不是本层第一个位置，
            // 且当前值与前一个值相同，说明这个分支和前一个分支会产生完全相同的组合，跳过
            if (i > startIndex && candidates[i] == candidates[i - 1]) {
                continue;
            }
            path.push_back(candidates[i]);       // 【选择】
            pathSum += candidates[i];
            backtrack(candidates, target, i + 1); // 【递归】i+1，保证同一数字不被重复使用（树枝去重已由此保证）
            pathSum -= candidates[i];              // 【撤销选择】
            path.pop_back();                        // 【撤销选择】
        }
    }

public:
    vector<vector<int>> combinationSum2(vector<int>& candidates, int target) {
        sort(candidates.begin(), candidates.end());  // 排序，为去重和剪枝做准备
        backtrack(candidates, target, 0);
        return result;
    }
};
```


### Go

```go
// 方法：combinationSum2；按题目要求处理输入并返回结果，核心算法见方法体。
func combinationSum2(candidates []int, target int) [][]int {
    sort.Ints(candidates)  // 排序，为去重和剪枝做准备
    var result [][]int
    var path []int
    pathSum := 0

    var backtrack func(startIndex int)
    backtrack = func(startIndex int) {
        if pathSum == target {                        // 终止条件：和恰好等于 target
            tmp := make([]int, len(path))
            copy(tmp, path)
            result = append(result, tmp)
            return
        }
        for i := startIndex; i < len(candidates); i++ {
            if pathSum+candidates[i] > target {       // 剪枝：已排序，超过 target 直接结束
                break
            }
            // 树层去重：i > startIndex 表示不是本层第一个位置，值相同则跳过
            if i > startIndex && candidates[i] == candidates[i-1] {
                continue
            }
            path = append(path, candidates[i])        // 【选择】
            pathSum += candidates[i]
            backtrack(i + 1)                           // 【递归】i+1，同一数字不重复使用
            pathSum -= candidates[i]                     // 【撤销选择】
            path = path[:len(path)-1]                     // 【撤销选择】
        }
    }
    backtrack(0)
    return result
}
```

## 总结

- 树层去重解决的是"同一层内相邻分支值相同导致的重复组合"，树枝去重解决的是"同一条路径上同一个数字被重复使用"，这两者是完全不同维度的问题，这题需要同时处理。
- 树枝去重靠 `startIndex` 从 `i+1` 开始递归天然就满足了，不需要额外代码；树层去重则需要显式加上 `i > startIndex && candidates[i] == candidates[i-1]` 这个判断。
- `i > startIndex` 是树层去重判断里最容易漏掉、但又最关键的一个条件，它把去重的作用范围限定在"同一层的横向比较"，避免误伤合法的树枝分支（比如示例中的 `[1,1,6]`）。
- 排序是这题去重和剪枝能成立的共同前提，你想啊，没有排序，相同数值根本不会相邻，也就没法通过比较 `candidates[i]` 和 `candidates[i-1]` 来判断是否重复了。

