# 0491. 递增子序列

**题目描述**

给定一个整数数组 `nums`，找出并返回所有该数组中不同的递增子序列，递增子序列中**至少有两个元素**。数组中可能含有重复元素，如果出现两个由**相同数字序列**组成的递增子序列，只需要返回一个。

```
示例：
输入: nums = [4,6,7,7]
输出: [[4,6],[4,6,7],[4,6,7,7],[4,7],[4,7,7],[6,7],[6,7,7],[7,7]]

输入: nums = [4,4,3,2,1]
输出: [[4,4]]
```

## 思路

回溯保持原下标顺序，不能排序。只选不小于路径末值的元素；每层用独立集合跳过重复值。长度至少为 2 就保存，递归从 `i+1` 开始，返回时撤销路径。

最坏时间 O(n·2ⁿ)，辅助空间 O(n·min(n,U))，不计结果；U 为值域大小，本题固定值域下为 O(n)。

## 代码

### Python

```python
class Solution:
    # 方法：findSubsequences；按题目要求处理输入并返回结果，核心算法见方法体。
    def findSubsequences(self, nums: list[int]) -> list[list[int]]:
        result = []
        path = []

        # 方法：backtrack；按题目要求处理输入并返回结果，核心算法见方法体。
        def backtrack(start_index: int):
            if len(path) >= 2:               # 满足长度>=2的每个节点都收集
                result.append(path[:])
            used = set()                      # 本层去重专用，局部变量，每次进入函数重新创建
            for i in range(start_index, len(nums)):
                # 递增校验：path 非空时，当前值必须 >= path 最后一个元素
                if path and nums[i] < path[-1]:
                    continue
                # 树层去重：不排序，直接用哈希 set 判断本层是否已用过这个值
                if nums[i] in used:
                    continue
                used.add(nums[i])             # 记录本层已使用的数值
                path.append(nums[i])           # 【选择】
                backtrack(i + 1)                 # 【递归】
                path.pop()                        # 【撤销选择】

        backtrack(0)
        return result
```

### C++

```cpp
class Solution {
private:
    vector<vector<int>> result;
    vector<int> path;

    // 方法：backtrack；按题目要求处理输入并返回结果，核心算法见方法体。
    void backtrack(vector<int>& nums, int startIndex) {
        if (path.size() >= 2) {          // 子序列问题：满足长度>=2的每个节点都收集
            result.push_back(path);
        }
        unordered_set<int> used;          // 本层去重专用，只在当前递归层生效（局部变量）
        for (int i = startIndex; i < nums.size(); i++) {
            // 递增校验：path 非空时，当前值必须 >= path 最后一个元素
            if (!path.empty() && nums[i] < path.back()) {
                continue;
            }
            // 树层去重：本层已经用过这个数值，跳过（不依赖排序，直接用哈希 set 记录）
            if (used.find(nums[i]) != used.end()) {
                continue;
            }
            used.insert(nums[i]);          // 记录本层已使用的数值
            path.push_back(nums[i]);       // 【选择】
            backtrack(nums, i + 1);        // 【递归】
            path.pop_back();                 // 【撤销选择】
        }
    }

public:
    vector<vector<int>> findSubsequences(vector<int>& nums) {
        backtrack(nums, 0);
        return result;
    }
};
```


### Go

```go
// 方法：findSubsequences；按题目要求处理输入并返回结果，核心算法见方法体。
func findSubsequences(nums []int) [][]int {
    var result [][]int
    var path []int

    var backtrack func(startIndex int)
    backtrack = func(startIndex int) {
        if len(path) >= 2 {                    // 满足长度>=2的每个节点都收集
            tmp := make([]int, len(path))
            copy(tmp, path)
            result = append(result, tmp)
        }
        used := make(map[int]bool)              // 本层去重专用，局部变量，每次进入函数重新创建
        for i := startIndex; i < len(nums); i++ {
            // 递增校验：path 非空时，当前值必须 >= path 最后一个元素
            if len(path) > 0 && nums[i] < path[len(path)-1] {
                continue
            }
            // 树层去重：不排序，直接用哈希 map 判断本层是否已用过这个值
            if used[nums[i]] {
                continue
            }
            used[nums[i]] = true               // 记录本层已使用的数值
            path = append(path, nums[i])        // 【选择】
            backtrack(i + 1)                      // 【递归】
            path = path[:len(path)-1]              // 【撤销选择】
        }
    }
    backtrack(0)
    return result
}
```

## 总结

- 这题不能排序，为什么呢？因为要保持"子序列"相对于原数组的顺序，这是跟 0040/0090 题最本质的区别，直接决定了去重方式必须改变。
- 去重改用哈希 set 记录"本层已经使用过的数值"，`set` 必须是每层递归独立的局部变量，只对同一层内的重复值生效，不影响不同层选择相同数值（比如 `[4,4]`）。
- 判断递增用 `path` 的最后一个元素跟当前候选值比较，允许相等（非严格递增），这就是本题结果里能出现 `[7,7]`、`[4,4]` 这类相邻相等值组合的原因。
- 这题是"子集类"收集方式（每个满足条件的节点都收集，不是只收集叶子），额外叠加了递增约束和长度 >= 2 的限制，是子集问题的进阶变形。

08.回溯算法/回溯算法去重问题的另一种写法/回溯算法去重问题的另一种写法.md:
# 回溯算法去重问题的另一种写法

**题目描述**

本篇不针对具体题目，是一篇方法论文档，介绍回溯去重的另一种实现方式——不排序，直接用哈希 set 记录本层已经使用过的值，并对比这种写法和"排序 + 相邻去重"两种方式的适用场景与效率差异。

## 思路

- 排序＋相邻比较：可排序时，同层跳过相同值；额外去重空间 O(1)，排序时间 O(n log n)。

```
if (i > startIndex && nums[i] == nums[i-1]) continue;
```

- 每层集合：不能排序或需保留原序时，记录本层已选值；平均单次判断 O(1)，每层最多 O(n) 空间。

```
unordered_set<int> used;  // 本层去重，进入函数时新建
for (...) {
    if (used.count(nums[i])) continue;
    used.insert(nums[i]);
    ...
}
```

集合用于同层去重；路径中的下标是否可复用，由 `startIndex/used` 单独控制。总复杂度取决于搜索树及结果复制。

## 代码

### Python

```python
# 写法一：排序 + 相邻去重
# 方法：backtrack_sorted；按题目要求处理输入并返回结果，核心算法见方法体。
def backtrack_sorted(nums, start_index, path, result):
    result.append(path[:])
    for i in range(start_index, len(nums)):
        if i > start_index and nums[i] == nums[i - 1]:   # 相邻位置比较去重
            continue
        path.append(nums[i])
        backtrack_sorted(nums, i + 1, path, result)
        path.pop()

# 写法二：哈希 set 去重
# 方法：backtrack_hashset；按题目要求处理输入并返回结果，核心算法见方法体。
def backtrack_hashset(nums, start_index, path, result):
    result.append(path[:])
    used = set()          # 每层新建，记录本层已处理过的数值
    for i in range(start_index, len(nums)):
        if nums[i] in used:    # 值已出现过，跳过
            continue
        used.add(nums[i])
        path.append(nums[i])
        backtrack_hashset(nums, i + 1, path, result)
        path.pop()
```

由于本篇是方法论对比，以下用 0090 子集 II 的双写法对照，展示两种去重方式在同一问题上的实现差异。

### C++

```cpp
// 写法一：排序 + 相邻去重（要求数组可排序）
// 方法：backtrackSorted；按题目要求处理输入并返回结果，核心算法见方法体。
void backtrackSorted(vector<int>& nums, int startIndex, vector<int>& path, vector<vector<int>>& result) {
    result.push_back(path);
    for (int i = startIndex; i < nums.size(); i++) {
        if (i > startIndex && nums[i] == nums[i - 1]) continue;  // 相邻位置比较去重
        path.push_back(nums[i]);
        backtrackSorted(nums, i + 1, path, result);
        path.pop_back();
    }
}

// 写法二：哈希 set 去重（不要求排序，通用写法）
// 方法：backtrackHashSet；按题目要求处理输入并返回结果，核心算法见方法体。
void backtrackHashSet(vector<int>& nums, int startIndex, vector<int>& path, vector<vector<int>>& result) {
    result.push_back(path);
    unordered_set<int> used;   // 每层新建，记录本层已处理过的数值
    for (int i = startIndex; i < nums.size(); i++) {
        if (used.count(nums[i])) continue;  // 值已出现过，跳过
        used.insert(nums[i]);
        path.push_back(nums[i]);
        backtrackHashSet(nums, i + 1, path, result);
        path.pop_back();
    }
}
```


### Go

```go
// 写法一：排序 + 相邻去重
// 方法：backtrackSorted；按题目要求处理输入并返回结果，核心算法见方法体。
func backtrackSorted(nums []int, startIndex int, path *[]int, result *[][]int) {
    tmp := make([]int, len(*path))
    copy(tmp, *path)
    *result = append(*result, tmp)
    for i := startIndex; i < len(nums); i++ {
        if i > startIndex && nums[i] == nums[i-1] { // 相邻位置比较去重
            continue
        }
        *path = append(*path, nums[i])
        backtrackSorted(nums, i+1, path, result)
        *path = (*path)[:len(*path)-1]
    }
}

// 写法二：哈希 set 去重（Go 用 map[int]bool 模拟 set）
// 方法：backtrackHashSet；按题目要求处理输入并返回结果，核心算法见方法体。
func backtrackHashSet(nums []int, startIndex int, path *[]int, result *[][]int) {
    tmp := make([]int, len(*path))
    copy(tmp, *path)
    *result = append(*result, tmp)
    used := make(map[int]bool)   // 每层新建
    for i := startIndex; i < len(nums); i++ {
        if used[nums[i]] {         // 值已出现过，跳过
            continue
        }
        used[nums[i]] = true
        *path = append(*path, nums[i])
        backtrackHashSet(nums, i+1, path, result)
        *path = (*path)[:len(*path)-1]
    }
}
```

## 总结

- "排序 + 相邻去重"和"哈希 set 去重"解决的其实是同一个问题（同一层内避免重复选择相同数值），前者依赖排序带来的物理相邻性，后者用额外的数据结构直接记录"本层出现过的值"，不依赖数组的顺序。
- 当题目要求保持原始相对顺序（不能排序）的时候，只能用哈希 set 去重，这就是 0491 题必须采用这种写法的根本原因。
- 当题目允许排序的时候，两种写法都能得到正确结果，"排序 + 相邻去重"通常常数开销更小，是更常见的首选写法；哈希 set 写法更通用，但每层新建 `set` 有额外的空间和时间开销。
- 理解这两种去重方式本质上相通的地方（都是判断"本层是否已经处理过这个数值"），有助于在面对新的去重变形题时灵活选择合适的实现方式，而不是死记某一种固定写法。

09.贪心算法/0053.最大子序和/0053.最大子序和.md:
# 0053. 最大子序和

**题目描述**

给定一个整数数组 `nums`，请找到一个具有最大和的连续子数组（子数组最少包含一个元素），返回其最大和。

```
示例：
输入: nums = [-2,1,-3,4,-1,2,1,-5,4]
输出: 6
解释: 连续子数组 [4,-1,2,1] 的和最大，为 6。
```

## 思路

- 贪心：累加当前段，先更新最大和；若累计和为负则清零，负前缀只会拖累后续。答案初始化为数组首值，处理全负数。时间 O(n)，空间 O(1)。
- DP：以 `i` 结尾的最大和为 `dp[i]=max(nums[i],dp[i-1]+nums[i])`，取全局最大值。时间 O(n)，数组空间 O(n)，滚动变量 O(1)。

## 代码

### Python

```python
class Solution:
    # 方法：maxSubArray；按题目要求处理输入并返回结果，核心算法见方法体。
    def maxSubArray(self, nums: list[int]) -> int:
        result = float('-inf')  # 记录出现过的最大和
        count = 0                # 当前累加和
        for num in nums:
            count += num  # 累加当前元素
            if count > result:
                result = count  # 更新历史最大值
            if count < 0:
                count = 0  # 累加和为负，丢弃这段前缀，重新从0开始累加
        return result
```

### C++

```cpp
class Solution {
public:
    // 方法：maxSubArray；按题目要求处理输入并返回结果，核心算法见方法体。
    int maxSubArray(vector<int>& nums) {
        int result = INT_MIN;  // 记录遍历过程中出现过的最大和
        int count = 0;         // 当前累加和
        for (int i = 0; i < nums.size(); i++) {
            count += nums[i];           // 把当前元素计入累加和
            if (count > result) {
                result = count;         // 更新历史最大值
            }
            if (count < 0) {
                count = 0;  // 累加和为负，说明这段前缀只会拖累后面，重置为0重新开始
            }
        }
        return result;
    }
};
```


### Go

```go
// 方法：maxSubArray；按题目要求处理输入并返回结果，核心算法见方法体。
func maxSubArray(nums []int) int {
    result := math.MinInt32 // 记录出现过的最大和
    count := 0              // 当前累加和
    for _, num := range nums {
        count += num // 累加当前元素
        if count > result {
            result = count // 更新历史最大值
        }
        if count < 0 {
            count = 0 // 为负说明这段前缀拖累后续结果，清零重新开始
        }
    }
    return result
}
```

## 总结

- 贪心策略的核心就是"累加和一旦为负就清零重新计数"，因为带着负的前缀往后走只会拖累后面的和，永远不会比丢弃它更好。
- 正确性可以用反证法来说明：如果最优子数组的某段前缀和为负，那去掉这段前缀后剩余部分的和会更大，这就跟"该子数组是全局最优"矛盾了，所以最优解永远不会以负的前缀开头。
- `result` 要在每一步累加后立即更新，不能只在清零时才更新，不然会漏掉最大值恰好出现在清零之前的情况。
- 贪心解法本质上是 DP 解法 `dp[i] = max(dp[i-1] + nums[i], nums[i])` 的空间优化版本，因为状态转移只依赖前一个状态，用一个滚动变量就能代替整个 dp 数组。

09.贪心算法/0055.跳跃游戏/0055.跳跃游戏.md:
# 0055. 跳跃游戏

**题目描述**

给定一个非负整数数组 `nums`，你最初位于数组的第一个下标。数组中的每个元素代表你在该位置可以跳跃的最大长度。判断你是否能够到达最后一个下标。

```
示例：
输入: nums = [2,3,1,1,4]
输出: true
解释: 可以先跳1步，从下标0到达下标1，然后再从下标1跳3步到达最后一个下标。

输入: nums = [3,2,1,0,4]
输出: false
解释: 无论怎样，总会到达下标3。但该下标的最大跳跃长度是0，
      所以永远不可能到达最后一个下标。
```

## 思路

贪心维护最远可达下标 `cover=0`。若 `i>cover` 则不可达，否则更新 `cover=max(cover,i+nums[i])`；覆盖末尾即成功。

时间 O(n)，空间 O(1)。

## 代码

### Python

```python
class Solution:
    # 方法：canJump；按题目要求处理输入并返回结果，核心算法见方法体。
    def canJump(self, nums: list[int]) -> bool:
        cover = 0  # 当前能到达的最远下标
        for i in range(len(nums)):
            if i > cover:
                return False  # 当前下标不可达，起跳点本身够不到
            cover = max(cover, i + nums[i])  # 更新最远覆盖范围
        return True
```

### C++

```cpp
class Solution {
public:
    // 方法：canJump；按题目要求处理输入并返回结果，核心算法见方法体。
    bool canJump(vector<int>& nums) {
        int cover = 0;  // 当前能到达的最远下标
        for (int i = 0; i < nums.size(); i++) {
            if (i > cover) {
                return false;  // 当前下标本身已不可达，后面再大的跳跃也没用
            }
            cover = max(cover, i + nums[i]);  // 用当前可达位置更新最远覆盖范围
        }
        return true;  // 遍历完仍未提前返回false，说明所有位置都可达
    }
};
```


### Go

```go
// 方法：canJump；按题目要求处理输入并返回结果，核心算法见方法体。
func canJump(nums []int) bool {
    cover := 0 // 当前能到达的最远下标
    for i := 0; i < len(nums); i++ {
        if i > cover {
            return false // 当前下标不可达，直接判定失败
        }
        if i+nums[i] > cover {
            cover = i + nums[i] // 用当前可达位置更新最远覆盖范围
        }
    }
    return true
}
```

## 总结

- 贪心策略就是维护一个"最远可达覆盖范围" `cover`，遍历过程中不断用每个可达位置能提供的跳跃范围去更新它，根本不需要模拟具体的跳跃路径。
- 正确性的关键在于：一个位置能跳多远，是它自带的属性（由 `nums[i]` 决定），跟到达它的路径没关系，所以把所有可达位置的覆盖范围合并起来，就等价于穷举了所有路径组合的能力上限。
- 一旦发现某个下标超过了当前覆盖范围，说明这个位置本身就到不了，可以直接判定失败并提前返回，不用继续遍历。
- 这道题只关心"能不能到达"，跟45题"最少跳跃次数"是相关但不同的问题，本题的 `cover` 只需要合并更新，不用额外统计跳跃次数。

09.贪心算法/0056.合并区间/0056.合并区间.md:
# 0056. 合并区间

**题目描述**

给定一个区间的集合 `intervals`，其中 `intervals[i] = [starti, endi]`，请合并所有重叠的区间，并返回一个不重叠的区间数组，该数组需恰好覆盖输入中的所有区间。

```
示例：
输入: intervals = [[1,3],[2,6],[8,10],[15,18]]
输出: [[1,6],[8,10],[15,18]]
解释: 区间 [1,3] 和 [2,6] 重叠，将它们合并为 [1,6]。
```

## 思路

按左端点排序，与结果中最后一个区间比较：相交则将右端点更新为两者最大值，否则加入新区间。端点相等也合并。

时间 O(n log n)，空间 O(n)（含结果及排序）。

## 代码

### Python

```python
class Solution:
    # 方法：merge；按题目要求处理输入并返回结果，核心算法见方法体。
    def merge(self, intervals: list[list[int]]) -> list[list[int]]:
        if not intervals:
            return []
        intervals.sort(key=lambda x: x[0])  # 按左边界从小到大排序

        result = [intervals[0]]  # 第一个区间直接作为结果集的起点
        for i in range(1, len(intervals)):
            if intervals[i][0] <= result[-1][1]:
                # 左边界不超过结果集最后一个区间的右边界，发生重叠，合并
                result[-1][1] = max(result[-1][1], intervals[i][1])  # 取较大右边界
            else:
                # 不重叠，作为新区间加入结果集
                result.append(intervals[i])
        return result
```

### C++

```cpp
class Solution {
public:
    vector<vector<int>> merge(vector<vector<int>>& intervals) {
        if (intervals.empty()) return {};
        // 按左边界从小到大排序
        sort(intervals.begin(), intervals.end(),
             [](const vector<int>& a, const vector<int>& b) { return a[0] < b[0]; });

        vector<vector<int>> result;
        result.push_back(intervals[0]);  // 第一个区间直接作为结果集的起点

        for (int i = 1; i < intervals.size(); i++) {
            if (intervals[i][0] <= result.back()[1]) {
                // 左边界不超过结果集最后一个区间的右边界，发生重叠，需要合并
                result.back()[1] = max(result.back()[1], intervals[i][1]);  // 取较大右边界
            } else {
                // 不重叠，作为新区间加入结果集
                result.push_back(intervals[i]);
            }
        }
        return result;
    }
};
```


### Go

```go
import "sort"

// 方法：merge；按题目要求处理输入并返回结果，核心算法见方法体。
func merge(intervals [][]int) [][]int {
    if len(intervals) == 0 {
        return [][]int{}
    }
    // 按左边界从小到大排序
    sort.Slice(intervals, func(i, j int) bool {
        return intervals[i][0] < intervals[j][0]
    })

    result := [][]int{intervals[0]} // 第一个区间直接作为结果集的起点
    for i := 1; i < len(intervals); i++ {
        last := result[len(result)-1]
        if intervals[i][0] <= last[1] {
            // 左边界不超过结果集最后一个区间的右边界，发生重叠，合并（取较大右边界）
            if intervals[i][1] > last[1] {
                last[1] = intervals[i][1]
            }
        } else {
            // 不重叠，作为新区间加入结果集
            result = append(result, intervals[i])
        }
    }
    return result
}
```

## 总结

- 按左边界排序之后，只需要拿当前区间和结果集最后一个区间比较就能判断重叠，为什么呢？因为排序和合并这个过程一起保证了结果集内部右边界非递减，不可能跟更早的区间产生"漏判"的重叠。
- 合并的时候取两者右边界的较大值，是保证"恰好覆盖所有输入区间"这个要求的必要操作，少取了就会丢失部分原始区间的范围。
- "排序后线性遍历"是区间类问题的通用处理范式，把原本复杂的两两比较关系转化成局部相邻区间的顺序关系，这是贪心算法处理区间问题的核心技巧。
- 这道题跟 452、435 题共享同一套处理框架，差异主要体现在最终要产出的结果形式上——这里是返回合并后的区间列表，而不是统计数量。

09.贪心算法/0122.买卖股票的最佳时机II/0122.买卖股票的最佳时机I:
# 0122. 买卖股票的最佳时机II

**题目描述**

给定一个数组 `prices`，其中 `prices[i]` 表示某支股票第 `i` 天的价格。你可以尽可能多地完成交易（多次买入卖出一支股票），但不能同时参与多笔交易（也就是说，必须先卖出手中持有的股票，才能再次购买）。返回你能获得的最大利润。

```
示例：
输入: prices = [7,1,5,3,6,4]
输出: 7
解释: 第2天（股价=1）买入，第3天（股价=5）卖出，这笔交易利润 = 5-1 = 4。
      第4天（股价=3）买入，第5天（股价=6）卖出，这笔交易利润 = 6-3 = 3。
      总利润为 4+3 = 7。
```

## 思路

贪心累加所有正的相邻价差：`sum(max(0,prices[i]-prices[i-1]))`。一段上涨的总利润等于其中每日涨幅之和。

时间 O(n)，空间 O(1)。

## 代码

### Python

```python
class Solution:
    # 方法：maxProfit；按题目要求处理输入并返回结果，核心算法见方法体。
    def maxProfit(self, prices: list[int]) -> int:
        result = 0  # 累加所有正的价格差
        for i in range(1, len(prices)):
            diff = prices[i] - prices[i - 1]  # 今天相对昨天的涨跌幅
            if diff > 0:
                result += diff  # 涨了就吃下这部分利润
            # 跌了直接跳过，不进行这次交易
        return result
```

### C++

```cpp
class Solution {
public:
    // 方法：maxProfit；按题目要求处理输入并返回结果，核心算法见方法体。
    int maxProfit(vector<int>& prices) {
        int result = 0;  // 累加所有正的价格差
        for (int i = 1; i < prices.size(); i++) {
            int diff = prices[i] - prices[i - 1];  // 今天相对昨天的涨跌幅
            if (diff > 0) {
                result += diff;  // 涨了就吃下这部分利润（相当于昨买今卖）
            }
            // 跌了（diff<=0）直接跳过，不进行这次交易，避免产生亏损
        }
        return result;
    }
};
```


### Go

```go
// 方法：maxProfit；按题目要求处理输入并返回结果，核心算法见方法体。
func maxProfit(prices []int) int {
    result := 0 // 累加所有正的价格差
    for i := 1; i < len(prices); i++ {
        diff := prices[i] - prices[i-1] // 今天相对昨天的涨跌幅
        if diff > 0 {
            result += diff // 涨了就把这部分涨幅计入利润
        }
        // 跌了就跳过，不进行这次交易
    }
    return result
}
```

## 总结

- 贪心策略就是把整体买卖利润拆解成逐日价差之和，只累加正的价差，负的价差直接跳过。
- 正确性的关键在于一个恒等式：任意一段持有区间的整体利润，等于区间内每天价差的累加和（中间项两两抵消），这跟实际股价走势没关系，是纯代数事实。
- 因为允许多次买卖且没有次数限制，逐日贪心不仅能完整捕获所有上升行情的收益，还能自动规避掉下跌段造成的损失，等价于全局最优解。
- 本题跟"最大子序和"（0053）都用到了"逐步累加、按正负筛选"的思路，但本题的贪心证明依赖的是"利润拆解成逐日差值之和"这一恒等式，而不是"负前缀不可能贡献最优解"的论证方式，两者的贪心角度是不一样的。

09.贪心算法/0135.分发糖果/0135.分发糖果.md:
# 0135. 分发糖果

**题目描述**

老师想给孩子们分发糖果，有 `n` 个孩子站成一排，每个孩子获得的糖果数量必须大于等于 1。老师会根据孩子们的表现给每个孩子一个评分数组 `ratings`，要求：

- 相邻两个孩子中，评分更高的孩子必须获得更多的糖果；
- 求满足以上条件所需要的最少糖果数总和。

```
示例：
输入: ratings = [1,0,2]
输出: 5
解释: 你可以分别给这三个孩子分发 2、1、2 颗糖果。

输入: ratings = [1,2,2]
输出: 4
解释: 你可以分别给这三个孩子分发 1、2、1 颗糖果。
第三个孩子只得到 1 颗糖果，这满足题面中的两个条件，因为评分相同的两个孩子不要求糖果数量的相对关系。
```

## 思路

每人先分 1 颗。从左向右，评分更高者至少比左邻多一颗；从右向左，评分更高者取 `max(已有糖果,右邻糖果+1)`，兼顾两侧约束，最后求和。

时间 O(n)，空间 O(n)。

## 代码

### Python

```python
class Solution:
    # 方法：candy；按题目要求处理输入并返回结果，核心算法见方法体。
    def candy(self, ratings: list[int]) -> int:
        n = len(ratings)
        candy_arr = [1] * n  # 每个孩子至少 1 颗糖果

        # 从左到右：处理右边比左边评分高的情况
        for i in range(1, n):
            if ratings[i] > ratings[i - 1]:
                candy_arr[i] = candy_arr[i - 1] + 1

        # 从右到左：处理左边比右边评分高的情况，取较大值避免覆盖
        for i in range(n - 2, -1, -1):
            if ratings[i] > ratings[i + 1]:
                candy_arr[i] = max(candy_arr[i], candy_arr[i + 1] + 1)

        return sum(candy_arr)  # 汇总糖果总数
```

### C++

```cpp
class Solution {
public:
    // 方法：candy；按题目要求处理输入并返回结果，核心算法见方法体。
    int candy(vector<int>& ratings) {
        int n = ratings.size();
        vector<int> candyVec(n, 1); // 每个孩子至少 1 颗糖果

        // 从左到右：只处理右边比左边评分高的情况
        for (int i = 1; i < n; i++) {
            if (ratings[i] > ratings[i - 1]) {
                candyVec[i] = candyVec[i - 1] + 1;
            }
        }

        // 从右到左：只处理左边比右边评分高的情况，取较大值不破坏之前的结果
        for (int i = n - 2; i >= 0; i--) {
            if (ratings[i] > ratings[i + 1]) {
                candyVec[i] = max(candyVec[i], candyVec[i + 1] + 1);
            }
        }

        int result = 0;
        for (int c : candyVec) result += c; // 汇总糖果总数
        return result;
    }
};
```


### Go

```go
// 方法：candy；按题目要求处理输入并返回结果，核心算法见方法体。
func candy(ratings []int) int {
    n := len(ratings)
    candyArr := make([]int, n)
    for i := range candyArr {
        candyArr[i] = 1 // 每个孩子至少 1 颗糖果
    }

    // 从左到右：处理右边比左边评分高的情况
    for i := 1; i < n; i++ {
        if ratings[i] > ratings[i-1] {
            candyArr[i] = candyArr[i-1] + 1
        }
    }

    // 从右到左：处理左边比右边评分高的情况，取较大值
    for i := n - 2; i >= 0; i-- {
        if ratings[i] > ratings[i+1] {
            if candyArr[i+1]+1 > candyArr[i] {
                candyArr[i] = candyArr[i+1] + 1
            }
        }
    }

    result := 0
    for _, c := range candyArr {
        result += c // 汇总
    }
    return result
}
```

## 总结

- 当一个位置同时受两个方向约束、直接一次遍历难以兼顾的时候，可以拆成"只看左边"和"只看右边"两次独立遍历，这是贪心里"分而治之"的常见技巧。
- 第二次遍历必须用 `max(当前值, 新约束值)` 合并结果，不能直接赋值覆盖，不然会破坏第一次遍历已经满足的约束。
- 两次遍历各自都是在自己方向上的最小解，合并后依然是全局最小解，因为两个方向的约束通过 `max` 操作可以无冲突地同时满足。
- 这种"两次单方向遍历 + 合并"的模式在后续类似需要同时满足左右邻居约束的题目中还会反复出现，值得作为一个独立的贪心套路记住。

09.贪心算法/0376.摆动序列/0376.摆动序列.md:
# 0376. 摆动序列

**题目描述**

如果一个序列中，相邻两个元素的差严格地在正负之间交替（即差值符号交替变化），那么这个序列被称为摆动序列。给定一个整数数组 `nums`，求其中最长摆动子序列的长度（子序列可以不连续，但要保持原数组中的相对顺序）。

```
示例：
输入: nums = [1,7,4,9,2,5]
输出: 6
解释: 整个数组就是一个摆动序列，差值为 (6,-3,5,-7,3)，符号严格交替。

输入: nums = [1,17,5,10,13,15,10,5,16,8]
输出: 7
解释: 存在多种最长摆动子序列，一个例子是 [1,17,10,13,10,16,8]，差值为 (16,-7,3,-3,6,-8)。
```

## 思路

贪心只保留峰谷：统计相邻差值的正负交替次数，初始长度为 1。零差跳过；仅符号反转时更新前差和长度。

时间 O(n)，空间 O(1)。

## 代码

### Python

```python
class Solution:
    # 方法：wiggleMaxLength；按题目要求处理输入并返回结果，核心算法见方法体。
    def wiggleMaxLength(self, nums: list[int]) -> int:
        if len(nums) <= 1:
            return len(nums)  # 长度 0 或 1 时本身就是摆动序列
        result = 1     # 第一个元素默认算作起点
        prediff = 0    # 上一次真正发生摆动的差值方向，初始为0
        for i in range(1, len(nums)):
            curdiff = nums[i] - nums[i - 1]  # 当前相邻差值
            # 谷底转峰顶 或 峰顶转谷底 时才计数
            if (prediff <= 0 and curdiff > 0) or (prediff >= 0 and curdiff < 0):
                result += 1        # 出现新的峰值/谷值
                prediff = curdiff  # 更新方向，平坡（curdiff==0）不更新
        return result
```

### C++

```cpp
class Solution {
public:
    // 方法：wiggleMaxLength；按题目要求处理输入并返回结果，核心算法见方法体。
    int wiggleMaxLength(vector<int>& nums) {
        if (nums.size() <= 1) return nums.size();  // 长度 0 或 1 时本身就是摆动序列
        int result = 1;    // 默认第一个元素算作序列的起点，长度至少为1
        int prediff = 0;   // 记录上一次真正发生摆动的差值符号（初始为0表示尚未摆动）
        for (int i = 1; i < nums.size(); i++) {
            int curdiff = nums[i] - nums[i - 1];  // 当前相邻元素的差值
            // 谷底转峰顶（prediff<=0 说明之前是下降或平坡，curdiff>0 说明现在上升）
            // 或者峰顶转谷底（prediff>=0 说明之前是上升或平坡，curdiff<0 说明现在下降）
            if ((prediff <= 0 && curdiff > 0) || (prediff >= 0 && curdiff < 0)) {
                result++;        // 出现一次新的摆动，长度加一
                prediff = curdiff;  // 更新为最近一次真正的摆动方向，供下次比较
            }
            // curdiff == 0（平坡）或方向未变化时，不更新prediff，跳过不计数
        }
        return result;
    }
};
```


### Go

```go
// 方法：wiggleMaxLength；按题目要求处理输入并返回结果，核心算法见方法体。
func wiggleMaxLength(nums []int) int {
    if len(nums) <= 1 {
        return len(nums) // 长度 0 或 1 时本身就是摆动序列
    }
    result := 1  // 第一个元素默认算作起点
    prediff := 0 // 上一次真正发生摆动的差值方向，初始为0
    for i := 1; i < len(nums); i++ {
        curdiff := nums[i] - nums[i-1] // 当前相邻差值
        if (prediff <= 0 && curdiff > 0) || (prediff >= 0 && curdiff < 0) {
            result++          // 出现新的峰值/谷值
            prediff = curdiff // 更新方向
        }
    }
    return result
}
```

## 总结

- 贪心策略就是只统计"局部峰值"（相邻差值符号发生变化的位置），说白了本质上就是删掉单调区间内部的所有中间元素，只留区间端点。
- 正确性证明的关键在哪儿呢？就在于单调区间内的中间元素不管留多少个都没法增加摆动次数（因为符号不会交替），而用峰值点去代替任意一个非峰值点，不会让摆动长度变差，所以贪心选峰值不会比任何其他方案差。
- 差值为0（平坡）的情况不能更新 prediff，不然会导致漏判或者重复计数，这是这题最容易出错的边界，得留意。
- 这题跟"最大子序和"（0053）都体现了"用一个方向标志/累加变量做单次遍历决策"的贪心手法，但摆动序列关注的是符号变化次数，最大子序和关注的是累加值的正负，这一点要分清楚，别搞混了。

09.贪心算法/0406.根据身高重建队列/0406.根据身高重建队列.md:
# 0406. 根据身高重建队列

**题目描述**

假设有打乱顺序的一群人站成一个队列，每个人由一个整数对 `(h, k)` 描述，其中 `h` 是这个人的身高，`k` 是排在这个人前面且身高大于或等于 `h` 的人数。请你重新构造并返回输入数组 `people` 所表示的队列。返回的队列应该形如 `[[h1,k1],[h2,k2],...]`，其中 `[hi, ki]` 是队列中第 `i` 个人的属性。

```
示例：
输入: people = [[7,0],[4,4],[7,1],[5,0],[6,1],[5,2]]
输出: [[5,0],[7,0],[5,2],[6,1],[4,4],[7,1]]
解释:
编号为 0 的人身高为 5，前面没有身高大于等于 5 的人，所以他必须排在最前面。
编号为 1 的人身高为 7，前面也没有身高大于等于 7 的人，所以他排在第二位。
编号为 2 的人身高为 5，前面有 2 个身高大于等于 5 的人，那就是编号为 0 和 1 的人。
...（以此类推）
```

## 思路

- 贪心插入：按身高降序、同高按 `k` 升序排序，再依次插入下标 `k`。已插入者均不矮于当前人，矮者后续插入不影响其计数。时间 O(n²)，空间 O(n)。
- 树状数组／线段树：按身高升序、同高 `k` 降序，将人放入第 `k+1` 个空位。时间 O(n log n)，空间 O(n)。

## 代码

### Python

```python
class Solution:
    # 方法：reconstructQueue；按题目要求处理输入并返回结果，核心算法见方法体。
    def reconstructQueue(self, people: list[list[int]]) -> list[list[int]]:
        # 身高降序；身高相同时 k 升序
        people.sort(key=lambda p: (-p[0], p[1]))

        result = []
        for p in people:
            result.insert(p[1], p)  # 插入到下标为 k 的位置
        return result
```

### C++

```cpp
class Solution {
public:
    vector<vector<int>> reconstructQueue(vector<vector<int>>& people) {
        // 身高降序；身高相同时 k 升序
        sort(people.begin(), people.end(), [](const vector<int>& a, const vector<int>& b) {
            if (a[0] == b[0]) return a[1] < b[1];
            return a[0] > b[0];
        });

        vector<vector<int>> result;
        for (auto& p : people) {
            result.insert(result.begin() + p[1], p); // 插入到下标为 k 的位置
        }
        return result;
    }
};
```


### Go

```go
// 方法：reconstructQueue；按题目要求处理输入并返回结果，核心算法见方法体。
func reconstructQueue(people [][]int) [][]int {
    // 身高降序；身高相同时 k 升序
    sort.Slice(people, func(i, j int) bool {
        if people[i][0] == people[j][0] {
            return people[i][1] < people[j][1]
        }
        return people[i][0] > people[j][0]
    })

    result := make([][]int, 0, len(people))
    for _, p := range people {
        k := p[1]
        result = append(result, nil)
        copy(result[k+1:], result[k:]) // 后面元素整体后移一位
        result[k] = p                  // 插入到下标为 k 的位置
    }
    return result
}
```

## 总结

- 遇到"每个元素受两个维度约束"的问题时，可以尝试先固定一个维度的处理顺序，把二维问题降成一维问题，这是一种通用的贪心降维技巧。
- 本题按身高降序处理的本质原因是：先确定的人身高更高，后续插入的人不会影响已确定的人的"前面身高≥自己的人数"这一约束，从而保证每一步插入都不会被后续操作破坏。
- 身高相同时按 k 升序排列，是为了让同身高的人之间的相对顺序跟插入顺序保持一致。
- 直接用数组插入的实现方式简单直观但是 O(n²)，如果对性能有更高要求，可以考虑链表或树状结构优化插入操作。

09.贪心算法/0435.无重叠区间/0435.无重叠区间.md:
# 0435. 无重叠区间

**题目描述**

给定一个区间的数组 `intervals`，其中 `intervals[i] = [starti, endi]`，返回需要移除区间的最小数量，使剩余区间互不重叠（区间的边界重合不算重叠，例如 `[1,2]` 和 `[2,3]` 视为不重叠）。

```
示例：
输入: intervals = [[1,2],[2,3],[3,4],[1,3]]
输出: 1
解释: 移除 [1,3] 后，剩下的区间 [[1,2],[2,3],[3,4]] 互不重叠。
```

## 思路

按右端点升序，优先保留结束最早的区间，为后续留出空间。左端点小于已保留右端点则删除，否则保留并更新右端点；端点相等不算重叠。

时间 O(n log n)，扫描辅助空间 O(1)；计入排序时 C++ 常见 O(log n)、Python O(n)。也可按左端点排序，重叠时保留右端点较小者。

## 代码

### Python

```python
class Solution:
    # 方法：eraseOverlapIntervals；按题目要求处理输入并返回结果，核心算法见方法体。
    def eraseOverlapIntervals(self, intervals: list[list[int]]) -> int:
        if not intervals:
            return 0
        intervals.sort(key=lambda x: x[1])  # 按右边界从小到大排序
        count = 0                             # 需要移除的区间数
        end = intervals[0][1]                 # 当前保留区间的右边界
        for i in range(1, len(intervals)):
            if intervals[i][0] < end:
                # 左边界小于当前保留区间右边界，发生重叠，移除当前这个
                count += 1
            else:
                # 不重叠，保留并更新右边界
                end = intervals[i][1]
        return count
```

### C++

```cpp
class Solution {
public:
    static bool cmp(const vector<int>& a, const vector<int>& b) {
        return a[1] < b[1];  // 按右边界从小到大排序
    }

    // 方法：eraseOverlapIntervals；按题目要求处理输入并返回结果，核心算法见方法体。
    int eraseOverlapIntervals(vector<vector<int>>& intervals) {
        if (intervals.empty()) return 0;
        sort(intervals.begin(), intervals.end(), cmp);  // 按右边界排序
        int count = 0;                 // 需要移除的区间数
        int end = intervals[0][1];     // 当前保留区间的右边界
        for (int i = 1; i < intervals.size(); i++) {
            if (intervals[i][0] < end) {
                // 左边界小于当前保留区间右边界，发生重叠（边界重合不算重叠，用严格小于）
                // 排序后右边界非递减，当前区间右边界必然>=end，故移除当前区间，end不更新
                count++;
            } else {
                // 不重叠，保留这个区间，更新右边界
                end = intervals[i][1];
            }
        }
        return count;
    }
};
```


### Go

```go
import "sort"

// 方法：eraseOverlapIntervals；按题目要求处理输入并返回结果，核心算法见方法体。
func eraseOverlapIntervals(intervals [][]int) int {
    if len(intervals) == 0 {
        return 0
    }
    // 按右边界从小到大排序
    sort.Slice(intervals, func(i, j int) bool {
        return intervals[i][1] < intervals[j][1]
    })
    count := 0                    // 需要移除的区间数
    end := intervals[0][1]        // 当前保留区间的右边界
    for i := 1; i < len(intervals); i++ {
        if intervals[i][0] < end {
            // 左边界小于当前保留区间右边界，发生重叠，移除当前这个
            count++
        } else {
            // 不重叠，保留并更新右边界
            end = intervals[i][1]
        }
    }
    return count
}
```

## 总结

- 跟 452 题共享同一套"排序 + 维护边界变量"的贪心模板，区别在于统计目标（箭数 vs 移除数）和边界重合的语义（`<=` vs `<`）。
- 重叠时保留右边界更小的区间是关键贪心选择，用交换论证可以证明：保留右边界小的区间不会让后续判断变严格，所以不劣于保留右边界大的区间。
- 452 题统计"分组数"就是答案，435 题需要用"总数 - 分组数"才能得到移除数，二者本质上是同一个分组过程的不同读数方式。
- 区间重叠类问题写代码时要特别注意边界符号（`<` 还是 `<=`），这取决于题目对"边界重合是否算重叠"的具体定义。

09.贪心算法/0452.用最少数量的箭引爆气球/0452.用最少数量的箭引爆气:
# 0452. 用最少数量的箭引爆气球

**题目描述**

给定一个二维数组 `points`，其中 `points[i] = [xstart, xend]` 表示第 i 个气球在 x 轴上的直径区间。气球被完全填充在 x 轴上方，一支箭可以从 x 轴上任意一点垂直射出，如果一支箭的射出点在气球的直径区间内（包括边界），那么该气球会被引爆。求引爆所有气球所需的最少弓箭数。

```
示例：
输入: points = [[10,16],[2,8],[1,6],[7,12]]
输出: 2
解释: 在 x=6 处射出一支箭，可以射爆气球 [2,8] 和 [1,6]；
在 x=11 处射出一支箭，射爆气球 [10,16] 和 [7,12]。
```

## 思路

- 按左端点排序：维护当前组公共交集的右端点，重叠时取较小右端点；下一左端点超过它时新增一箭。
- 按右端点排序：箭射最早结束处，跳过已覆盖气球，遇到未覆盖者再射。

端点相等可共用一箭。时间 O(n log n)，扫描辅助空间 O(1)；计入排序时 C++ 常见 O(log n)、Python O(n)。

## 代码

### Python

```python
class Solution:
    # 方法：findMinArrowShots；按题目要求处理输入并返回结果，核心算法见方法体。
    def findMinArrowShots(self, points: list[list[int]]) -> int:
        if not points:
            return 0
        points.sort(key=lambda p: p[0])  # 按左边界从小到大排序
        count = 1                          # 至少需要一支箭
        arrow_pos = points[0][1]           # 第一支箭覆盖到第一个气球的右边界
        for i in range(1, len(points)):
            if points[i][0] > arrow_pos:
                # 左边界超出覆盖范围，没有重叠，新增一支箭
                count += 1
                arrow_pos = points[i][1]
            else:
                # 有重叠，收缩覆盖范围为交集右边界（取较小值）
                arrow_pos = min(arrow_pos, points[i][1])
        return count
```

### C++

```cpp
class Solution {
public:
    static bool cmp(const vector<int>& a, const vector<int>& b) {
        return a[0] < b[0];  // 按左边界从小到大排序
    }

    // 方法：findMinArrowShots；按题目要求处理输入并返回结果，核心算法见方法体。
    int findMinArrowShots(vector<vector<int>>& points) {
        if (points.empty()) return 0;
        sort(points.begin(), points.end(), cmp);  // 按左边界排序
        int count = 1;                             // 至少需要一支箭
        int arrowPos = points[0][1];                // 第一支箭初始覆盖到第一个气球的右边界
        for (int i = 1; i < points.size(); i++) {
            if (points[i][0] > arrowPos) {
                // 左边界超出当前箭覆盖范围，说明没有重叠，必须新增一支箭
                count++;
                arrowPos = points[i][1];  // 新箭的覆盖右边界初始化为当前气球右边界
            } else {
                // 左边界在覆盖范围内，可以用同一支箭，收缩覆盖范围为交集右边界（取较小值）
                arrowPos = min(arrowPos, points[i][1]);
            }
        }
        return count;
    }
};
```


### Go

```go
import "sort"

// 方法：findMinArrowShots；按题目要求处理输入并返回结果，核心算法见方法体。
func findMinArrowShots(points [][]int) int {
    if len(points) == 0 {
        return 0
    }
    // 按左边界从小到大排序
    sort.Slice(points, func(i, j int) bool {
        return points[i][0] < points[j][0]
    })
    count := 1                   // 至少需要一支箭
    arrowPos := points[0][1]     // 第一支箭覆盖到第一个气球的右边界
    for i := 1; i < len(points); i++ {
        if points[i][0] > arrowPos {
            // 没有重叠，新增一支箭
            count++
            arrowPos = points[i][1]
        } else {
            // 有重叠，收缩覆盖范围为交集右边界
            if points[i][1] < arrowPos {
                arrowPos = points[i][1]
            }
        }
    }
    return count
}
```

## 总结

- 按左边界排序是为了让遍历过程单调有序，这样只需要维护一个"当前箭覆盖范围"变量就能正确判断重叠关系，不用去处理乱序区间的复杂关系。
- 重叠的时候更新覆盖范围为两者右边界的较小值，说白了本质上就是维护"覆盖范围=已合并气球的真实交集"这一不变量，取较大值或者不更新都会导致后面判断出现误判。
- 边界重合（左边界恰好等于arrowPos）算作可以引爆，因为箭可以射在边界点上，所以判断条件用的是"严格大于才新增箭"，等号情况归入可合并这一类。
- 这题跟435（无重叠区间）思路高度相似，都是"排序+维护右边界"的区间处理范式，区别就在于边界重合的语义和最终统计目标不一样。

09.贪心算法/0649.Dota2参议院/0649.Dota2参议院.md:
# 0649. Dota2参议院

**题目描述**

Dota2 的世界里有两个阵营：Radiant（天辉）和 Dire（夜魔）。Dota2 参议院由来自两派的参议员组成，现在参议院希望对某一 Dota2 游戏里的改变作出决定，他们以投票的形式决定。这个投票过程按照以下规则进行：

给定一个字符串 `senate` 代表每个参议员的阵营，`senate[i]` 为 `'R'` 或 `'D'`，字符所在位置代表投票次序。参议员按照排列顺序，轮流行使两项权利中的一项：
- **禁止一名参议员的权利**：参议员可以让另一位参议员在这一轮和随后的几轮中丧失所有权利。
- **宣布胜利**：如果参议员发现所有的参议员都是同一个阵营的，他可以宣布胜利并决定在游戏中的有关变化。

给定一个字符串代表每个参议员的阵营，请预测哪一个阵营最终会宣布胜利并在 Dota2 游戏中决定改变。输出应该是 `Radiant` 或 `Dire`。

```
示例：
输入：senate = "RD"
输出："Radiant"
解释：第 1 个参议员来自 Radiant 阵营，他可以使用第一项权利让第 2 个参议员失去权力。
剩下所有的参议员都是 Radiant 阵营的，所以宣布胜利。

输入：senate = "RDD"
输出："Dire"
解释：
第 1 个参议员来自 Radiant 阵营，他可以使用第一项权利禁止第 2 个参议员的权利。
第 2 个参议员被禁止了所有的权利。
第 3 个参议员来自 Dire 阵营，他可以使用他的权利禁止第 1 个参议员的权利。
因为参议院中只剩下第 3 个参议员，所以他可以宣布胜利。
```

## 思路

双队列保存两阵营的下标。每次取双方队头，下标小者先行动，淘汰对方并将自身下标加 `n` 后入队。某队为空时另一方获胜；优先淘汰最早能行动的对手。

每次对抗淘汰一人，时间 O(n)，空间 O(n)。

## 代码

### Python

本题是状态模拟类问题，没有对应的标准库一行解，只有手写队列模拟：

```python
from collections import deque

class Solution:
    # 方法：predictPartyVictory；按题目要求处理输入并返回结果，核心算法见方法体。
    def predictPartyVictory(self, senate: str) -> str:
        n = len(senate)
        radiant = deque(i for i, c in enumerate(senate) if c == 'R')  # R 阵营下标队列
        dire = deque(i for i, c in enumerate(senate) if c == 'D')    # D 阵营下标队列

        while radiant and dire:
            r = radiant.popleft()  # R 阵营下一个要行动的人
            d = dire.popleft()     # D 阵营下一个要行动的人
            if r < d:
                # R 更早行动，禁掉 D；R 存活，下标+n 表示进入下一轮
                radiant.append(r + n)
            else:
                dire.append(d + n)

        return "Radiant" if radiant else "Dire"  # 非空的队列即为胜者
```

### C++

```cpp
class Solution {
public:
    // 方法：predictPartyVictory；按题目要求处理输入并返回结果，核心算法见方法体。
    string predictPartyVictory(string senate) {
        int n = senate.size();
        queue<int> radiant, dire;  // 分别存放 R、D 阵营参议员的下标
        for (int i = 0; i < n; i++) {
            if (senate[i] == 'R') radiant.push(i);
            else dire.push(i);
        }
        while (!radiant.empty() && !dire.empty()) {
            int r = radiant.front(); radiant.pop();  // R 阵营下一个行动的人
            int d = dire.front(); dire.pop();        // D 阵营下一个行动的人
            if (r < d) {
                // R 先行动，禁掉 D，R 存活并进入下一轮（下标+n 表示时间顺序后移）
                radiant.push(r + n);
            } else {
                dire.push(d + n);
            }
        }
        return radiant.empty() ? "Dire" : "Radiant";  // 哪个队列还有剩余就是赢家
    }
};
```


### Go

```go
// 方法：predictPartyVictory；按题目要求处理输入并返回结果，核心算法见方法体。
func predictPartyVictory(senate string) string {
    n := len(senate)
    radiant := make([]int, 0, n)
    dire := make([]int, 0, n)
    for i, c := range senate {
        if c == 'R' {
            radiant = append(radiant, i)
        } else {
            dire = append(dire, i)
        }
    }

    for len(radiant) > 0 && len(dire) > 0 {
        r, d := radiant[0], dire[0]
        radiant, dire = radiant[1:], dire[1:] // 弹出两队队首
        if r < d {
            radiant = append(radiant, r+n) // R 先行动，禁掉 D，自己进入下一轮
        } else {
            dire = append(dire, d+n) // D 先行动，禁掉 R，自己进入下一轮
        }
    }

    if len(radiant) > 0 {
        return "Radiant"
    }
    return "Dire"
}
```

## 总结

- 核心贪心策略是"谁先行动谁就优先消灭对方下一个即将行动的人"，本质上是在争夺行动的先手权，这类"轮流行动、互相消耗"的博弈模拟题经常可以转化为贪心+队列模型。
- 给重新入队的下标加上 `n` 是本题最关键的技巧：它把"轮次信息"编码进了下标数值本身，让两个独立队列之间依然可以通过简单的数值比较还原出全局的真实时间顺序，避免了显式模拟每一轮、每一个位置的复杂操作。
- 时间复杂度做到了 O(n)，因为每一轮必定有一个参议员永久出局，循环次数不会超过参议员总数。
- 容易犯的错误是直接用两个指针在原字符串上模拟轮转，忘了被禁止的参议员是永久出局的，还试图给"存活"和"出局"分别加复杂的标记数组——队列模型天然免除了这个麻烦，因为出队的人默认不会再出现，除非显式重新入队。

09.贪心算法/0763.划分字母区间/0763.划分字母区间.md:
# 0763. 划分字母区间

**题目描述**

给定一个字符串 `s`，需要把这个字符串划分为尽可能多的片段，同一字母最多出现在一个片段中，返回一个表示每个字符串片段长度的列表。

```
示例：
输入: s = "ababcbacadefegdehijhklij"
输出: [9,7,8]
解释: 划分结果为 "ababcbaca", "defegde", "hijhklij"，
每个片段中的字母都不会出现在其他片段中。
```

## 思路

记录每个字符最后出现的位置。扫描时更新本段最远终点 `end=max(end,last[s[i]])`；到达 `end` 即切分，此时段内字符都不会出现在后面。

时间 O(n)，辅助空间 O(1)（26 个字母），结果最多 26 段。

## 代码

### Python

```python
class Solution:
    # 方法：partitionLabels；按题目要求处理输入并返回结果，核心算法见方法体。
    def partitionLabels(self, s: str) -> list[int]:
        last_index = {}  # 记录每个字母最后一次出现的下标
        for i, ch in enumerate(s):
            last_index[ch] = i  # 不断覆盖，最终保留最后一次出现的位置

        result = []
        start, right = 0, 0  # start:片段起点，right:片段右边界
        for i, ch in enumerate(s):
            right = max(right, last_index[ch])  # 扩展右边界，纳入当前字符完整区间
            if i == right:
                # 下标追上右边界，当前片段可以安全切分
                result.append(right - start + 1)
                start = i + 1
        return result
```

### C++

```cpp
class Solution {
public:
    // 方法：partitionLabels；按题目要求处理输入并返回结果，核心算法见方法体。
    vector<int> partitionLabels(string s) {
        int lastIndex[26] = {0};  // 记录每个字母最后一次出现的下标
        for (int i = 0; i < s.size(); i++) {
            lastIndex[s[i] - 'a'] = i;  // 不断更新，最终保留最后一次出现的位置
        }
        vector<int> result;
        int start = 0, right = 0;  // start:当前片段起点，right:当前片段右边界
        for (int i = 0; i < s.size(); i++) {
            right = max(right, lastIndex[s[i] - 'a']);  // 扩展右边界，纳入当前字符的完整区间
            if (i == right) {
                // 遍历下标追上右边界，说明当前片段内所有字母的区间都已完整纳入，可以切分
                result.push_back(right - start + 1);
                start = i + 1;  // 下一个片段起点
            }
        }
        return result;
    }
};
```


### Go

```go
// 方法：partitionLabels；按题目要求处理输入并返回结果，核心算法见方法体。
func partitionLabels(s string) []int {
    var lastIndex [26]int // 记录每个字母最后一次出现的下标
    for i := 0; i < len(s); i++ {
        lastIndex[s[i]-'a'] = i // 更新为最后一次出现的位置
    }

    var result []int
    start, right := 0, 0 // start:片段起点，right:片段右边界
    for i := 0; i < len(s); i++ {
        if lastIndex[s[i]-'a'] > right {
            right = lastIndex[s[i]-'a'] // 扩展右边界，纳入当前字符完整区间
        }
        if i == right {
            // 下标追上右边界，当前片段可以安全切分
            result = append(result, right-start+1)
            start = i + 1
        }
    }
    return result
}
```

## 总结

- 这题的核心思路，说白了就是把"字母不能跨片段出现"这个要求，转化成了"字母对应的区间不能跨片段"，然后用区间合并的思路一次遍历搞定划分，本质上是区间合并思想在字符串上的一个变体。
- `right` 变量代表的是"当前片段已经合并的所有字母区间能撑到的最远边界"，只有遍历下标追上了 `right`，才能保证这个片段里的所有字母都不会跑到外面去。
- 这个贪心策略切出来的，既是能合法切分的最早时机，也是数量最多的划分方式——提前切会把字母区间切断变成非法划分，拖后切又会白白减少片段数量。
- 用一个长度为 26 的数组代替哈希表来记录最后出现位置，这是字符集有限场景下很常见的优化技巧，能省掉哈希表那部分额外开销。

