                dp[i] = dp[i - 1] + 1;  // 递增，接续前一个数的长度 +1
            } else {
                dp[i] = 1;  // 不递增，断开，重新从 1 开始计数
            }
            result = max(result, dp[i]);  // 更新全局最长长度
        }
        return result;
    }
};
```


### Go

```go
// 方法：findLengthOfLCIS；按题目要求处理输入并返回结果，核心算法见方法体。
func findLengthOfLCIS(nums []int) int {
    n := len(nums)
    dp := make([]int, n)
    for i := range dp {
        dp[i] = 1 // dp[i] 初始化为 1，每个元素自身构成长度为1的序列
    }
    result := 1 // 记录最长长度，至少为 1
    for i := 1; i < n; i++ {
        if nums[i] > nums[i-1] {
            dp[i] = dp[i-1] + 1 // 递增，接续前一个数的长度 +1
        } else {
            dp[i] = 1 // 不递增，断开，重新从 1 开始计数
        }
        if dp[i] > result {
            result = dp[i] // 更新全局最长长度
        }
    }
    return result
}
```

## 总结

- 这道题的核心递推就是比较相邻的两个元素 `nums[i]` 和 `nums[i-1]`，一旦不满足递增条件，就必须把 `dp[i]` 清零重置为 1。这也是"连续子序列"跟"不连续子序列"最本质的区别：连续子序列一旦断开就没有回头路了，而不连续子序列断开之后，还有可能从更早的位置续上。
- 300 题（不要求连续）得枚举所有 `j < i` 的前驱再取最大值，时间复杂度是 O(n^2)；而本题（要求连续）因为候选前驱是唯一的，只需要一层 O(n) 遍历就能解决。这也提醒我们做题的时候，一定要先看清楚"连续"跟"不连续"这类关键限定词，它会直接决定你 DP 状态转移该怎么设计。
- `dp[i]` 只依赖 `dp[i-1]`，所以完全可以用一个滚动变量去替代整个数组，把空间复杂度从 O(n) 优化到 O(1)，代价就是牺牲了 dp 数组本身的可读性和可调试性。
- 以后遇到"连续区间"这类问题的时候，可以优先考虑这种只看相邻元素关系的线性遍历思路，往往会比套用一般子序列那种双重循环的模板要高效得多。

# 718. 最长重复子数组

**题目描述**

给定两个整数数组 `nums1` 和 `nums2`，求两个数组中最长公共**连续**子数组的长度（子数组要求下标连续，不能跳跃）。

```
示例：
输入: nums1 = [1,2,3,2,1], nums2 = [3,2,1,4,7]
输出: 3
解释: 公共的连续子数组是 [3,2,1]，长度为 3
```

## 思路

DP：`dp[i][j]` 为分别以两数组下标 `i-1、j-1` 结尾的最长公共连续段长度。边界为 0；元素相等取 `dp[i-1][j-1]+1`，否则清零。逐行正序，返回全部状态最大值。

时间、空间 O(nm)；一维滚动按 j 倒序，不匹配仍清零，空间 O(m)。

## 代码

### Python

```python
class Solution:
    # 方法：findLength；按题目要求处理输入并返回结果，核心算法见方法体。
    def findLength(self, nums1: list[int], nums2: list[int]) -> int:
        n, m = len(nums1), len(nums2)
        dp = [[0] * (m + 1) for _ in range(n + 1)]  # dp[i][0]、dp[0][j] 均为0
        result = 0
        for i in range(1, n + 1):
            for j in range(1, m + 1):
                if nums1[i - 1] == nums2[j - 1]:
                    dp[i][j] = dp[i - 1][j - 1] + 1  # 匹配，接续左上方长度+1
                else:
                    dp[i][j] = 0  # 不匹配，连续子数组断开，清零
                result = max(result, dp[i][j])  # 更新全局最大值
        return result
```

### C++

