public:
    // 方法：findLength；按题目要求处理输入并返回结果，核心算法见方法体。
    int findLength(vector<int>& nums1, vector<int>& nums2) {
        int n = nums1.size(), m = nums2.size();
        vector<vector<int>> dp(n + 1, vector<int>(m + 1, 0));  // dp[i][0]、dp[0][j] 默认初始化为0
        int result = 0;
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                if (nums1[i - 1] == nums2[j - 1]) {
                    dp[i][j] = dp[i - 1][j - 1] + 1;  // 匹配，接续左上方长度+1
                } else {
                    dp[i][j] = 0;  // 不匹配，连续子数组断开，清零
                }
                result = max(result, dp[i][j]);  // 更新全局最大值
            }
        }
        return result;
    }
};
```


### Go

