// 方法一：双指针
// 方法：trap；按题目要求处理输入并返回结果，核心算法见方法体。
func trap(height []int) int {
    left, right := 0, len(height)-1
    leftMax, rightMax := 0, 0
    water := 0
    for left < right {
        if height[left] > leftMax {
            leftMax = height[left]
        }
        if height[right] > rightMax {
            rightMax = height[right]
        }
        if leftMax < rightMax {
            water += leftMax - height[left] // 左边屏障更矮，决定水位
            left++
        } else {
            water += rightMax - height[right] // 右边屏障更矮或相等
            right--
        }
    }
    return water
}
```

```go
// 方法二：单调栈
// 方法：trapStack；按题目要求处理输入并返回结果，核心算法见方法体。
func trapStack(height []int) int {
    stack := make([]int, 0, len(height)) // 栈中存下标，高度递减
    water := 0
    for i, h := range height {
        for len(stack) > 0 && h > height[stack[len(stack)-1]] {
            mid := stack[len(stack)-1]
            stack = stack[:len(stack)-1] // 槽底出栈
            if len(stack) == 0 {
                break // 左边没有屏障
            }
            left := stack[len(stack)-1]      // 左边界
            width := i - left - 1             // 凹槽宽度
            depth := min(height[left], h) - height[mid] // 这一层高度
            water += width * depth
        }
        stack = append(stack, i)
    }
    return water
}

// 方法：min；按题目要求处理输入并返回结果，核心算法见方法体。
func min(a, b int) int {
    if a < b {
        return a
    }
    return b
}
```

## 总结

- 接雨水这道题的核心公式就是"每一列的积水量 = min(左边最高, 右边最高) - 自身高度"，双指针法靠维护左右两个指针扫过的历史最大值，在不知道对面精确最大值的情况下，也能确定当前列的水位归属到底是谁，这样就把空间优化到了 O(1)。
- 单调栈法换了个视角来看这道题：不是一列一列地算，而是直接定位"凹槽"——左边界、槛底、右边界，一次弹栈就能同时确定凹槽的宽和高，说白了本质是"按层"累加雨水，而双指针/DP 是"按列"累加雨水，两种思路殊途同归，最后结果是一样的。
- 单调栈法里有个容易漏掉的边界条件：一旦弹出槛底之后栈变空了，说明左边根本没有更高的屏障能把水围住，这时候一定要记得 `break` 跳出内层循环。
- 双指针能简化到 O(1) 空间，关键的判断依据就是：只要 `leftMax < rightMax`，就能确定右边一定存在能挡住水的屏障（哪怕还没扫到它具体在哪），所以当前列的水位必然是由 `leftMax` 决定的。这其实是一种"提前确定归属、不用知道精确对手值"的技巧，在双指针这类问题里还挺常见的。

11.单调栈/0084.柱状图中最大的矩形/0084.柱状图中最大的矩形.md:
# 0084. 柱状图中最大的矩形

**题目描述**

给定 `n` 个非负整数，用来表示柱状图中各个柱子的高度，每个柱子彼此相邻，且宽度为 1。求在该柱状图中，能够勾勒出来的矩形的最大面积。

```
示例：
输入: heights = [2,1,5,6,2,3]
输出: 10
解释: 最大的矩形由下标2、3处的柱子（高度5、6）中较矮的高度5为矩形高，
宽度从下标2到下标3，但实际上可以扩展——
以高度5为矩形高时，宽度能扩展到下标1右边、下标4左边之间(下标2到3)，面积5*2=10。
```

## 思路

- 单调栈：存下标，高度从栈底到栈顶非递减。遇更矮柱弹出 `mid`，弹出后栈顶为 `left`（空则 -1），面积为 `heights[mid]*(i-left-1)`。末尾补 0，结算剩余正高度。时间 O(n)，空间 O(n)。
- 暴力：以每根柱为高度，向两边扩到更矮柱前。时间 O(n²)，空间 O(1)。

## 代码

### Python

```python
class Solution:
    # 方法：largestRectangleArea；按题目要求处理输入并返回结果，核心算法见方法体。
    def largestRectangleArea(self, heights: list[int]) -> int:
        h = heights + [0]  # 哨兵，保证栈中所有元素最终都会被弹出结算
        stack = []           # 栈中存下标，高度从栈底到栈顶递增
        max_area = 0
        for i, cur in enumerate(h):
            # 当前高度比栈顶柱子矮，说明栈顶柱子右边界就是当前下标
            while stack and cur < h[stack[-1]]:
                mid = stack.pop()                     # 待结算柱子
                left = stack[-1] if stack else -1      # 左边界：栈为空则视为-1
                width = i - left - 1                   # 矩形宽度
                max_area = max(max_area, h[mid] * width)
            stack.append(i)
        return max_area
```

### C++

```cpp
class Solution {
public:
    // 方法：largestRectangleArea；按题目要求处理输入并返回结果，核心算法见方法体。
    int largestRectangleArea(vector<int>& heights) {
        heights.push_back(0);       // 哨兵，保证栈中所有元素最终都会被弹出结算
        stack<int> st;                // 栈中存下标，高度从栈底到栈顶递增
        int maxArea = 0;
        for (int i = 0; i < (int)heights.size(); i++) {
            // 当前高度比栈顶柱子矮，说明栈顶柱子右边界就是当前下标
            while (!st.empty() && heights[i] < heights[st.top()]) {
                int mid = st.top(); st.pop();          // 取出待结算的柱子
                int left = st.empty() ? -1 : st.top();  // 左边界：栈为空则视为-1
                int width = i - left - 1;               // 矩形宽度
                maxArea = max(maxArea, heights[mid] * width);
            }
            st.push(i); // 当前下标入栈
        }
        heights.pop_back(); // 恢复原数组（避免副作用）
        return maxArea;
    }
};
```


### Go

```go
// 方法：largestRectangleArea；按题目要求处理输入并返回结果，核心算法见方法体。
func largestRectangleArea(heights []int) int {
    h := append(append([]int{}, heights...), 0) // 哨兵，保证栈中所有元素最终都会被弹出结算
    stack := make([]int, 0, len(h))               // 栈中存下标，高度递增
    maxArea := 0
    for i, cur := range h {
        // 当前高度比栈顶柱子矮，说明栈顶柱子右边界就是当前下标
        for len(stack) > 0 && cur < h[stack[len(stack)-1]] {
            mid := stack[len(stack)-1]
            stack = stack[:len(stack)-1] // 待结算柱子出栈
            left := -1
            if len(stack) > 0 {
                left = stack[len(stack)-1] // 左边界
            }
            width := i - left - 1// 矩形宽度
            if area := h[mid] * width; area > maxArea {
                maxArea = area
            }
        }
        stack = append(stack, i)
    }
    return maxArea
}
```

## 总结

- 这道题的核心，就是把"暴力向左向右扩展找矮柱子"这个 O(n²) 的过程，用单调栈一次遍历优化到了 O(n)：栈维护的是"从栈底到栈顶高度递增"的性质，每次弹出操作正好同时确定了被弹出柱子的左右两个"更矮边界"。
- 在数组末尾加一个高度为 0 的哨兵柱子，这是个很常用的小技巧，可以避免遍历结束之后还要单独写一段代码去处理栈里剩下的元素，让所有柱子都能在主循环里统一被结算掉。
- 这道题跟 42 题接雨水的单调栈方向刚好相反：接雨水是找"更高"的柱子来当蓄水墙（用的是递减栈），这道题是找"更矮"的柱子来当矩形边界（用的是递增栈），理解这种对称关系，有助于以后碰到单调栈题目时判断该往哪个方向维护——关键就看题目需要找的是"更大"还是"更小"的元素。
- 求矩形宽度的公式 `i - left - 1` 里，`left` 和 `i` 都是边界柱子本身（它们不算在矩形范围内），所以要减 1 把这两个边界位置排除掉，只统计中间部分的宽度。

11.单调栈/0496.下一个更大元素I/0496.下一个更大元素I.md:
# 0496. 下一个更大元素 I

**题目描述**

给定两个没有重复元素的数组 `nums1` 和 `nums2`，其中 `nums1` 是 `nums2` 的子集。对于 `nums1` 中的每个元素，找出它在 `nums2` 中对应位置右边的第一个比它大的元素，如果不存在则输出 -1。

```
示例：
输入: nums1 = [4,1,2], nums2 = [1,3,4,2]
输出: [-1,3,-1]
解释：
4 在 nums2 中的下一个更大元素不存在，输出 -1
1 在 nums2 中的下一个更大元素是 3
2 在 nums2 中的下一个更大元素不存在，输出 -1
```

## 思路

单调栈扫描 `nums2`，遇更大值时连续弹栈，记录“弹出值→当前值”；未找到的默认 -1。再按 `nums1` 顺序查表。值不重复，因此可用值作键。

平均时间 O(m+n)，空间 O(n)，m、n 为两数组长度。

## 代码

### Python

```python
class Solution:
    # 方法：nextGreaterElement；按题目要求处理输入并返回结果，核心算法见方法体。
    def nextGreaterElement(self, nums1: list[int], nums2: list[int]) -> list[int]:
        next_greater = {}   # 值 -> 下一个更大值
        stack = []           # 栈中存元素值，从栈底到栈顶递减
        for num in nums2:
            # 当前值比栈顶值大，弹出并记录映射
            while stack and num > stack[-1]:
                next_greater[stack.pop()] = num
            stack.append(num)  # 当前值入栈

        # 查表，get 的默认值 -1 表示没有下一个更大元素
        return [next_greater.get(num, -1) for num in nums1]
```

### C++

```cpp
class Solution {
public:
    // 方法：nextGreaterElement；按题目要求处理输入并返回结果，核心算法见方法体。
    vector<int> nextGreaterElement(vector<int>& nums1, vector<int>& nums2) {
        unordered_map<int, int> nextGreater; // 值 -> 下一个更大值
        stack<int> st;                       // 栈中存元素值，从栈底到栈顶递减
        for (int num : nums2) {
            // 当前值比栈顶值大，弹出并记录映射
            while (!st.empty() && num > st.top()) {
                nextGreater[st.top()] = num;
                st.pop();
            }
            st.push(num); // 当前值入栈，等待被结算
        }
        // 栈中剩余元素没有找到更大值，对应 -1（下面查表时用 getOrDefault 处理，此处无需显式赋值）

        vector<int> res;
        res.reserve(nums1.size());
        for (int num : nums1) {
            // 查表，找不到说明没有下一个更大元素
            res.push_back(nextGreater.count(num) ? nextGreater[num] : -1);
        }
        return res;
    }
};
```


### Go

```go
// 方法：nextGreaterElement；按题目要求处理输入并返回结果，核心算法见方法体。
func nextGreaterElement(nums1 []int, nums2 []int) []int {
    nextGreater := make(map[int]int) // 值 -> 下一个更大值
    stack := make([]int, 0, len(nums2)) // 栈中存元素值，从栈底到栈顶递减
    for _, num := range nums2 {
        // 当前值比栈顶值大，弹出并记录映射
        for len(stack) > 0 && num > stack[len(stack)-1] {
            top := stack[len(stack)-1]
            stack = stack[:len(stack)-1]
            nextGreater[top] = num
        }
        stack = append(stack, num) // 当前值入栈
    }

    res := make([]int, len(nums1))
    for i, num := range nums1 {
        if v, ok := nextGreater[num]; ok {
            res[i] = v // 查表成功
        } else {
            res[i] = -1 // 没有找到更大元素
        }
    }
    return res
}
```

## 总结

- 这道题的核心其实不在单调栈本身（这个模板和 739 题完全一样），关键是要识别出"子集查询"这个结构，把问题拆成"对全集预处理 + 对子集查表"两步，这样就避免了对 `nums1` 里每个元素都重复扫一遍 `nums2`。
- 因为 `nums2` 里的元素不重复，所以可以直接拿元素值当哈希表的 key；但如果存在重复元素，就必须改成用下标当 key 了，不然值会冲突覆盖。
- 单调栈这里存的是元素值而不是下标，因为咱们只需要建立"值到值"的映射关系，不涉及位置的计算（不像 739 题那样需要算下标差）。
- 哈希表查询是 O(1)，配合 O(n) 的单调栈预处理，整体复杂度就是线性的，比对 `nums1` 里每个元素都在 `nums2` 里线性扫一遍（那样是 O(m*n)）要高效得多。

11.单调栈/0503.下一个更大元素II/0503.下一个更大元素II.md:
# 0503. 下一个更大元素 II

**题目描述**

给定一个循环数组 `nums`（最后一个元素的下一个元素是数组的第一个元素），返回 `nums` 中每个元素的下一个更大元素。数字 `x` 的下一个更大的元素是指在遍历中它后面（包括循环情况下从头开始遍历）第一个比它大的数字，如果不存在则输出 -1。

```
示例：
输入: nums = [1,2,1]
输出: [2,-1,2]
解释：
第一个 1 的下一个更大元素是 2
2 找不到下一个更大元素，输出 -1
第二个 1 由于是循环数组，向后循环到开头的 2，所以下一个更大元素是 2
```

## 思路

单调栈存下标，对应值从栈底到栈顶非递增。遍历 `2n` 次，用 `i%n` 模拟循环；遇更大值时弹栈填写答案。仅第一轮入栈，未匹配项保留 -1。

时间 O(n)，空间 O(n)。

## 代码

### Python

```python
class Solution:
    # 方法：nextGreaterElements；按题目要求处理输入并返回结果，核心算法见方法体。
    def nextGreaterElements(self, nums: list[int]) -> list[int]:
        n = len(nums)
        res = [-1] * n     # 默认-1，表示循环一圈没找到
        stack = []          # 栈中存下标，对应值从栈底到栈顶递减
        for i in range(2 * n):        # 遍历两倍长度模拟循环
            idx = i % n                # 映射回真实下标
            while stack and nums[idx] > nums[stack[-1]]:
                res[stack.pop()] = nums[idx]  # 结算
            if i < n:
                stack.append(idx)  # 仅第一轮入栈，避免重复
        return res
```

### C++

```cpp
class Solution {
public:
    // 方法：nextGreaterElements；按题目要求处理输入并返回结果，核心算法见方法体。
    vector<int> nextGreaterElements(vector<int>& nums) {
        int n = nums.size();
        vector<int> res(n, -1);   // 默认值-1，表示循环一圈也没找到更大元素
        stack<int> st;             // 栈中存下标，从栈底到栈顶对应值递减
        for (int i = 0; i < 2 * n; i++) {  // 遍历两倍长度模拟循环
            int idx = i % n;                // 取模映射回真实下标
            // 当前值比栈顶下标对应的值大，弹出并结算
            while (!st.empty() && nums[idx] > nums[st.top()]) {
                res[st.top()] = nums[idx];
                st.pop();
            }
            if (i < n) {
                st.push(idx); // 只在第一轮压入，避免重复入栈同一个下标
            }
        }
        return res;
    }
};
```


### Go

```go
// 方法：nextGreaterElements；按题目要求处理输入并返回结果，核心算法见方法体。
func nextGreaterElements(nums []int) []int {
    n := len(nums)
    res := make([]int, n)
    for i := range res {
        res[i] = -1 // 默认-1，表示循环一圈没找到
    }
    stack := make([]int, 0, n) // 栈中存下标
    for i := 0; i < 2*n; i++ { // 遍历两倍长度模拟循环
        idx := i % n             // 映射回真实下标
        for len(stack) > 0 && nums[idx] > nums[stack[len(stack)-1]] {
            top := stack[len(stack)-1]
            stack = stack[:len(stack)-1]
            res[top] = nums[idx] // 结算
        }
        if i < n {
            stack = append(stack, idx) // 仅第一轮入栈
        }
    }
    return res
}
```

## 总结

- 处理循环数组的通用技巧就是"遍历两倍长度 + 取模映射真实下标"，说白了本质上是虚拟地把数组延展成两份首尾相连，但又避免了真正复制数组带来的额外空间开销。
- 栈里必须存下标而不是值，因为最终结果要写回 `res[原下标]`，只有下标才能定位到原数组的具体位置。
- 这里有个关键的实现细节，就是"只在第一轮（`i < n`）的时候才压栈"，不然第二轮遍历的时候，同一个下标就会被重复压进去，造成结果出错或者冗余计算。
- 这道题跟 496 题的联系是：如果把"循环"这个条件去掉，这道题就退化成了对单个数组求下一个更大元素（也就是 496 题预处理 `nums2` 的那一步），循环数组只是在这个基础上把查找范围扩展了一下而已。

11.单调栈/0739.每日温度/0739.每日温度.md:
# 0739. 每日温度

**题目描述**

给定一个整数数组 `temperatures`，表示每天的气温，返回一个数组 `answer`，其中 `answer[i]` 表示对于第 `i` 天，下一个更高气温出现在几天之后。如果气温在这之后都不会升高，则该位置用 0 代替。

```
示例：
输入: temperatures = [73,74,75,71,69,72,76,73]
输出: [1,1,4,2,1,1,0,0]
解释：
第0天(73°)，下一个更高温度在第1天(74°)，间隔1天
第2天(75°)，下一个更高温度在第6天(76°)，间隔4天
第6天(76°)是全局最高，之后没有更高的，输出0
```

## 思路

- 单调栈：存未找到更暖日的下标，温度从栈底到栈顶非递增。当前温度更高时连续弹出 `j`，令 `answer[j]=i-j`，再将 `i` 入栈；剩余答案为 0。时间 O(n)，空间 O(n)。
- 暴力：每一天向右找首个更高温度。时间 O(n²)，辅助空间 O(1)，不计结果。

## 代码

### Python

```python
class Solution:
    # 方法：dailyTemperatures；按题目要求处理输入并返回结果，核心算法见方法体。
    def dailyTemperatures(self, temperatures: list[int]) -> list[int]:
        n = len(temperatures)
        answer = [0] * n          # 默认0，表示后面没有更高的
        stack = []                 # 栈中存下标，温度从栈底到栈顶递减
        for i, cur in enumerate(temperatures):
            # 当前温度比栈顶下标对应温度高，说明栈顶那天等到了更高温度
            while stack and cur > temperatures[stack[-1]]:
                j = stack.pop()
                answer[j] = i - j  # 结算：间隔天数
            stack.append(i)        # 当前下标入栈，等待被结算
        return answer
```

### C++

```cpp
class Solution {
public:
    // 方法：dailyTemperatures；按题目要求处理输入并返回结果，核心算法见方法体。
    vector<int> dailyTemperatures(vector<int>& temperatures) {
        int n = temperatures.size();
        vector<int> answer(n, 0);      // 默认0，表示后面没有更高的
        stack<int> st;                 // 栈中存下标，对应温度从栈底到栈顶递减
        for (int i = 0; i < n; i++) {
            // 当前温度比栈顶下标对应的温度高，说明栈顶那天等到了更高温度
            while (!st.empty() && temperatures[i] > temperatures[st.top()]) {
                int j = st.top();
                st.pop();
                answer[j] = i - j;     // 结算：间隔天数 = 当前下标 - 栈顶下标
            }
            st.push(i);                // 当前下标入栈，等待被后面更高的温度结算
        }
        return answer;
    }
};
```


### Go

```go
// 方法：dailyTemperatures；按题目要求处理输入并返回结果，核心算法见方法体。
func dailyTemperatures(temperatures []int) []int {
    n := len(temperatures)
    answer := make([]int, n)      // 默认0
    stack := make([]int, 0, n)    // 栈中存下标，温度从栈底到栈顶递减
    for i := 0; i < n; i++ {
        // 当前温度比栈顶下标对应温度高，弹出并结算
        for len(stack) > 0 && temperatures[i] > temperatures[stack[len(stack)-1]] {
            j := stack[len(stack)-1]
            stack = stack[:len(stack)-1] // 弹出栈顶
            answer[j] = i - j            // 结算间隔天数
        }
        stack = append(stack, i) // 当前下标入栈
    }
    return answer
}
```

## 总结

- 单调栈的本质说白了就是"延迟结算"：遇到还确定不了答案的元素，先压进栈里暂存着，等到未来某个元素能触发结算条件了（这里就是"比栈顶更大"），才一次性批量弹出计算，这样就避免了暴力法里的重复扫描。
- 这道题栈里维护的是下标而不是数值本身，因为最终答案得算下标差（也就是间隔天数），要是只存数值，位置信息就丢了。
- 判断"该入栈还是该弹栈"的关键，就在于比较新元素和栈顶元素的大小关系，这决定了栈该维护成什么单调性方向（递增栈是用来找更小值的，递减栈是用来找更大值的）。这道题要找的是"下一个更大元素"，所以用的是栈内自底向上非递增的写法（也就是说，找到更大值就弹栈）。
- 时间复杂度能从 O(n²) 降到 O(n)，关键就在于每个下标只会被压入和弹出各一次，总的操作次数是线性的。

12.图论/0127.单词接龙/0127.单词接龙.md:
# 127. 单词接龙

**题目描述**

给定两个单词 `beginWord` 和 `endWord`，以及一个字典 `wordList`。规则是：每次转换只能改变单词中的一个字母，并且每次转换得到的中间单词都必须存在于 `wordList` 中。求从 `beginWord` 转换到 `endWord` 的最短转换序列的**单词个数**（包含 `beginWord` 和 `endWord` 本身）。如果不存在这样的转换序列，返回 0。

```
示例：
输入: beginWord = "hit", endWord = "cog"
      wordList = ["hot","dot","dog","lot","log","cog"]
输出: 5
解释: 最短转换序列是 "hit" -> "hot" -> "dot" -> "dog" -> "cog"，共 5 个单词
```

```
示例：
输入: beginWord = "hit", endWord = "cog"
      wordList = ["hot","dot","dog","lot","log"]
输出: 0
解释: endWord "cog" 不在 wordList 中，无法转换
```

## 思路

BFS：单词为节点，相差一个字母即相邻。从 `beginWord` 分层搜索，枚举每位的 26 种替换，字典中未访问的词入队并立即标记。首次到达终点返回层数，包含起点；终点不在字典或不可达返回 0。

时间 O(NL²)，空间 O(NL)，N 为单词数，L 为词长，含字符串构造与哈希开销。

## 代码

### Python

```python
from collections import deque

class Solution:
    # 方法：ladderLength；按题目要求处理输入并返回结果，核心算法见方法体。
    def ladderLength(self, beginWord: str, endWord: str, wordList: list[str]) -> int:
        word_set = set(wordList)  # 单词表转哈希集合，便于 O(1) 查找
        if endWord not in word_set:
            return 0  # 终点不在字典里，不可能转换成功

        queue = deque([beginWord])
        word_set.discard(beginWord)  # 起点从候选集合移除，充当 visited 标记
        step = 1  # 序列长度从 1 开始，因为要把 beginWord 自己计入

        while queue:
            level_size = len(queue)  # 固定当前层的元素个数，实现按层扩展
            for _ in range(level_size):
                cur = queue.popleft()
                for i in range(len(cur)):  # 枚举单词的每一位
                    for c in "abcdefghijklmnopqrstuvwxyz":  # 枚举该位替换成的每个字母
                        if c == cur[i]:
                            continue  # 跳过原字母
                        next_word = cur[:i] + c + cur[i + 1:]  # 构造替换后的新单词
                        if next_word == endWord:
                            return step + 1  # 命中终点，返回长度
                        if next_word in word_set:
                            word_set.discard(next_word)  # 标记 visited
                            queue.append(next_word)         # 加入下一层队列
            step += 1  # 当前层处理完毕，进入下一层
        return 0  # 队列耗尽仍未到达终点，无法转换
```

### C++

```cpp
class Solution {
public:
    // 方法：ladderLength；按题目要求处理输入并返回结果，核心算法见方法体。
    int ladderLength(string beginWord, string endWord, vector<string>& wordList) {
        unordered_set<string> wordSet(wordList.begin(), wordList.end()); // 单词表转哈希集合，便于 O(1) 查找
        if (wordSet.find(endWord) == wordSet.end()) {
            return 0; // 终点不在字典里，不可能转换成功
        }

        queue<string> q;
        q.push(beginWord);
        wordSet.erase(beginWord); // 起点不需要再作为候选边，顺便充当 visited 标记
        int step = 1; // 序列长度从 1 开始，因为要把 beginWord 自己计入

        while (!q.empty()) {
            int levelSize = q.size(); // 固定当前层的元素个数，实现按层扩展
            for (int i = 0; i < levelSize; i++) {
                string cur = q.front();
                q.pop();
                for (int j = 0; j < (int)cur.size(); j++) { // 枚举单词的每一位
                    char origin = cur[j];
                    for (char c = 'a'; c <= 'z'; c++) { // 枚举该位替换成的每个字母
                        if (c == origin) continue; // 跳过原字母，没有变化不算一次转换
                        cur[j] = c;
                        if (cur == endWord) {
                            return step + 1; // 命中终点，返回长度
                        }
                        if (wordSet.count(cur)) {
                            wordSet.erase(cur); // 从候选集合移除，等同于标记 visited
                            q.push(cur);         // 加入下一层队列
                        }
                    }
                    cur[j] = origin; // 恢复原字母，继续枚举下一位
                }
            }
            step++; // 当前层处理完毕，进入下一层
        }
        return 0; // 队列耗尽仍未到达终点，无法转换
    }
};
```


### Go

```go
// 方法：ladderLength；按题目要求处理输入并返回结果，核心算法见方法体。
func ladderLength(beginWord string, endWord string, wordList []string) int {
    wordSet := make(map[string]bool) // 单词表转哈希集合，便于 O(1) 查找
    for _, w := range wordList {
        wordSet[w] = true
    }
    if !wordSet[endWord] {
        return 0 // 终点不在字典里，不可能转换成功
    }

    queue := []string{beginWord}
    delete(wordSet, beginWord) // 起点从候选集合移除，充当 visited 标记
    step := 1                  // 序列长度从 1 开始，因为要把 beginWord 自己计入

    for len(queue) > 0 {
        levelSize := len(queue) // 固定当前层的元素个数，实现按层扩展
        for i := 0; i < levelSize; i++ {
            cur := queue[0]
            queue = queue[1:]
            bytes := []byte(cur)
            for j := 0; j < len(bytes); j++ { // 枚举单词的每一位
                origin := bytes[j]
                for c := byte('a'); c <= 'z'; c++ { // 枚举该位替换成的每个字母
                    if c == origin {
                        continue // 跳过原字母
                    }
                    bytes[j] = c
                    next := string(bytes)
                    if next == endWord {
                        return step + 1 // 命中终点，返回长度
                    }
                    if wordSet[next] {
                        delete(wordSet, next)          // 标记 visited
                        queue = append(queue, next)    // 加入下一层队列
                    }
                }
                bytes[j] = origin // 恢复原字母，继续枚举下一位
            }
        }
        step++ // 当前层处理完毕，进入下一层
    }
    return 0 // 队列耗尽仍未到达终点，无法转换
}
```

## 总结

- 这道题的核心就是"隐式建图"：咱们不预先枚举所有单词对之间的边，而是在 BFS 扩展的时候，对当前单词的每一位尝试替换 26 个字母，动态判断是否存在到某个邻居单词的边，这样就省去了 O(N²) 级别的建图开销。
- 必须用 BFS 而不是 DFS，因为这道题求的是最短转换序列的长度，BFS 是按层扩散的，第一次到达终点的层数就是最短路径长度；而 DFS 只能找到某一条可行路径，没法保证是最短的，要保证最短就得穷举全部路径，代价是指数级的。
- 用哈希集合而不是数组来存 `wordList`，是为了把"新单词是否可达"的判断从 O(N) 降到 O(1)；而把已访问单词直接从哈希集合里删掉，就省去了单独维护一个 `visited` 集合的空间。
- 整体时间复杂度约 O(N × 26 × L²)，这里 26×L 是每个单词能枚举出的邻居数量上限，L² 来自构造新字符串和哈希计算的开销；空间复杂度 O(N)，用在哈希集合和 BFS 队列上。

