                    int ni = i + d[0], nj = j + d[1];
                    // 越界，或者相邻格子是水域，说明这条边暴露在外
                    if (ni < 0 || ni >= m || nj < 0 || nj >= n || grid[ni][nj] == 0) {
                        perimeter++;
                    }
                }
            }
        }
        return perimeter;
    }
};
```


### Go

```go
// 方法：islandPerimeter；按题目要求处理输入并返回结果，核心算法见方法体。
func islandPerimeter(grid [][]int) int {
    m, n := len(grid), len(grid[0])
    perimeter := 0
    dirs := [4][2]int{{-1, 0}, {1, 0}, {0, -1}, {0, 1}} // 上下左右四个方向

    for i := 0; i < m; i++ {
        for j := 0; j < n; j++ {
            if grid[i][j] != 1 { // 只处理陆地格子
                continue
            }
            for _, d := range dirs {
                ni, nj := i+d[0], j+d[1]
                // 越界，或者相邻格子是水域，说明这条边暴露在外
                if ni < 0 || ni >= m || nj < 0 || nj >= n || grid[ni][nj] == 0 {
                    perimeter++
                }
            }
        }
    }
    return perimeter
}
```

## 总结

- 岛屿周长说白了本质就是"所有陆地格子暴露在外的边数之和"，这个转化是解题的关键，把一个几何问题变成了逐格计数的问题。
- 方法一（双重循环统计）不需要递归，也不需要 `visited`，直接对每个陆地格子做四方向的边界/水域判断就行了，时间 O(mn)、空间 O(1)，是本题最简洁高效的做法。
- 方法二（DFS 遍历岛屿）思路上更"图论化"一点：碰到越界或水域就记一次周长，碰到已访问的陆地直接跳过不重复计数，本质上和方法一是等价的，只是多了 `visited` 数组和递归栈的开销。
- 那这两种方法怎么选呢？原则是：如果题目只需要统计跟遍历顺序无关的信息（就像本题这样），直接扫描更合适；但如果题目需要先明确岛屿的连通范围，再做进一步处理，比如统计岛屿数量、面积、区分多个岛屿，那 DFS/BFS 遍历会更自然一些。

12.图论/0684.冗余连接/0684.冗余连接.md:
# 684. 冗余连接

**题目描述**

给定一个无向图，它原本是一棵树（n 个节点，n-1 条边，无环、连通），现在多加了一条边，导致图中出现了一个环。`edges` 数组按顺序给出所有边（包括多余的那一条），要求找出这条可以删除、使图重新变成一棵树的边。如果有多个符合要求的答案，返回数组 `edges` 中最后出现的那一条。

```
示例：
输入: edges = [[1,2],[1,3],[2,3]]
输出: [2,3]
解释: 节点1、2、3原本应该构成一棵树，但1-2、1-3、2-3三条边形成了环，
     其中[2,3]是最后加入且导致成环的边，删除它后剩下[1,2]、[1,3]恰好构成一棵树
```

## 思路

并查集按输入顺序处理边：端点不同根则合并，同根则当前边闭环，返回该边；它是环中最后出现的边。

当前仅路径压缩：时间 O(n log n) 上界，空间 O(n)；再加按秩／大小合并，时间可为 O(nα(n))。

## 代码

### Python

```python
class Solution:
    # 方法：findRedundantConnection；按题目要求处理输入并返回结果，核心算法见方法体。
    def findRedundantConnection(self, edges: list[list[int]]) -> list[int]:
        n = len(edges)
        parent = list(range(n + 1))  # 节点编号从1开始，初始化每个节点的父节点是自己

        # 方法：find；按题目要求处理输入并返回结果，核心算法见方法体。
        def find(x: int) -> int:
            if parent[x] != x:
                parent[x] = find(parent[x])  # 路径压缩
            return parent[x]

        for u, v in edges:
            root_u, root_v = find(u), find(v)
            if root_u == root_v:
                return [u, v]  # 两端点已同根，这条边是多余边
            parent[root_u] = root_v  # 否则合并两个集合

        return []  # 理论上不会执行到这里
```

