var ufParent []int

// 方法：find；按题目要求处理输入并返回结果，核心算法见方法体。
func find(x int) int {
    if ufParent[x] != x {
        ufParent[x] = find(ufParent[x]) // 路径压缩
    }
    return ufParent[x]
}

// 尝试把除 skipIndex 外的所有边都union，能成功构成树则返回 true
// 方法：buildWithoutEdge；按题目要求处理输入并返回结果，核心算法见方法体。
func buildWithoutEdge(edges [][]int, n int, skipIndex int) bool {
    ufParent = make([]int, n+1)
    for i := 1; i <= n; i++ {
        ufParent[i] = i // 初始化
    }
    for i, e := range edges {
        if i == skipIndex {
            continue // 跳过被假设删除的边
        }
        u, v := e[0], e[1]
        ru, rv := find(u), find(v)
        if ru == rv {
            return false // 成环，假设失败
        }
        ufParent[ru] = rv
    }
    return true
}

// 方法：findRedundantDirectedConnection；按题目要求处理输入并返回结果，核心算法见方法体。
func findRedundantDirectedConnection(edges [][]int) []int {
    n := len(edges)
    parentOf := make([]int, n+1) // parentOf[v] 记录 v 当前的父节点
    earlierIdx, laterIdx := -1, -1

    for i, e := range edges {
        u, v := e[0], e[1]
        if parentOf[v] != 0 {
            for j := 0; j < i; j++ { // 找到较早给 v 赋父节点的边
                if edges[j][1] == v {
                    earlierIdx = j
                    break
                }
            }
            laterIdx = i
            break // v 入度为2，提前结束扫描
        }
        parentOf[v] = u
    }

    if laterIdx != -1 { // 存在入度为2的节点
        if buildWithoutEdge(edges, n, laterIdx) {
            return edges[laterIdx] // 删除较晚的边即可成树
        }
        return edges[earlierIdx] // 否则答案是较早的那条
    }

    // 不存在入度为2的节点，退化为纯环检测
    ufParent = make([]int, n+1)
    for i := 1; i <= n; i++ {
        ufParent[i] = i
    }
    for _, e := range edges {
        u, v := e[0], e[1]
        ru, rv := find(u), find(v)
        if ru == rv {
            return e // 第一条成环边即为答案
        }
        ufParent[ru] = rv
    }
    return nil // 题目保证有解，理论不会到达这里
}
```

## 总结

- 685 题比 684 题多了"方向"这个维度，导致异常模式从单一的"成环"分裂成两种互斥情况：某节点入度为2（多父节点冲突），或所有节点入度都合法但整体构成环（纯环结构）。
- 必须先扫描判断是否存在入度为2的节点，因为这种情况下候选答案是明确的两条边中的一条，不能直接套用684题"逐条union找第一条成环边"的方法，否则可能在同时存在入度冲突和环的场景下选错答案。
- 处理入度为2的节点时，优先假设删除较晚出现的那条边（符合"多个候选取最后出现"的要求），用并查集验证剩余边能否构成合法树；验证失败就说明较晚的边是树结构必需的，答案退化为较早的那条边。
- 排除入度为2的特殊情况后，剩下的纯环场景处理方式和684题完全一致：并查集逐条union，第一条导致两端点同根的边就是答案；整体时间复杂度 O(n)，空间复杂度 O(n)。

